def recruiter_stage_for_status(status: str) -> str:
    return RECRUITER_STAGE_BY_STATUS.get(str(status or "").strip(), "")


def recruiter_next_action_for_status(status: str) -> str:
    status = str(status or "").strip()
    if status in RECRUITER_NEXT_ACTION_BY_STATUS:
        return RECRUITER_NEXT_ACTION_BY_STATUS[status]
    if "resume" in status and "blocked" in status:
        return "retry_request_resume"
    if "resume" in status and "requested" in status:
        return "done_resume_requested"
    if "rejected" in status:
        return "done_skip_unsuitable"
    if "waiting" in status:
        return "wait_candidate_reply"
    if "blocked" in status:
        return "retry_or_manual_review"
    if "unclear" in status:
        return "wait_or_manual_review"
    return "review_next"


def is_ai_app_basic_conditions_position(context: dict | None, position_reply: dict | None = None) -> bool:
    context = context if isinstance(context, dict) else {}
    position_reply = position_reply if isinstance(position_reply, dict) else {}
    knowledge_base = context.get("companyKnowledgeBase") if isinstance(context.get("companyKnowledgeBase"), dict) else {}
    applicant = context.get("applicant") if isinstance(context.get("applicant"), dict) else {}
    texts = [
        context.get("appliedPosition"),
        applicant.get("appliedPosition"),
        knowledge_base.get("title"),
        position_reply.get("category"),
        position_reply.get("matched"),
    ]
    for raw in texts:
        compact = re.sub(r"\s+", "", str(raw or "")).lower()
        if not compact:
            continue
        if "ai" in compact and "应用开发" in compact:
            return True
        if "应用开发" in compact and ("实习" in compact or "工程师" in compact or "大模型" in compact):
            return True
    return False


def is_explicit_ai_app_basic_conditions_position(context: dict | None) -> bool:
    context = context if isinstance(context, dict) else {}
    applicant = context.get("applicant") if isinstance(context.get("applicant"), dict) else {}
    position_values = [
        context.get("appliedPosition"),
        applicant.get("appliedPosition"),
    ]
    allowed_positions = (
        "AI应用开发实习生",
        "AI应用开发工程师",
    )
    for raw in position_values:
        clean = clean_applied_position(str(raw or ""))
        compact = re.sub(r"\s+", "", clean).lower()
        if not compact:
            continue
        for allowed in allowed_positions:
            allowed_compact = re.sub(r"\s+", "", clean_applied_position(allowed)).lower()
            if compact == allowed_compact or allowed_compact in compact:
                return True
    return False


def recruiter_workflow_for_context(context: dict | None, status: str = "", payload: dict | None = None) -> str:
    context = context if isinstance(context, dict) else {}
    payload = payload if isinstance(payload, dict) else {}
    if status == "proactive_greeted" or payload.get("source") == "recommend":
        return "proactive_contact"
    position_reply = context.get("positionReply") if isinstance(context.get("positionReply"), dict) else {}
    knowledge_base = context.get("companyKnowledgeBase") if isinstance(context.get("companyKnowledgeBase"), dict) else {}
    screening = knowledge_base.get("screening") if isinstance(knowledge_base.get("screening"), dict) else {}
    if str(position_reply.get("initialCommonPhrase") or "").strip() and is_ai_app_basic_conditions_position(context, position_reply):
        return "basic_conditions_screening"
    if normalize_position_screening_questions(screening):
        return "position_skill_screening"
    if knowledge_base.get("enabled"):
        return "knowledge_answering"
    return "unconfigured_position_skip"


class AgentError(RuntimeError):
    pass


class PauseRequested(AgentError):
    pass


def timed_agent_stage(key: str, label: str):
    def decorator(func):
        @wraps(func)
        def wrapper(self, *args, **kwargs):
            measure = getattr(self, "measure_current_timing_stage", None)
            if not callable(measure):
                return func(self, *args, **kwargs)
            return measure(key, label, lambda: func(self, *args, **kwargs))

        return wrapper

    return decorator


class WebAgentService:
    def __init__(self) -> None:
        self.lock = threading.RLock()
        self.terminal: BrowserTerminal | None = None
        self.terminal_thread_id: int | None = None
        self.files = load_json(FILE_REGISTRY, [])
        self.events = load_json(EVENT_LOG, [])
        self.chat_states = load_json(CHAT_STATE_FILE, {})
        if not isinstance(self.chat_states, dict):
            self.chat_states = {}
        self.chat_memories = load_json(CHAT_MEMORY_FILE, {})
        if not isinstance(self.chat_memories, dict):
            self.chat_memories = {}
        self.common_phrase_cache = load_json(COMMON_PHRASE_CACHE_FILE, {})
        if not isinstance(self.common_phrase_cache, dict):
            self.common_phrase_cache = {}
        self.local_candidates: list[dict] = []
        self.pending_actions: dict[str, dict] = {}
        self.last_find_element_matches: list[dict] = []
        self.chat_monitor_signature = ""
        self.chat_monitor_unread_signature = ""
        self.chat_monitor_handled_unread_signature = ""
        self.chat_monitor_cooldown_until = 0.0
        self.chat_monitor_suggestions: list[dict] = []
        self.current_operation_timing: dict | None = None
        self.last_operation_timing: dict | None = None
        self.pause_requested = False
        self.pause_reason = ""
        self.pause_updated_at = 0.0
        # Runtime limits/guards. Previously these were hard-coded (e.g. 6 steps, dangerous-click confirmation).
        # Defaults here are permissive to avoid artificially limiting human-like/autonomous operation.
        self.max_steps = 30
        self.max_actions_per_step: int | None = 20
        self.require_confirm_dangerous_clicks = False
        self.require_confirm_send_message = False
        # Bulk-chat/campaign defaults (anti-abuse / anti-lockup)
        self.bulk_max_chats = 30
        self.bulk_delay_ms_range = (220, 520)
        self.bulk_stop_on_captcha = True
        self.bulk_personalize = False
        # Multi-round chat waiting knobs
        self.chat_wait_timeout_ms = 20000
        self.chat_wait_poll_ms = 800
        self.automation_speed_factor = 1.0
        self.automation_speed_multiplier = AUTOMATION_SPEED_MULTIPLIER
        self.proactive_task_lock = threading.Lock()

    def save_common_phrase_cache(self) -> None:
        save_json(COMMON_PHRASE_CACHE_FILE, self.common_phrase_cache)

    def get_common_phrase_cache(self, key: str = "basic_conditions") -> dict:
        cache = self.common_phrase_cache.get(key)
        return cache if isinstance(cache, dict) else {}

    def update_common_phrase_cache(self, key: str = "basic_conditions", **values) -> dict:
        cache = dict(self.get_common_phrase_cache(key))
        cache.update({
            **values,
            "accountId": AGENT_ACCOUNT_ID,
            "accountName": AGENT_ACCOUNT_NAME,
            "updatedAt": time.strftime("%Y-%m-%d %H:%M:%S"),
            "updatedAtTs": time.time(),
        })
        self.common_phrase_cache[key] = cache
        self.save_common_phrase_cache()
        return cache

    def clear_common_phrase_cache(self, key: str = "basic_conditions") -> None:
        if key in self.common_phrase_cache:
            self.common_phrase_cache.pop(key, None)
            self.save_common_phrase_cache()

    def _cached_box(self, value) -> dict:
        if not isinstance(value, dict):
            return {}
        try:
            x = float(value.get("x") or 0)
            y = float(value.get("y") or 0)
            width = float(value.get("width") or value.get("w") or 0)
            height = float(value.get("height") or value.get("h") or 0)
        except Exception:
            return {}
        if width <= 2 or height <= 2:
            return {}
        return {"x": x, "y": y, "width": width, "height": height}

    def click_cached_common_phrase_button(self, terminal: BrowserTerminal, key: str = "basic_conditions") -> dict:
        cache = self.get_common_phrase_cache(key)
        box = self._cached_box(cache.get("buttonBox"))
        if not box:
            return {"clicked": False, "reason": "no_cached_button"}
        page = terminal.current_page()
        viewport = page.viewport_size or {"width": 1280, "height": 720}
        if box["x"] < 0 or box["y"] < 0 or box["x"] > float(viewport.get("width", 1280)) or box["y"] > float(viewport.get("height", 720)):
            self.clear_common_phrase_cache(key)
            return {"clicked": False, "reason": "cached_button_out_of_view"}
        try:
            if terminal.humanize:
                terminal.pause_like_person("pre_action")
            x, y = target_box_inner_point(box)
            humanized_point_click(terminal, x, y, target_box=box)
            page.wait_for_timeout(random.randint(420, 820))
            opened = is_common_phrase_panel_open(terminal)
            if not opened:
                self.clear_common_phrase_cache(key)
            return {"clicked": bool(opened), "usedCache": True, "opened": bool(opened), "box": box}
        except Exception as error:
            self.clear_common_phrase_cache(key)
            return {"clicked": False, "usedCache": True, "error": safe_text(str(error), 160)}

    def click_cached_common_phrase_send(self, terminal: BrowserTerminal, phrase: str, item: dict | None = None, key: str = "basic_conditions") -> dict:
        cache = self.get_common_phrase_cache(key)
        send_box = self._cached_box(cache.get("sendBox"))
        row_box = self._cached_box((item or {}).get("rowBox")) or self._cached_box(item) or self._cached_box(cache.get("rowBox"))
        if not send_box or not row_box:
            return {"clicked": False, "reason": "no_cached_send"}
        page = terminal.current_page()
        try:
            hover_x = row_box["x"] + row_box["width"] * random.uniform(0.66, 0.82)
            hover_y = row_box["y"] + row_box["height"] * random.uniform(0.42, 0.58)
            move_cursor_like_person(
                terminal,
                hover_x,
                hover_y,
                duration_factor=random.uniform(0.18, 0.36),
                show_trail=False,
            )
            page.wait_for_timeout(random.randint(180, 360))
            adjusted_send_box = dict(send_box)
            cached_row = self._cached_box(cache.get("rowBox"))
            if cached_row:
                adjusted_send_box["y"] = send_box["y"] + ((row_box["y"] + row_box["height"] / 2) - (cached_row["y"] + cached_row["height"] / 2))
            x = adjusted_send_box["x"] + adjusted_send_box["width"] * random.uniform(0.42, 0.58)
            y = adjusted_send_box["y"] + adjusted_send_box["height"] * random.uniform(0.42, 0.58)
            humanized_point_click(terminal, x, y, target_box=adjusted_send_box)
            page.wait_for_timeout(random.randint(520, 980))
            return {
                "clicked": True,
                "found": True,
                "usedCache": True,
                "strategy": "cached_common_phrase_send",
                "label": "发送",
                "itemLabel": safe_text(str((item or {}).get("label") or phrase), 120),
                "x": round(adjusted_send_box["x"]),
                "y": round(adjusted_send_box["y"]),
                "w": round(adjusted_send_box["width"]),
                "h": round(adjusted_send_box["height"]),
                "rowBox": {
                    "x": round(row_box["x"]),
                    "y": round(row_box["y"]),
                    "w": round(row_box["width"]),
                    "h": round(row_box["height"]),
                },
            }
        except Exception as error:
            self.clear_common_phrase_cache(key)
            return {"clicked": False, "usedCache": True, "error": safe_text(str(error), 160)}

    def _operation_timing_timestamp(self, ts: float | None = None) -> str:
        return time.strftime("%Y-%m-%dT%H:%M:%S", time.localtime(ts or time.time()))

    def start_operation_timing(self, operation_type: str, message: str = "") -> dict:
        now = time.time()
        timing = {
            "id": str(uuid.uuid4()),
            "type": operation_type,
            "accountId": AGENT_ACCOUNT_ID,
            "accountName": AGENT_ACCOUNT_NAME,
            "status": "running",
            "message": safe_text(message, 180),
            "startedAt": self._operation_timing_timestamp(now),
            "startedAtMs": int(now * 1000),
            "finishedAt": "",
            "totalMs": 0,
            "stages": [],
            "stageStats": {},
            "stageStatsList": [],
            "counters": {},
        }
        self.current_operation_timing = timing
        self.last_operation_timing = timing
        return timing

    def finish_operation_timing(self, timing: dict | None, status: str = "success", error: str = "") -> dict | None:
        if not isinstance(timing, dict):
            return None
        now = time.time()
        timing["status"] = status
        timing["finishedAt"] = self._operation_timing_timestamp(now)
        timing["totalMs"] = max(0, int(now * 1000) - int(timing.get("startedAtMs") or int(now * 1000)))
        if error:
            timing["error"] = safe_text(error, 260)
        if self.current_operation_timing is timing:
            self.current_operation_timing = None
        self.last_operation_timing = timing
        return timing

    def refresh_operation_timing_runtime(self, timing: dict | None) -> dict | None:
        if not isinstance(timing, dict):
            return None
        if timing.get("status") == "running":
            now_ms = int(time.time() * 1000)
            timing["totalMs"] = max(0, now_ms - int(timing.get("startedAtMs") or now_ms))
        return timing

    def measure_current_timing_stage(self, key: str, label: str, worker):
        timing = self.current_operation_timing
        if not isinstance(timing, dict):
            return worker()
        started = time.time()
        try:
            result = worker()
            self.record_current_timing_stage(key, label, started, ok=True)
            return result
        except Exception as error:
            self.record_current_timing_stage(key, label, started, ok=False, error=str(error))
            raise

    def record_current_timing_stage(
        self,
        key: str,
        label: str,
        started: float,
        ok: bool = True,
        error: str = "",
        extra: dict | None = None,
    ) -> None:
        timing = self.current_operation_timing
        if not isinstance(timing, dict):
            return
        finished = time.time()
        duration_ms = max(0, int((finished - started) * 1000))
        label = safe_text(str(label or key or ""), 80)
        stages = timing.setdefault("stages", [])
        if not isinstance(stages, list):
            timing["stages"] = stages = []
        counters = timing.setdefault("counters", {})
        if not isinstance(counters, dict):
            timing["counters"] = counters = {}
        counters["totalStages"] = int(counters.get("totalStages") or 0) + 1
        stats = timing.setdefault("stageStats", {})
        if not isinstance(stats, dict):
            timing["stageStats"] = stats = {}
        stat = stats.setdefault(
            str(key or "unknown"),
            {
                "key": str(key or "unknown"),
                "label": label,
                "count": 0,
                "okCount": 0,
                "failedCount": 0,
                "totalMs": 0,
                "avgMs": 0.0,
                "minMs": duration_ms,
                "maxMs": duration_ms,
                "lastMs": 0,
                "lastAt": "",
            },
        )
        if not isinstance(stat, dict):
            stat = {
                "key": str(key or "unknown"),
                "label": label,
                "count": 0,
                "okCount": 0,
                "failedCount": 0,
                "totalMs": 0,
                "avgMs": 0.0,
                "minMs": duration_ms,
                "maxMs": duration_ms,
                "lastMs": 0,
                "lastAt": "",
            }
            stats[str(key or "unknown")] = stat
        count = int(stat.get("count") or 0) + 1
        total_ms = int(stat.get("totalMs") or 0) + duration_ms
        stat.update(
            {
                "label": label or stat.get("label") or str(key or "unknown"),
                "count": count,
                "okCount": int(stat.get("okCount") or 0) + (1 if ok else 0),
                "failedCount": int(stat.get("failedCount") or 0) + (0 if ok else 1),
                "totalMs": total_ms,
                "avgMs": round(total_ms / count, 2) if count else 0.0,
                "minMs": min(int(stat.get("minMs") or duration_ms), duration_ms),
                "maxMs": max(int(stat.get("maxMs") or duration_ms), duration_ms),
                "lastMs": duration_ms,
                "lastAt": self._operation_timing_timestamp(finished),
            }
        )
        timing["stageStatsList"] = sorted(
            (dict(value) for value in stats.values() if isinstance(value, dict)),
            key=lambda item: int(item.get("totalMs") or 0),
            reverse=True,
        )
        if len(stages) >= 1200:
            stages.pop(0)
            counters["trimmedStages"] = int(counters.get("trimmedStages") or counters.get("droppedStages") or 0) + 1
            counters["droppedStages"] = counters["trimmedStages"]
        stage = {
            "key": key,
            "label": label,
            "startedAt": self._operation_timing_timestamp(started),
            "finishedAt": self._operation_timing_timestamp(finished),
            "durationMs": duration_ms,
            "ok": bool(ok),
        }
        if error:
            stage["error"] = safe_text(error, 260)
        if isinstance(extra, dict):
            stage.update(extra)
        stages.append(stage)

    def close(self) -> None:
        with self.lock:
            terminal = self.terminal
            owner_thread_id = self.terminal_thread_id
            self.terminal = None
            self.terminal_thread_id = None
            if terminal and (owner_thread_id is None or owner_thread_id == threading.get_ident()):
                try:
                    terminal.__exit__(None, None, None)
                except Exception:
                    pass

    def close_current_thread_terminal(self) -> None:
        current_thread_id = threading.get_ident()
        with self.lock:
            if not self.terminal or self.terminal_thread_id != current_thread_id:
                return
            terminal = self.terminal
            self.terminal = None
            self.terminal_thread_id = None
            try:
                terminal.__exit__(None, None, None)
            except Exception:
                pass

    def get_terminal(self) -> BrowserTerminal:
        current_thread_id = threading.get_ident()
        with self.lock:
            if self.terminal is not None and self.terminal_thread_id != current_thread_id:
                # Playwright's sync API is bound to the thread that created it.
                # Drop stale references instead of reusing them across HTTP worker threads.
                self.terminal = None
                self.terminal_thread_id = None
            if self.terminal is None:
                terminal = BrowserTerminal(
                    AGENT_CDP_URL,
                    page_index=0,
                    auto_start=True,
                    visual_cursor=True,
                    humanize=True,
                    pace="normal",
                )
                self.terminal = terminal.__enter__()
                self.terminal.automation_speed_multiplier = self.automation_speed_multiplier
                self.terminal_thread_id = current_thread_id
                apply_automation_speed_multiplier(self.terminal)
            else:
                self.terminal.automation_speed_multiplier = self.automation_speed_multiplier
                apply_automation_speed_multiplier(self.terminal)
            return self.terminal

    def status(self) -> dict:
        operation_timing = self.refresh_operation_timing_runtime(self.current_operation_timing or self.last_operation_timing)
        busy = bool(self.current_operation_timing)
        connected = self.terminal is not None
        if busy:
            page = {"busy": True, "message": "智能体正在执行任务，暂时不读取浏览器状态"}
        else:
            page = {"message": "空闲；状态接口不再主动读取浏览器，避免页面查询卡住自动化服务。"}
        return {
            "connected": connected,
            "busy": busy,
            "accountId": AGENT_ACCOUNT_ID,
            "accountName": AGENT_ACCOUNT_NAME,
            "cdp": {
                "boss": AGENT_CDP_URL,
                "job51": JOB51_CDP_URL,
                "zhilian": ZHILIAN_CDP_URL,
            },
            "page": page,
            "hasApiKey": has_model_key(),
            "modelConfig": public_model_config(),
            "automationSpeedFactor": self.automation_speed_factor,
            "automationSpeedMultiplier": self.automation_speed_multiplier,
            "pause": self.pause_state(),
            "operationTiming": operation_timing,
            "files": self.files[-8:],
            "localCandidates": self.local_candidates[:8],
            "events": self.events[-20:],
        }

    def pause_state(self) -> dict:
        return {
            "paused": bool(self.pause_requested),
            "reason": self.pause_reason,
            "updatedAt": self.pause_updated_at,
        }

    def set_pause(self, paused: bool, reason: str = "") -> dict:
        self.pause_requested = bool(paused)
        self.pause_reason = safe_text(str(reason or ("用户手动暂停" if paused else "")), 120)
        self.pause_updated_at = time.time()
        try:
            self.add_event("system", "已暂停执行" if paused else "已恢复执行")
        except Exception:
            pass
        return self.pause_state()

    def check_pause(self) -> None:
        if self.pause_requested:
            reason = self.pause_reason or "用户手动暂停"
            raise PauseRequested(f"任务已暂停：{reason}")

    def set_options(self, options: dict) -> dict:
        with self.lock:
            terminal = self.get_terminal()
            if "cursor" in options:
                terminal.visual_cursor = bool(options["cursor"])
            if "humanize" in options:
                terminal.humanize = bool(options["humanize"])
            pace = str(options.get("pace") or terminal.pace).strip().lower()
            if pace in PACE_PRESETS:
                terminal.pace = pace
            if "speedFactor" in options or "automationSpeedFactor" in options:
                speed_value = options.get("speedFactor", options.get("automationSpeedFactor"))
                self.automation_speed_factor = normalize_automation_speed_factor(
                    speed_value,
                    self.automation_speed_factor,
                )
                self.automation_speed_multiplier = AUTOMATION_BASE_SPEED_MULTIPLIER * self.automation_speed_factor
                terminal.automation_speed_multiplier = self.automation_speed_multiplier
                apply_automation_speed_multiplier(terminal)
            elif "speedMultiplier" in options or "automationSpeedMultiplier" in options:
                speed_value = options.get("speedMultiplier", options.get("automationSpeedMultiplier"))
                self.automation_speed_multiplier = normalize_automation_speed_multiplier(
                    speed_value,
                    self.automation_speed_multiplier,
                )
                self.automation_speed_factor = self.automation_speed_multiplier / AUTOMATION_BASE_SPEED_MULTIPLIER
                terminal.automation_speed_multiplier = self.automation_speed_multiplier
                apply_automation_speed_multiplier(terminal)
            if "maxSteps" in options:
                self.max_steps = max(1, int(options["maxSteps"]))
            if "maxActionsPerStep" in options:
                raw = options["maxActionsPerStep"]
                if raw in {None, "", 0, "0", False}:
                    self.max_actions_per_step = None
                else:
                    self.max_actions_per_step = max(1, int(raw))
            if "confirmDangerousClicks" in options:
                self.require_confirm_dangerous_clicks = bool(options["confirmDangerousClicks"])
            if "confirmSendMessage" in options:
                self.require_confirm_send_message = bool(options["confirmSendMessage"])
            if "bulkMaxChats" in options:
                self.bulk_max_chats = max(1, int(options["bulkMaxChats"]))
            if "bulkDelayMsMin" in options or "bulkDelayMsMax" in options:
                low = int(options.get("bulkDelayMsMin") or self.bulk_delay_ms_range[0])
                high = int(options.get("bulkDelayMsMax") or self.bulk_delay_ms_range[1])
                if low < 0:
                    low = 0
                if high < low:
                    high = low
                self.bulk_delay_ms_range = (low, high)
            if "bulkStopOnCaptcha" in options:
                self.bulk_stop_on_captcha = bool(options["bulkStopOnCaptcha"])
            if "bulkPersonalize" in options:
                self.bulk_personalize = bool(options["bulkPersonalize"])
            if "chatWaitTimeoutMs" in options:
                self.chat_wait_timeout_ms = max(1000, int(options["chatWaitTimeoutMs"]))
            if "chatWaitPollMs" in options:
                self.chat_wait_poll_ms = max(200, int(options["chatWaitPollMs"]))
            return {
                "cursor": terminal.visual_cursor,
                "humanize": terminal.humanize,
                "pace": terminal.pace,
                "speedFactor": self.automation_speed_factor,
                "speedMultiplier": self.automation_speed_multiplier,
                "maxSteps": self.max_steps,
                "maxActionsPerStep": self.max_actions_per_step,
                "confirmDangerousClicks": self.require_confirm_dangerous_clicks,
                "confirmSendMessage": self.require_confirm_send_message,
                "bulkMaxChats": self.bulk_max_chats,
                "bulkDelayMsMin": self.bulk_delay_ms_range[0],
                "bulkDelayMsMax": self.bulk_delay_ms_range[1],
                "bulkStopOnCaptcha": self.bulk_stop_on_captcha,
                "bulkPersonalize": self.bulk_personalize,
                "chatWaitTimeoutMs": self.chat_wait_timeout_ms,
                "chatWaitPollMs": self.chat_wait_poll_ms,
            }

    def wait_for_chat_change(self, terminal: BrowserTerminal, previous_signature: str) -> bool:
        """Wait until chat context signature changes.

        Used for multi-round conversations so we don't keep responding without new user input.
        """

        deadline = time.time() + (self.chat_wait_timeout_ms / 1000.0)
        while time.time() < deadline:
            context = self.read_chat_context(terminal)
            current = chat_context_signature(context.get("recentText", ""))
            if current and current != previous_signature:
                return True
            terminal.current_page().wait_for_timeout(self.chat_wait_poll_ms)
        return False

    def observe(self) -> dict:
        with self.lock:
            terminal = self.get_terminal()
            context = terminal.collect_page_context(limit=90)
            context["fileInputs"] = self.collect_file_inputs(terminal)
            return context

    def collect_file_inputs(self, terminal: BrowserTerminal) -> list[dict]:
        page = terminal.current_page()
        try:
            return page.locator("input[type=file]").evaluate_all(
                """els => els.map((el, index) => ({
                  index: index + 1,
                  id: el.id || "",
                  name: el.name || "",
                  accept: el.getAttribute("accept") || "",
                  multiple: !!el.multiple,
                  visible: !!(el.offsetWidth || el.offsetHeight || el.getClientRects().length)
                }))"""
            )
        except Exception:
            return []

    def save_uploaded_file(self, filename: str, content: bytes) -> dict:
        safe_name = sanitize_filename(filename)
        if not safe_name:
            raise AgentError("文件名为空，无法保存。")
        day_dir = UPLOAD_DIR / time.strftime("%Y-%m-%d")
        day_dir.mkdir(parents=True, exist_ok=True)
        target = unique_path(day_dir / safe_name)
        target.write_bytes(content)
        item = {
            "id": f"file_{int(time.time() * 1000)}",
            "name": safe_name,
            "path": str(target),
            "size": len(content),
            "time": time.strftime("%Y-%m-%d %H:%M:%S"),
        }
        self.files.append(item)
        save_json(FILE_REGISTRY, self.files[-200:])
        self.add_event("file", f"已保存文件：{safe_name}")
        return item

    def add_event(self, kind: str, text: str, extra: dict | None = None) -> None:
        created_at = time.strftime("%Y-%m-%d %H:%M:%S")
        item = {
            "accountId": AGENT_ACCOUNT_ID,
            "accountName": AGENT_ACCOUNT_NAME,
            "date": created_at[:10],
            "time": time.strftime("%H:%M:%S"),
            "createdAt": created_at,
            "kind": kind,
            "text": text,
            "extra": extra or {},
        }
        self.events.append(item)
        save_json(EVENT_LOG, self.events[-2000:])

    def save_chat_states(self) -> None:
        now = time.time()
        compact: dict[str, dict] = {}
        for key, item in self.chat_states.items():
            if not isinstance(item, dict):
                continue
            updated_at = float(item.get("updatedAtTs") or 0)
            if updated_at and now - updated_at > CHAT_STATE_TTL_SECONDS:
                continue
            compact[str(key)] = item
        self.chat_states = compact
        save_json(CHAT_STATE_FILE, compact)

    def get_chat_state(self, key: str) -> dict:
        if not key:
            return {}
        item = self.chat_states.get(key)
        return item if isinstance(item, dict) else {}

    def set_chat_state(self, key: str, status: str, **fields) -> dict:
        if not key:
            return {}
        item = dict(self.get_chat_state(key))
        item.update(fields)
        item["status"] = status
        stage = recruiter_stage_for_status(status)
        if stage:
            item["stage"] = stage
        item["agentNextAction"] = str(item.get("agentNextAction") or recruiter_next_action_for_status(status))
        if status == "proactive_greeted":
            item.setdefault("agentWorkflow", "proactive_contact")
        if item.get("agentWorkflow") or stage or item.get("agentNextAction"):
            item["agentState"] = {
                "workflow": item.get("agentWorkflow") or "",
                "stage": stage,
                "status": status,
                "nextAction": item.get("agentNextAction") or recruiter_next_action_for_status(status),
                "updatedAt": time.strftime("%Y-%m-%d %H:%M:%S"),
            }
        item["updatedAt"] = time.strftime("%Y-%m-%d %H:%M:%S")
        item["updatedAtTs"] = time.time()
        self.chat_states[key] = item
        self.save_chat_states()
        return item

    def find_proactive_contact_origin(
        self,
        candidate_name: str = "",
        applied_position: str = "",
        candidate_label: str = "",
        identity: dict | None = None,
    ) -> dict:
        identity = identity if isinstance(identity, dict) else {}
        candidate_name = safe_text(str(candidate_name or identity.get("candidateName") or ""), 60)
        applied_position = safe_text(str(applied_position or identity.get("appliedPosition") or ""), 120)
        label_compact = compact_conversation_label(candidate_label or str(identity.get("listLabel") or ""))
        best: dict = {}
        best_score = 0

        for state_key, state in self.chat_states.items():
            if not isinstance(state, dict):
                continue
            status = str(state.get("status") or "")
            if status != "proactive_greeted":
                continue
            source = str(state.get("source") or "")
            if source not in {"recommend", "51job_recommend", "zhilian_recommend", ""} and not str(state_key).startswith(
                ("proactive|", "job51_proactive|", "zhilian_proactive|")
            ):
                continue

            state_label = str(state.get("candidateLabel") or "")
            state_name = safe_text(
                str(state.get("candidateName") or recruiter_candidate_name_from_label(state_label)),
                60,
            )
            state_position = safe_text(str(state.get("appliedPosition") or state.get("targetPosition") or ""), 120)
            state_label_compact = compact_conversation_label(state_label)
            state_position_compact = re.sub(r"\s+", "", state_position)

            identity_match = bool(
                identity.get("identityKey")
                and str(identity.get("identityKey")) == str(state.get("candidateIdentityKey") or "")
            )
            name_match = bool(
                candidate_name
                and state_name
                and (
                    candidate_name == state_name
                    or (len(candidate_name) >= 2 and len(state_name) >= 2 and (candidate_name in state_name or state_name in candidate_name))
                )
            )
            position_match = False
            if applied_position and state_position:
                try:
                    position_match = recommend_position_matches(applied_position, state_position) or recommend_position_matches(
                        state_position, applied_position
                    )
                except Exception:
                    position_match = re.sub(r"\s+", "", applied_position) == state_position_compact
            if not position_match and state_position_compact and label_compact:
                position_match = state_position_compact in label_compact

            label_match = bool(
                label_compact
                and state_label_compact
                and len(label_compact) >= 12
                and len(state_label_compact) >= 12
                and (label_compact in state_label_compact or state_label_compact in label_compact)
            )

            if not (identity_match or label_match or (name_match and position_match)):
                continue

            score = 0
            if identity_match:
                score += 120
            if name_match:
                score += 80
            if position_match:
                score += 70
            if label_match:
                score += 40
            if score > best_score:
                best_score = score
                best = {
                    "matched": True,
                    "stateKey": str(state_key),
                    "score": score,
                    "candidateName": state_name,
                    "targetPosition": state_position,
                    "candidateLabel": safe_text(state_label, 180),
                    "greetedAt": state.get("updatedAt") or "",
                    "greetedAtTs": state.get("updatedAtTs") or 0,
                    "source": state.get("source") or "recommend",
                }

        return best

    def mark_proactive_contact_replied(self, origin: dict, status: str, payload: dict) -> None:
        state_key = str((origin or {}).get("stateKey") or "")
        if not state_key:
            return
        state = dict(self.get_chat_state(state_key))
        if not state or str(state.get("status") or "") != "proactive_greeted":
            return
        now_ts = time.time()
        state.update({
            "replyDetected": True,
            "replyStatus": status,
            "replyDetectedAt": time.strftime("%Y-%m-%d %H:%M:%S"),
            "replyDetectedAtTs": now_ts,
            "replyCandidateName": payload.get("candidateName") or state.get("candidateName") or "",
            "replyAppliedPosition": payload.get("appliedPosition") or state.get("appliedPosition") or "",
            "replyCandidateIdentityKey": payload.get("candidateIdentityKey") or "",
            "replyCandidateLabel": payload.get("candidateLabel") or "",
        })
        self.chat_states[state_key] = state

    def set_recruiter_basic_state(
        self,
        conversation_key: str,
        candidate_label: str,
        status: str,
        context: dict | None = None,
        **fields,
    ) -> dict:
        candidate_label = safe_text(str(candidate_label or ""), 180)
        candidate_name = recruiter_candidate_name_from_label(candidate_label)
        identity = build_recruiter_candidate_identity(context or {}, candidate_label, conversation_key)
        payload = dict(fields)
        payload.setdefault("candidateLabel", candidate_label)
        if candidate_name:
            payload.setdefault("candidateName", candidate_name)
        payload.setdefault("candidateIdentity", identity)
        if identity.get("identityKey"):
            payload.setdefault("candidateIdentityKey", identity.get("identityKey"))
        if identity.get("appliedPosition"):
            payload.setdefault("appliedPosition", identity.get("appliedPosition"))
        if identity.get("lastMessageSignature"):
            payload.setdefault("lastMessageSignature", identity.get("lastMessageSignature"))
        messages = (context or {}).get("messages") if isinstance(context, dict) else []
        if isinstance(messages, list) and messages:
            payload.setdefault("recentMessages", [
                {
                    "sender": safe_text(str(message.get("sender") or ""), 20),
                    "time": safe_text(str(message.get("time") or ""), 40),
                    "status": safe_text(str(message.get("status") or ""), 40),
                    "text": safe_text(str(message.get("text") or ""), 500),
                    "rawText": safe_text(str(message.get("rawText") or message.get("text") or ""), 600),
                }
                for message in messages[-80:]
                if isinstance(message, dict) and str(message.get("text") or "").strip()
            ])
        last_other = (context or {}).get("lastOtherMessage") if isinstance(context, dict) else {}
        if isinstance(last_other, dict) and last_other.get("text"):
            payload.setdefault("lastOther", safe_text(str(last_other.get("text") or ""), 500))
        review = (context or {}).get("conversationReview") if isinstance(context, dict) else {}
        if isinstance(review, dict) and review:
            payload.setdefault("conversationReview", compact_candidate_conversation_review(review))
        workflow = recruiter_workflow_for_context(context, status, payload)
        next_action = recruiter_next_action_for_status(status)
        payload.setdefault("agentWorkflow", workflow)
        payload.setdefault("agentNextAction", next_action)
        payload.setdefault("agentState", {
            "workflow": workflow,
            "stage": recruiter_stage_for_status(status),
            "status": status,
            "nextAction": next_action,
            "updatedAt": time.strftime("%Y-%m-%d %H:%M:%S"),
        })
        if status != "proactive_greeted":
            proactive_origin = self.find_proactive_contact_origin(
                candidate_name=str(payload.get("candidateName") or identity.get("candidateName") or ""),
                applied_position=str(payload.get("appliedPosition") or identity.get("appliedPosition") or ""),
                candidate_label=candidate_label,
                identity=identity,
            )
            if proactive_origin.get("matched"):
                payload.setdefault("proactiveOrigin", True)
                payload.setdefault("proactiveSource", proactive_origin.get("source") or "recommend")
                payload.setdefault("proactiveStateKey", proactive_origin.get("stateKey") or "")
                payload.setdefault("proactiveGreetedAt", proactive_origin.get("greetedAt") or "")
                payload.setdefault("proactiveGreetedAtTs", proactive_origin.get("greetedAtTs") or 0)
                payload.setdefault("proactiveTargetPosition", proactive_origin.get("targetPosition") or "")
                self.mark_proactive_contact_replied(proactive_origin, status, payload)
        keys: list[str] = []
        if conversation_key:
            keys.append(str(conversation_key))
        candidate_key = recruiter_basic_candidate_state_key(candidate_label, identity=identity)
        if candidate_key and candidate_key not in keys:
            keys.append(candidate_key)
        if identity.get("identityKey"):
            identity_state_key = "recruiter_identity_" + str(identity.get("identityKey"))
            if identity_state_key not in keys:
                keys.append(identity_state_key)
        updated: dict = {}
        for key in keys:
            updated = self.set_chat_state(key, status, **payload)
        append_recruiter_decision_log({
            "conversationKey": conversation_key,
            "stateKeys": keys,
            "candidateLabel": candidate_label,
            "candidateName": payload.get("candidateName") or "",
            "appliedPosition": payload.get("appliedPosition") or "",
            "status": status,
            "stage": recruiter_stage_for_status(status),
            "workflow": workflow,
            "nextAction": next_action,
            "screening": payload.get("screening") if isinstance(payload.get("screening"), dict) else {},
            "conversationReview": payload.get("conversationReview") if isinstance(payload.get("conversationReview"), dict) else {},
            "knowledgeAnswer": payload.get("knowledgeAnswer") or "",
            "lastScreening": payload.get("lastScreening") or "",
            "lastOther": payload.get("lastOther") or "",
        })
        return updated

    def pending_recruiter_basic_candidates(self, limit: int = 8) -> list[dict]:
        pending_statuses = {"basic_conditions_opened_unsent", "basic_conditions_needs_resend"}
        items: list[dict] = []
        seen: set[str] = set()
        for key, state in self.chat_states.items():
            if not isinstance(state, dict) or state.get("status") not in pending_statuses:
                continue
            label = safe_text(str(state.get("candidateLabel") or ""), 180)
            name = safe_text(str(state.get("candidateName") or recruiter_candidate_name_from_label(label)), 40)
            identity_data = state.get("candidateIdentity") if isinstance(state.get("candidateIdentity"), dict) else {}
            unique_key = (
                str(state.get("candidateIdentityKey") or "")
                or str(identity_data.get("identityKey") or "")
                or compact_conversation_label(label)
                or str(key)
            )
            if not unique_key or unique_key in seen:
                continue
            seen.add(unique_key)
            items.append({
                "key": str(key),
                "status": str(state.get("status") or ""),
                "candidateLabel": label,
                "candidateName": name,
                "candidateIdentity": identity_data,
                "candidateIdentityKey": str(state.get("candidateIdentityKey") or ""),
                "appliedPosition": safe_text(str(state.get("appliedPosition") or ""), 80),
                "lastMessageSignature": safe_text(str(state.get("lastMessageSignature") or ""), 60),
                "updatedAtTs": float(state.get("updatedAtTs") or 0),
            })
        items.sort(key=lambda item: item.get("updatedAtTs") or 0)
        return items[: max(1, int(limit or 1))]

    @timed_agent_stage("verify_basic_conditions_sent", "检查基础话术发送结果")
    def verify_basic_conditions_sent_in_current_chat(self, terminal: BrowserTerminal, phrase: str) -> dict:
        try:
            terminal.current_page().wait_for_timeout(random.randint(700, 1150))
        except Exception:
            pass
        context = self.read_chat_context(terminal)
        screening = analyze_basic_condition_screening(context.get("messages", []), phrase)
        verified = screening.get("status") != "not_asked"
        return {
            "verified": bool(verified),
            "context": context,
            "screening": screening,
        }

    @timed_agent_stage("send_basic_conditions_with_verification", "发送基础话术并验证")
    def send_basic_conditions_with_verification(
        self,
        terminal: BrowserTerminal,
        phrase: str,
        max_attempts: int = CHAT_SEND_MAX_ATTEMPTS,
    ) -> tuple[dict, dict]:
        attempts: list[dict] = []
        send_result: dict = {}
        verification: dict = {}
        for attempt in range(1, max(1, int(max_attempts or CHAT_SEND_MAX_ATTEMPTS)) + 1):
            send_result = self.send_recruiter_common_phrase(
                terminal,
                phrase=phrase,
                phrase_key="basic_conditions",
                target_candidate="",
            )
            if send_result.get("blocked"):
                attempts.append({"attempt": attempt, "send": send_result, "verification": {}})
                continue
            verification = self.verify_basic_conditions_sent_in_current_chat(terminal, phrase)
            attempts.append({"attempt": attempt, "send": send_result, "verification": verification})
            if verification.get("verified"):
                send_result["attempt"] = attempt
                send_result["attempts"] = attempts
                send_result["verification"] = verification
                return send_result, verification
        send_result = dict(send_result or {})
        send_result["blocked"] = True
        send_result["attempts"] = attempts
        send_result["verification"] = verification
        send_result["message"] = "已尝试发送基础情况常用语，但聊天记录里没有确认出现该消息。"
        return send_result, verification

    def save_chat_memories(self) -> None:
        now = time.time()
        compact: dict[str, dict] = {}
        for key, item in self.chat_memories.items():
            if not isinstance(item, dict):
                continue
            updated_at = float(item.get("updatedAtTs") or 0)
            if updated_at and now - updated_at > CHAT_MEMORY_TTL_SECONDS:
                continue
            compact[str(key)] = item
        self.chat_memories = compact
        save_json(CHAT_MEMORY_FILE, compact)

    def get_chat_memory(self, key: str) -> dict:
        if not key:
            return {}
        item = self.chat_memories.get(key)
        return item if isinstance(item, dict) else {}

    def refresh_chat_memory(self, context: dict, key: str | None = None, opened_label: str | None = None) -> dict:
        conversation_key = str(key or context.get("conversationKey") or "")
        if not conversation_key:
            return {}
        previous = dict(self.get_chat_memory(conversation_key))
        memory = build_chat_memory(previous, context, opened_label=opened_label)
        memory["updatedAt"] = time.strftime("%Y-%m-%d %H:%M:%S")
        memory["updatedAtTs"] = time.time()
        self.chat_memories[conversation_key] = memory
        self.save_chat_memories()
        return compact_chat_memory(memory)

    def latest_file(self) -> dict | None:
        return self.files[-1] if self.files else None

    def remember_local_file(self, path_text: str) -> dict:
        path = Path(path_text).expanduser().resolve()
        if not path.exists() or not path.is_file():
            raise AgentError(f"本地文件不存在：{path}")
        item = {
            "id": f"local_{int(time.time() * 1000)}",
            "name": path.name,
            "path": str(path),
            "size": path.stat().st_size,
            "time": time.strftime("%Y-%m-%d %H:%M:%S"),
            "source": "local_scan",
        }
        self.files.append(item)
        save_json(FILE_REGISTRY, self.files[-200:])
        self.add_event("file", f"已设为当前文件：{path.name}")
        return item

    def scan_local_resumes(self, query: str = "", limit: int = 24) -> list[dict]:
        candidates = scan_resume_candidates(query=query, limit=limit)
        self.local_candidates = candidates
        self.add_event("file", f"本地扫描到 {len(candidates)} 个候选文件")
        return candidates

    def chat(self, message: str, auto: bool = True, max_steps: int | None = None) -> dict:
        message = message.strip()
        if not message:
            raise AgentError("请输入你想让智能顾问完成的任务。")

        with self.lock:
            self.check_pause()
            terminal = self.get_terminal()
            self.apply_message_options(terminal, message)

            trace: list[dict] = []
            builtin = self.try_builtin_task(terminal, message, trace)
            if builtin:
                self.add_event("chat", builtin["reply"])
                return builtin

            if not has_model_key():
                raise AgentError("还没有配置模型 API Key。已知任务我可以用内置执行器处理；开放式智能网页操作仍需要模型配置。")

            enriched_task = self.enrich_task_with_files(message)
            final_reply = ""
            done = False
            pending_action = None

            required_rounds = parse_required_chat_rounds(enriched_task)
            last_chat_signature = ""
            if required_rounds > 1:
                try:
                    last_chat_signature = chat_context_signature(self.read_chat_context(terminal).get("recentText", ""))
                except Exception:
                    last_chat_signature = ""

            step_limit = int(max_steps) if max_steps is not None else int(self.max_steps)
            for step in range(1, step_limit + 1):
                self.check_pause()
                completed_before_step = count_completed_chat_rounds(trace) if required_rounds > 1 else 0
                context = terminal.collect_page_context(limit=90)
                context["fileInputs"] = self.collect_file_inputs(terminal)
                related = get_related_memory(terminal.memory, context.get("url", ""))
                step_task = build_step_task(enriched_task, trace, step, step_limit)

                self.add_event("observe", f"第 {step} 步：观察页面")
                model_context = compact_context_for_model(context, enriched_task, trace)
                plan = ask_agent_model_for_actions(step_task, model_context, terminal.active_role, related)
                actions = normalize_agent_actions(plan.get("actions", []), limit=self.max_actions_per_step)
                thought = plan.get("thought") or plan.get("summary") or ""

                step_record = {
                    "step": step,
                    "thought": thought,
                    "actions": [format_action(action) for action in actions],
                    "results": [],
                }
                trace.append(step_record)

                if not actions:
                    final_reply = thought or "模型没有给出可执行动作，我先停下来。"
                    break

                for action in actions:
                    self.check_pause()
                    recovered = self.recover_model_action(terminal, action, message)
                    if recovered:
                        action = recovered
                    # Resolve placeholder targets produced by page tools.
                    if isinstance(action, dict):
                        kind2 = str(action.get("action") or "").lower()
                        if kind2 in {"click", "fill", "upload"}:
                            raw_target = str(action.get("target") or action.get("query") or "").strip()
                            fixed = resolve_index_placeholder(raw_target, self.last_find_element_matches)
                            if fixed != raw_target:
                                action = {**action, "target": fixed}
                    result = self.execute_action(terminal, action)
                    step_record["results"].append(result)
                    if result.get("confirmRequired"):
                        final_reply = result["message"]
                        pending_action = result.get("pendingAction")
                        done = True
                        break
                    if result.get("blocked"):
                        if is_recruiter_basic_screening_task(message):
                            target_candidate = extract_recruiter_screen_candidate_name(message)
                            batch_count = extract_recruiter_screen_batch_count(message)
                            if should_scan_recent_contacts_for_basic_screening(message) and not target_candidate:
                                fallback = self.screen_recent_recruiter_basic_contacts(
                                    terminal,
                                    max_contacts=batch_count,
                                )
                            else:
                                fallback = self.screen_recruiter_basic_conditions(
                                    terminal,
                                    open_unreplied=should_open_unreplied_for_basic_screening(message),
                                    target_candidate=target_candidate,
                                    max_attempts=batch_count,
                                )
                            final_reply = fallback.get("message") or "已切换到招聘端基础条件筛选流程。"
                            pending_action = fallback.get("pendingAction")
                            step_record["results"].append({
                                "message": "通用网页规划失败，已切换到招聘端“基础条件筛选”专用流程。",
                                "fallback": True,
                                "candidate": fallback.get("candidate"),
                                "screening": fallback.get("screening"),
                            })
                            done = True
                            break
                        if is_recruiter_unsuitable_task(message):
                            target_candidate = extract_recruiter_unsuitable_candidate_name(message)
                            fallback = self.mark_recruiter_candidate_unsuitable(
                                terminal,
                                confirmed=False,
                                open_unreplied=False,
                                target_candidate=target_candidate,
                            )
                            final_reply = fallback.get("message") or "已切换到招聘端“不合适”专用流程。"
                            pending_action = fallback.get("pendingAction")
                            step_record["results"].append({
                                "message": "通用网页规划失败，已切换到招聘端“不合适”专用流程。",
                                "fallback": True,
                                "candidate": fallback.get("candidate"),
                            })
                            done = True
                            break
                        if is_recruiter_resume_request_task(message) or looks_like_recruiter_resume_request(message):
                            target_candidates = extract_recruiter_request_candidate_names(message)
                            batch_count = extract_recruiter_batch_count(message)
                            if len(target_candidates) > 1:
                                fallback = self.request_resume_for_named_candidates(terminal, target_candidates)
                            elif batch_count > 1:
                                fallback = self.request_resume_for_unreplied_candidates(terminal, batch_count)
                            else:
                                target_candidate = extract_recruiter_request_candidate_name(message)
                                fallback = self.request_resume_from_recruiter_conversation(
                                    terminal,
                                    confirmed=False,
                                    open_unreplied=not bool(target_candidate),
                                    target_candidate=target_candidate,
                                )
                            final_reply = fallback.get("message") or "已切换到招聘端求简历流程。"
                            pending_action = fallback.get("pendingAction")
                            step_record["results"].append({
                                "message": "通用网页规划失败，已切换到招聘端“求简历”专用流程。",
                                "fallback": True,
                                "candidate": fallback.get("candidate"),
                            })
                            done = True
                            break
                        if is_auto_reply_command(message):
                            fallback = self.auto_reply_chat_once(auto_send=("本地" in message and "自动发送" in message), force=True)
                            final_reply = fallback.get("reply") or fallback.get("message") or "已切换到聊天自动回复流程。"
                            pending_action = fallback.get("pendingAction")
                            step_record["results"].append({
                                "message": "通用网页规划失败，已切换到专用聊天自动回复流程。",
                                "fallback": True,
                            })
                            done = True
                            break
                        final_reply = result["message"]
                        done = True
                        break
                    if result.get("done"):
                        if required_rounds > 1:
                            completed = count_completed_chat_rounds(trace)
                            if completed < required_rounds:
                                final_reply = f"已完成对话 {completed}/{required_rounds} 轮，继续下一轮。"
                                done = False
                                break
                        final_reply = result["message"]
                        done = True
                        break

                # Multi-round chat: after we successfully send a message, wait for the other side to reply.
                if not done and required_rounds > 1:
                    completed_after_step = count_completed_chat_rounds(trace)
                    if completed_after_step > completed_before_step:
                        try:
                            current_signature = chat_context_signature(self.read_chat_context(terminal).get("recentText", ""))
                        except Exception:
                            current_signature = last_chat_signature
                        changed = self.wait_for_chat_change(terminal, current_signature or last_chat_signature)
                        if not changed:
                            final_reply = (
                                f"已发送第 {completed_after_step}/{required_rounds} 轮消息，正在等待对方回复。"
                                "对方回复后你再让我继续，我会进入下一轮。"
                            )
                            done = True
                        else:
                            try:
                                last_chat_signature = chat_context_signature(self.read_chat_context(terminal).get("recentText", ""))
                            except Exception:
                                pass

                memory_entry = {
                    "time": time.strftime("%Y-%m-%d %H:%M:%S"),
                    "url": context.get("url", ""),
                    "title": context.get("title", ""),
                    "role": get_role_name(terminal.roles, terminal.active_role),
                    "task": message,
                    "agentStep": step,
                    "thought": thought,
                    "actions": actions,
                    "confirmed": auto,
                    "result": "done" if done else "executed",
                    "afterUrl": terminal.current_page().url,
                    "afterTitle": terminal.current_page().title(),
                }
                append_memory(terminal.memory, memory_entry)

                if done:
                    break
                terminal.current_page().wait_for_timeout(random.randint(320, 420))

            if not final_reply:
                final_reply = "我已经执行到当前阶段。你可以继续给我下一步指令，或者让我观察页面状态。"

            self.add_event("chat", final_reply)
            return {
                "reply": final_reply,
                "trace": trace,
                "pendingAction": pending_action,
                "files": self.files[-8:],
                "page": {
                    "title": terminal.current_page().title(),
                    "url": terminal.current_page().url,
                },
            }

    def create_pending_action(self, action: dict, label: str) -> dict:
        token = f"confirm_{int(time.time() * 1000)}_{os.urandom(4).hex()}"
        item = {
            "token": token,
            "action": action,
            "label": label,
            "url": self.get_terminal().current_page().url,
            "time": time.strftime("%Y-%m-%d %H:%M:%S"),
        }
        self.pending_actions[token] = item
        return {
            "token": token,
            "label": label,
            "url": item["url"],
            "time": item["time"],
        }

    def pending_send_confirmation(self) -> dict | None:
        for item in reversed(list(self.pending_actions.values())):
            action = item.get("action") if isinstance(item, dict) else None
            if isinstance(action, dict) and action.get("_pendingType") == "send_message":
                return {
                    "token": item.get("token"),
                    "label": item.get("label"),
                    "url": item.get("url"),
                    "time": item.get("time"),
                }
        return None

    def confirm_action(self, token: str) -> dict:
        with self.lock:
            item = self.pending_actions.pop(token, None)
            if not item:
                raise AgentError("这个确认请求不存在或已经执行过。")
            terminal = self.get_terminal()
            action = dict(item["action"])
            action["_confirmed"] = True
            result = self.execute_action(terminal, action)
            if action.get("_pendingType") == "send_message":
                conversation_key = str(action.get("_conversationKey") or "")
                last_other_signature = str(action.get("_lastOtherSignature") or "")
                terminal.current_page().wait_for_timeout(random.randint(650, 1100))
                unread_state = read_unread_badge_state(terminal)
                unread_signature = str(unread_state.get("signature") or "")
                if unread_signature:
                    self.chat_monitor_unread_signature = unread_signature
                    self.chat_monitor_handled_unread_signature = unread_signature
                context = self.read_chat_context(terminal)
                if conversation_key:
                    context["conversationKey"] = conversation_key
                    context["memory"] = self.refresh_chat_memory(context, conversation_key)
                signature = chat_context_signature(context.get("recentText", ""))
                if signature:
                    self.chat_monitor_signature = signature
                if conversation_key:
                    self.set_chat_state(
                        conversation_key,
                        "sent",
                        lastOtherSignature=last_other_signature or context.get("lastOtherSignature", ""),
                        sentAt=time.strftime("%Y-%m-%d %H:%M:%S"),
                    )
                self.chat_monitor_cooldown_until = time.time() + 8.0
            response = {
                "reply": result.get("message", "已执行确认动作。"),
                "result": result,
                "page": {
                    "title": terminal.current_page().title(),
                    "url": terminal.current_page().url,
                },
            }
            if result.get("confirmRequired"):
                response["pendingAction"] = result.get("pendingAction")
            return response

    def cancel_action(self, token: str) -> dict:
        with self.lock:
            item = self.pending_actions.pop(token, None)
            if not item:
                return {"reply": "这次确认请求已经取消或不存在。"}
            action = item.get("action") if isinstance(item, dict) else {}
            if isinstance(action, dict) and action.get("_pendingType") == "request_candidate_resume_final":
                try:
                    close_recruiter_resume_confirm_tooltip(self.get_terminal())
                except Exception:
                    pass
            if isinstance(action, dict) and action.get("_pendingType") == "mark_candidate_unsuitable_final":
                try:
                    close_recruiter_unsuitable_confirm_dialog(self.get_terminal())
                except Exception:
                    pass
            if isinstance(action, dict) and action.get("_conversationKey"):
                self.set_chat_state(
                    str(action.get("_conversationKey")),
                    "cancelled",
                    lastOtherSignature=str(action.get("_lastOtherSignature") or ""),
                )
            return {
                "reply": f"已取消：{safe_text(str(item.get('label') or ''), 80)}",
                "cancelled": True,
            }

    def recover_model_action(self, terminal: BrowserTerminal, action: dict, message: str) -> dict | None:
        kind = str(action.get("action") or "").lower()
        reason = str(action.get("reason") or action.get("value") or "").lower()
        if is_recruiter_unsuitable_task(message):
            if kind in {"click", "done", "stop"}:
                target_candidate = extract_recruiter_unsuitable_candidate_name(message)
                return {
                    "action": "recruiter_mark_unsuitable",
                    "openUnreplied": False,
                    "targetCandidate": target_candidate,
                }
        if is_recruiter_basic_screening_task(message):
            if kind in {"click", "done", "stop"}:
                target_candidate = extract_recruiter_screen_candidate_name(message)
                batch_count = extract_recruiter_screen_batch_count(message)
                if (
                    should_process_all_unread_for_basic_screening(message)
                    or (should_open_unreplied_for_basic_screening(message) and batch_count > 1 and not target_candidate)
                ):
                    return {
                        "action": "recruiter_process_unread_all_positions",
                        "maxTotal": batch_count,
                    }
                return {
                    "action": "recruiter_process_current_position",
                    "targetCandidate": target_candidate,
                    "maxAttempts": batch_count,
                }
        if is_recruiter_common_phrase_task(message):
            if kind in {"click", "done", "stop"}:
                target_candidate = extract_recruiter_common_phrase_candidate_name(message)
                return {
                    "action": "recruiter_send_company_info",
                    "targetCandidate": target_candidate,
                }
        if is_recruiter_resume_request_task(message) or looks_like_recruiter_resume_request(message):
            if kind in {"click", "done", "stop"}:
                target_candidate = extract_recruiter_request_candidate_name(message)
                return {
                    "action": "recruiter_request_resume",
                    "openUnreplied": not bool(target_candidate),
                    "targetCandidate": target_candidate,
                }
        if kind in {"done", "stop"} and is_resume_upload_task(message):
            if any(word in reason for word in ("路径", "file", "pdf", "简历", "upload", "文件")):
                file_path = self.resolve_action_file("")
                return {"action": "upload", "target": "file", "value": file_path}
        if kind == "click":
            target = str(action.get("target") or action.get("query") or "")
            if is_resume_upload_task(message) and any(word in target for word in ("选择简历", "选择文件", "上传")):
                file_path = self.resolve_action_file("")
                return {"action": "upload", "target": "file", "value": file_path}
        return None

    @timed_agent_stage("route_builtin_task", "识别任务/进入内置流程")
    def try_builtin_task(self, terminal: BrowserTerminal, message: str, trace: list[dict]) -> dict | None:
        lowered = message.lower()
        if is_recruiter_proactive_contact_task(message):
            result = self.proactive_contact_recommended_candidates(
                terminal,
                target_position=extract_recruiter_target_position(message) or "应用技术经理（工业涂料领域）",
                max_total=extract_recruiter_batch_count(message) or 10,
                dry_run=("预览" in message or "只看" in message or "dry" in lowered),
            )
            trace.append({
                "step": len(trace) + 1,
                "thought": "用户要求在推荐牛人里主动联系候选人，已切换为招聘端主动联系 functioncall。",
                "actions": ["recruiter_proactive_contact_recommended_candidates"],
            })
            return {
                "reply": result.get("message") or "主动联系任务已完成。",
                "trace": trace,
                "files": self.files[-8:],
                "page": {
                    "title": terminal.current_page().title(),
                    "url": terminal.current_page().url,
                },
                "state": result.get("state"),
                "results": result.get("results"),
            }
        if is_recruiter_basic_screening_task(message):
            target_candidate = extract_recruiter_screen_candidate_name(message)
            batch_count = extract_recruiter_screen_batch_count(message)
            if False and should_watch_recent_contacts_for_basic_screening(message) and not target_candidate:
                result = self.screen_recent_recruiter_contacts_with_followup_watch(
                    terminal,
                    max_contacts=extract_recruiter_recent_watch_count(message),
                    idle_seconds=extract_recruiter_recent_watch_idle_seconds(message),
                )
                return {
                    "reply": result.get("message") or "已处理最近联系人并进入后续回复观察流程。",
                    "pendingAction": result.get("pendingAction"),
                    "trace": trace,
                    "files": self.files[-8:],
                    "page": {
                        "title": terminal.current_page().title(),
                        "url": terminal.current_page().url,
                    },
                    "state": result.get("state"),
                    "results": result.get("results"),
                    "followups": result.get("followups"),
                }
            target_position = extract_recruiter_target_position(message)
            date_scope = extract_recruiter_date_scope(message)
            if (
                (should_process_all_unread_for_basic_screening(message) and not target_candidate)
                or (should_open_unreplied_for_basic_screening(message) and not target_candidate)
            ):
                result = self.screen_all_recruiter_unread_basic_conditions(
                    terminal,
                    max_total=batch_count if batch_count > 1 else 80,
                    target_position=target_position,
                    date_scope=date_scope,
                )
                return {
                    "reply": result.get("message") or "已处理所有未读招聘消息。",
                    "pendingAction": result.get("pendingAction"),
                    "trace": trace,
                    "files": self.files[-8:],
                    "page": {
                        "title": terminal.current_page().title(),
                        "url": terminal.current_page().url,
                    },
                    "state": result.get("state"),
                    "results": result.get("results"),
                }
            if False and should_scan_recent_contacts_for_basic_screening(message) and not target_candidate:
                result = self.screen_recent_recruiter_basic_contacts(
                    terminal,
                    max_contacts=batch_count,
                )
                return {
                    "reply": result.get("message") or "已处理最近联系人基础条件筛选流程。",
                    "pendingAction": result.get("pendingAction"),
                    "trace": trace,
                    "files": self.files[-8:],
                    "page": {
                        "title": terminal.current_page().title(),
                        "url": terminal.current_page().url,
                    },
                    "state": result.get("state"),
                    "results": result.get("results"),
                }
            if False and should_open_unreplied_for_basic_screening(message) and batch_count > 1 and not target_candidate:
                result = self.screen_all_recruiter_unread_basic_conditions(
                    terminal,
                    max_total=batch_count,
                    target_position=target_position,
                    date_scope=date_scope,
                )
                return {
                    "reply": result.get("message") or "已批量处理未回复招聘消息。",
                    "pendingAction": result.get("pendingAction"),
                    "trace": trace,
                    "files": self.files[-8:],
                    "page": {
                        "title": terminal.current_page().title(),
                        "url": terminal.current_page().url,
                    },
                    "state": result.get("state"),
                    "results": result.get("results"),
                }
            result = self.screen_recruiter_basic_conditions(
                terminal,
                open_unreplied=False,
                target_candidate=target_candidate,
                max_attempts=batch_count,
            )
            return {
                "reply": result.get("message") or "已处理基础条件筛选流程。",
                "pendingAction": result.get("pendingAction"),
                "trace": trace,
                "files": self.files[-8:],
                "page": {
                    "title": terminal.current_page().title(),
                    "url": terminal.current_page().url,
                },
                "state": result.get("state"),
                "candidate": result.get("candidate"),
                "screening": result.get("screening"),
            }
        if is_recruiter_common_phrase_task(message):
            target_candidate = extract_recruiter_common_phrase_candidate_name(message)
            result = self.execute_action(terminal, {
                "action": "recruiter_send_company_info",
                "targetCandidate": target_candidate,
            })
            trace.append({
                "step": len(trace) + 1,
                "thought": "用户要发送公司/岗位基本情况，已切换为招聘端业务 functioncall。",
                "actions": ["recruiter_send_company_info"],
            })
            return {
                "reply": result.get("message") or "已处理公司情况发送流程。",
                "pendingAction": result.get("pendingAction"),
                "trace": trace,
                "files": self.files[-8:],
                "page": {
                    "title": terminal.current_page().title(),
                    "url": terminal.current_page().url,
                },
                "state": result.get("state"),
                "candidate": result.get("candidate"),
            }
        if is_recruiter_unsuitable_task(message):
            target_candidate = extract_recruiter_unsuitable_candidate_name(message)
            result = self.mark_recruiter_candidate_unsuitable(
                terminal,
                confirmed=False,
                open_unreplied=False,
                target_candidate=target_candidate,
            )
            return {
                "reply": result.get("message") or "已处理不合适流程。",
                "pendingAction": result.get("pendingAction"),
                "trace": trace,
                "files": self.files[-8:],
                "page": {
                    "title": terminal.current_page().title(),
                    "url": terminal.current_page().url,
                },
                "state": result.get("state"),
                "candidate": result.get("candidate"),
            }
        if is_recruiter_resume_request_task(message) or looks_like_recruiter_resume_request(message):
            target_candidates = extract_recruiter_request_candidate_names(message)
            batch_count = extract_recruiter_batch_count(message)
            if len(target_candidates) > 1:
                result = self.request_resume_for_named_candidates(terminal, target_candidates)
            elif batch_count > 1:
                result = self.request_resume_for_unreplied_candidates(terminal, batch_count)
            else:
                target_candidate = extract_recruiter_request_candidate_name(message)
                result = self.request_resume_from_recruiter_conversation(
                    terminal,
                    confirmed=False,
                    open_unreplied=not bool(target_candidate),
                    target_candidate=target_candidate,
                )
            return {
                "reply": result.get("message") or "已处理求简历流程。",
                "pendingAction": result.get("pendingAction"),
                "trace": trace,
                "files": self.files[-8:],
                "page": {
                    "title": terminal.current_page().title(),
                    "url": terminal.current_page().url,
                },
                "state": result.get("state"),
                "candidate": result.get("candidate"),
                "results": result.get("results"),
            }
        if is_auto_reply_command(message):
            result = self.auto_reply_chat_once(auto_send=("本地" in message and "自动发送" in message), force=True)
            return {
                "reply": result.get("reply") or result.get("message") or "已处理自动回复监听。",
                "pendingAction": result.get("pendingAction"),
                "trace": trace,
                "files": self.files[-8:],
                "page": result.get("page") or {
                    "title": terminal.current_page().title(),
                    "url": terminal.current_page().url,
                },
            }
        if is_chat_resume_send_task(message):
            result = self.send_chat_resume_from_current_conversation(terminal, confirmed=False)
            return {
                "reply": result.get("message") or "已处理发送简历流程。",
                "pendingAction": result.get("pendingAction"),
                "trace": trace,
                "files": self.files[-8:],
                "page": {
                    "title": terminal.current_page().title(),
                    "url": terminal.current_page().url,
                },
                "state": result.get("state"),
            }

        if "boss" in lowered and any(word in message for word in ("挨个", "逐个", "批量", "群发", "群聊", "全聊", "跟所有人")):
            return self.boss_bulk_chat(terminal, message, trace)

        if not is_resume_upload_task(message):
            return None

        file_path = self.resolve_action_file(extract_windows_path(message) or "")
        file_name = Path(file_path).name

        trace.append({
            "step": 1,
            "thought": "这是上传简历类任务，使用内置执行器直接寻找文件输入框，避免系统级文件选择弹窗。",
            "actions": [f"select file {file_name}"],
            "results": [{"message": f"已选择文件：{file_path}"}],
        })

        terminal.current_page().wait_for_timeout(random.randint(120, 180))
        upload_result = self.smart_upload_to_page(terminal, file_path)
        trace.append({
            "step": 2,
            "thought": "后端直接设置页面中的 file input，不需要用户在系统文件窗口里手动选择。",
            "actions": [f"upload file = {file_path}"],
            "results": [upload_result],
        })

        terminal.current_page().wait_for_timeout(random.randint(450, 650))
        follow = self.try_click_followup_button(terminal)
        if follow:
            trace.append({
                "step": 3,
                "thought": "上传后发现页面上有可能继续解析/检测的按钮，自动推进下一步。",
                "actions": [follow["action"]],
                "results": [{"message": follow["message"]}],
            })
            terminal.current_page().wait_for_timeout(random.randint(550, 800))

        context = terminal.collect_page_context(limit=90)
        body = context.get("bodyTextPreview", "")
        summary = safe_text(body, 500) if body else "页面已更新，但没有读取到明显结果文本。"
        reply = f"我已经把 {file_name} 上传到当前页面了。{follow['message'] if follow else ''}\n\n当前页面状态：{summary}"
        return {
            "reply": reply.strip(),
            "trace": trace,
            "files": self.files[-8:],
            "page": {
                "title": terminal.current_page().title(),
                "url": terminal.current_page().url,
            },
        }

    def boss_bulk_chat(self, terminal: BrowserTerminal, message: str, trace: list[dict]) -> dict:
        """Semi-generic bulk chat runner.

        Assumptions:
        - User has already opened BOSS chat/message list page and filtered to the people to contact.
        - We only use the existing element cache (buttons/links) to iterate; we do NOT hardcode selectors.
        """

        # Parse optional placeholders from user message.
        job = ""
        m = re.search(r"岗位\s*[=:：]\s*([^\n\r]+)", message)
        if m:
            job = m.group(1).strip()

        auto_send = "自动发送" in message or "不需要确认" in message
        personalize = self.bulk_personalize or ("个性化" in message) or ("更智能" in message)
        rules = load_boss_chat_rules()

        trace.append({
            "step": 1,
            "thought": "进入批量聊天模式：遍历当前页面左侧会话/联系人列表，按规则分类并生成不同话术。",
            "actions": [
                f"load rules from {BOSS_RULES_FILE.name}",
                f"auto_send={auto_send}",
                f"max={self.bulk_max_chats}",
            ],
            "results": [],
        })

        visited: set[str] = set()
        sent = 0
        skipped = 0

        for i in range(self.bulk_max_chats):
            self.check_pause()
            context = terminal.collect_page_context(limit=120)
            body = str(context.get("bodyTextPreview") or "")
            if self.bulk_stop_on_captcha and any(word in body for word in ("验证码", "安全验证", "请完成验证")):
                return {
                    "reply": "检测到页面出现安全验证/验证码，我先停止批量聊天以避免触发风控。",
                    "trace": trace,
                    "page": {"title": context.get("title"), "url": context.get("url")},
                }

            # Pick a plausible conversation/contact entry from cached elements.
            candidates: list[tuple[int, str, str, int]] = []
            for item in terminal.cache:
                if item.kind not in {"link", "button"}:
                    continue
                label = (item.label or "").strip()
                if not label:
                    continue
                name, href = normalize_contact_label(label)
                if any(bad in label for bad in ("发送", "提交", "删除", "支付", "付款", "发布", "确认")):
                    continue
                key = href or name or label
                if key in visited:
                    continue
                # Prefer items that look like chat threads (have an href with chat-ish path)
                score = 0
                if href:
                    score += 10
                    if any(word in href.lower() for word in ("chat", "message", "im", "dialog")):
                        score += 10
                if name:
                    score += 2
                candidates.append((item.index, name or label, key, score))

            if not candidates:
                break

            # Deterministic but higher-score first
            candidates.sort(key=lambda t: (-t[3], t[0]))
            idx, label, key, _score = candidates[0]
            visited.add(key)

            step_no = len(trace) + 1
            trace.append({
                "step": step_no,
                "thought": f"打开会话并按规则分类：{label}",
                "actions": [f"click {idx}", "observe"],
                "results": [],
            })

            # Open conversation.
            open_result = self.execute_action(terminal, {"action": "click", "target": str(idx)})
            trace[-1]["results"].append(open_result)
            if open_result.get("blocked"):
                skipped += 1
                continue

            terminal.current_page().wait_for_timeout(random.randint(*self.bulk_delay_ms_range))
            chat_context = self.read_chat_context(terminal)
            applied_position = str(chat_context.get("appliedPosition") or "")
            position_reply = chat_context.get("positionReply") if isinstance(chat_context.get("positionReply"), dict) else {}
            if position_reply.get("template"):
                category = str(position_reply.get("category") or "position")
                template = str(position_reply.get("template") or "")
            else:
                category, template = classify_boss_chat(chat_context, rules)
            base_text = template.replace("{job}", job or applied_position or "岗位")
            text = base_text
            if personalize and has_model_key():
                try:
                    text = ask_agent_model_for_message(
                        category=category,
                        template=base_text,
                        context=chat_context,
                        job=job or applied_position or "",
                    ) or base_text
                except Exception:
                    text = base_text

            # Fill draft.
            try:
                filled_label = self.smart_fill(terminal, "聊天", text)
                trace[-1]["results"].append({"message": f"分类={category}；已填写草稿：{safe_text(filled_label, 80)}"})
            except Exception as error:
                trace[-1]["results"].append({"blocked": True, "message": f"填写失败：{error}"})
                skipped += 1
                continue

            if not auto_send or self.require_confirm_send_message:
                pending = self.create_send_confirmation()
                trace[-1]["results"].append({"confirmRequired": True, "pendingAction": pending, "message": "已生成并填入草稿，等待你确认发送。"})
                return {
                    "reply": "已为当前会话生成并填入不同话术草稿，等待你确认发送（确认后可继续下一位）。",
                    "trace": trace,
                    "pendingAction": pending,
                    "page": {"title": chat_context.get("title"), "url": chat_context.get("url")},
                }

            # Auto send.
            send_action = find_send_action(terminal)
            send_result = self.execute_action(terminal, send_action)
            trace[-1]["results"].append(send_result)
            if send_result.get("blocked"):
                skipped += 1
            else:
                sent += 1

            terminal.current_page().wait_for_timeout(random.randint(*self.bulk_delay_ms_range))

        return {
            "reply": f"批量聊天已结束：已处理 {len(visited)} 个条目，自动发送 {sent}，跳过/失败 {skipped}。",
            "trace": trace,
            "page": {
                "title": terminal.current_page().title(),
                "url": terminal.current_page().url,
            },
        }

    def smart_upload_to_page(self, terminal: BrowserTerminal, file_path: str) -> dict:
        page = terminal.current_page()
        inputs = page.locator("input[type=file]")
        count = inputs.count()
        if count <= 0:
            raise AgentError("当前页面没有找到 file input，无法绕开系统文件选择窗口上传。")

        preferred = None
        for index in range(count):
            item = inputs.nth(index)
            label = describe_file_input(item)
            if any(word in label.lower() for word in ("resume", "简历", "pdf", "file")):
                preferred = item
                break
        locator = preferred or inputs.first
        locator.set_input_files(file_path, timeout=10000)
        self.add_event("action", f"已上传文件：{Path(file_path).name}")
        return {"message": f"已上传文件：{Path(file_path).name}"}

    def try_click_followup_button(self, terminal: BrowserTerminal) -> dict | None:
        context = terminal.collect_page_context(limit=90)
        keywords = ("开始解析", "解析简历", "开始检测", "检测", "匹配", "分析", "提交解析")
        for item in terminal.cache:
            if item.kind != "button":
                continue
            label = item.label
            if any(keyword in label for keyword in keywords) and (
                (not self.require_confirm_dangerous_clicks) or (not is_dangerous(label))
            ):
                if terminal.humanize:
                    terminal.pause_like_person("pre_action")
                    highlight_target(item.locator)
                humanized_locator_click(terminal, item.locator)
                if terminal.humanize:
                    terminal.pause_like_person("post_action")
                message = f"已点击后续按钮：{safe_text(label, 80)}"
                self.add_event("action", message)
                return {"action": f"click {label}", "message": message}
        return None

    def apply_message_options(self, terminal: BrowserTerminal, message: str) -> None:
        lower = message.lower()
        if "慢一点" in message or "慢速" in message or "slow" in lower:
            terminal.pace = "slow"
        elif "快一点" in message or "快速" in message or "fast" in lower:
            terminal.pace = "fast"
        if "关闭鼠标" in message:
            terminal.visual_cursor = False
        if "显示鼠标" in message or "可视化" in message:
            terminal.visual_cursor = True
        if "关闭拟人" in message:
            terminal.humanize = False
        if "拟人" in message or "像真人" in message:
            terminal.humanize = True

    def enrich_task_with_files(self, message: str) -> str:
        if mentions_file(message) and not contains_windows_path(message):
            latest = self.latest_file()
            if latest:
                return (
                    f"{message}\n"
                    f"可用文件：{latest['name']}，fileId={latest['id']}，本地绝对路径={latest['path']}。"
                )
            candidates = self.scan_local_resumes(query=message, limit=8)
            if candidates:
                lines = [
                    f"{item['name']} | 本地绝对路径={item['path']} | 修改时间={item['mtimeText']}"
                    for item in candidates[:5]
                ]
                return (
                    f"{message}\n"
                    "用户授权你在常用目录中扫描本地简历候选文件。"
                    "如果用户没有指定具体文件，请选择候选列表中最像简历且最近修改的一份，不要再要求用户提供路径。\n"
                    "候选文件：\n" + "\n".join(lines)
                )
        return message

    @timed_agent_stage("execute_action", "执行页面动作")
    def execute_action(self, terminal: BrowserTerminal, action: dict) -> dict:
        self.check_pause()
        kind = str(action.get("action") or "").lower()
        target = str(action.get("target") or action.get("query") or "").strip()
        value = str(action.get("value") or "").strip()

        try:
            if kind == "observe_page_summary":
                context = terminal.collect_page_context(limit=90)
                context["fileInputs"] = self.collect_file_inputs(terminal)
                compact = compact_context_for_model(context, target or value)
                return {
                    "message": f"Observed compact page summary: {compact.get('title', '')}",
                    "context": compact,
                }

            if kind == "find_element":
                matches = find_elements_for_query(terminal, target or value)
                self.last_find_element_matches = matches
                return {
                    "message": f"Found {len(matches)} matching element(s).",
                    "matches": matches,
                }

            if kind == "verify_result":
                check_text = value or target
                page_text = safe_eval(terminal.current_page(), "() => document.body ? document.body.innerText : ''") or ""
                matched = bool(check_text) and check_text.lower() in page_text.lower()
                return {
                    "message": "Verification matched." if matched else "Verification did not match yet.",
                    "matched": matched,
                    "expected": check_text,
                    "textPreview": safe_text(page_text, 500),
                }

            if kind == "recover_from_error":
                context = terminal.collect_page_context(limit=90)
                context["fileInputs"] = self.collect_file_inputs(terminal)
                compact = compact_context_for_model(context, target or value)
                return {
                    "message": "Recovered by refreshing compact observation.",
                    "context": compact,
                }

            if kind == "chat_read_context":
                context = self.read_chat_context(terminal)
                return {"message": context["summary"], "context": context}

            if kind == "chat_load_history":
                rounds = int(value or target or CHAT_HISTORY_SCROLL_ROUNDS)
                history = self.load_chat_history(terminal, max_rounds=max(1, min(20, rounds)))
                context = self.read_chat_context(terminal, history=history)
                return {
                    "message": f"已尝试向上加载聊天历史：{history.get('rounds', 0)} 轮，读取约 {len(history.get('text', ''))} 字。",
                    "history": history,
                    "context": context,
                }

            if kind == "chat_find_input":
                _, label = find_best_editable(terminal, target or "聊天")
                return {"message": f"已找到聊天输入框：{safe_text(label, 80)}"}

            if kind == "chat_fill_draft":
                draft = value or str(action.get("message") or action.get("draft") or action.get("text") or "").strip()
                label = self.smart_fill(terminal, target or "聊天", draft)
                if self.require_confirm_send_message or not is_local_browser_page(terminal):
                    pending = self.create_send_confirmation()
                    return {
                        "confirmRequired": True,
                        "pendingAction": pending,
                        "message": f"已把回复草稿填入：{safe_text(label, 80)}。需要你确认后再发送。",
                    }
                click_result = click_current_chat_send_button(terminal)
                return {
                    "message": f"已把回复草稿填入：{safe_text(label, 80)}。{click_result.get('message', '已尝试发送。')}",
                    "send": click_result,
                }

            if kind == "chat_request_send_confirmation":
                # This tool should only be used when the backend requires confirmation.
                if not self.require_confirm_send_message:
                    return {
                        "blocked": True,
                        "message": "当前配置不需要发送确认。请直接使用 chat_fill_draft 生成并发送消息。",
                    }

                if self.require_confirm_send_message:
                    pending = self.create_send_confirmation()
                    return {
                        "confirmRequired": True,
                        "pendingAction": pending,
                        "message": f"需要你确认后再执行：{safe_text(pending['label'], 80)}",
                    }
                click_result = click_current_chat_send_button(terminal)
                return {"message": click_result.get("message", "已尝试发送。"), "send": click_result}

            if kind == "chat_send_resume":
                return self.send_chat_resume_from_current_conversation(
                    terminal,
                    confirmed=bool(action.get("_confirmed")),
                )

            if kind == "recruiter_send_company_info":
                target_candidate = str(
                    action.get("targetCandidate")
                    or action.get("candidate")
                    or action.get("candidateName")
                    or ""
                ).strip()
                return self.send_recruiter_common_phrase(
                    terminal,
                    phrase_key="basic_conditions",
                    target_candidate=target_candidate,
                )

            if kind == "recruiter_send_common_phrase":
                target_candidate = str(
                    action.get("targetCandidate")
                    or action.get("candidate")
                    or action.get("candidateName")
                    or ""
                ).strip()
                phrase = str(
                    action.get("phrase")
                    or action.get("value")
                    or action.get("text")
                    or action.get("message")
                    or ""
                ).strip()
                phrase_key = str(action.get("phraseKey") or action.get("key") or "").strip()
                return self.send_recruiter_common_phrase(
                    terminal,
                    phrase=phrase,
                    phrase_key=phrase_key,
                    target_candidate=target_candidate,
                )

            if kind == "recruiter_proactive_contact_recommended_candidates":
                return self.proactive_contact_recommended_candidates(
                    terminal,
                    target_position=str(
                        action.get("targetPosition")
                        or action.get("position")
                        or "应用技术经理（工业涂料领域）"
                    ),
                    max_total=int(action.get("maxTotal") or action.get("count") or action.get("limit") or 10),
                    dry_run=bool(action.get("dryRun", False)),
                    require_match=bool(action.get("requireMatch", False)),
                )

            if kind == "recruiter_process_unread_all_positions":
                return self.screen_all_recruiter_unread_basic_conditions(
                    terminal,
                    max_total=int(action.get("maxTotal") or action.get("count") or action.get("limit") or 80),
                    target_position=str(action.get("targetPosition") or action.get("position") or ""),
                    date_scope=str(action.get("dateScope") or action.get("scope") or ""),
                )

            if kind == "recruiter_process_current_position":
                target_candidate = str(
                    action.get("targetCandidate")
                    or action.get("candidate")
                    or action.get("candidateName")
                    or ""
                ).strip()
                return self.screen_recruiter_basic_conditions(
                    terminal,
                    open_unreplied=bool(action.get("openUnreplied", False)),
                    target_candidate=target_candidate,
                    max_attempts=int(action.get("maxAttempts") or action.get("count") or action.get("limit") or 5),
                )

            if kind == "recruiter_answer_candidate_questions":
                target_candidate = str(
                    action.get("targetCandidate")
                    or action.get("candidate")
                    or action.get("candidateName")
                    or ""
                ).strip()
                return self.answer_current_recruiter_questions(
                    terminal,
                    target_candidate=target_candidate,
                )

            if kind == "recruiter_screen_basic_conditions":
                return {
                    "blocked": True,
                    "message": "旧入口 recruiter_screen_basic_conditions 已删除；请使用 recruiter_process_unread_all_positions 或 recruiter_process_current_position。",
                }

            if kind == "recruiter_screen_recent_with_followup":
                return {
                    "blocked": True,
                    "message": "旧入口 recruiter_screen_recent_with_followup 已删除；请使用全岗位未读处理或四账号监听流程。",
                }

            if kind == "recruiter_request_resume":
                target_candidate = str(
                    action.get("targetCandidate")
                    or action.get("candidate")
                    or action.get("candidateName")
                    or ""
                ).strip()
                target_candidates = extract_recruiter_candidate_names_from_text(target_candidate)
                if len(target_candidates) > 1:
                    return self.request_resume_for_named_candidates(terminal, target_candidates)
                return self.request_resume_from_recruiter_conversation(
                    terminal,
                    confirmed=bool(action.get("_confirmed")),
                    open_unreplied=not bool(action.get("_confirmed"))
                    and bool(action.get("openUnreplied", not bool(target_candidate))),
                    expected_candidate=str(action.get("_candidateLabel") or ""),
                    target_candidate=target_candidate,
                )

            if kind == "recruiter_confirm_resume_request":
                return self.confirm_recruiter_resume_request(
                    terminal,
                    expected_candidate=str(action.get("_candidateLabel") or ""),
                )

            if kind == "recruiter_mark_unsuitable":
                target_candidate = str(
                    action.get("targetCandidate")
                    or action.get("candidate")
                    or action.get("candidateName")
                    or ""
                ).strip()
                return self.mark_recruiter_candidate_unsuitable(
                    terminal,
                    confirmed=bool(action.get("_confirmed")),
                    open_unreplied=not bool(action.get("_confirmed"))
                    and bool(action.get("openUnreplied", False)),
                    expected_candidate=str(action.get("_candidateLabel") or ""),
                    target_candidate=target_candidate,
                )

            if kind == "recruiter_confirm_unsuitable":
                return self.confirm_recruiter_unsuitable(
                    terminal,
                    expected_candidate=str(action.get("_candidateLabel") or ""),
                )

            if kind == "job51_process_unread_all_positions":
                return self.with_job51_terminal(
                    lambda job51_terminal: self.job51_process_unread_all_positions(
                        job51_terminal,
                        max_total=int(action.get("maxTotal") or action.get("count") or action.get("limit") or 40),
                        target_position=str(action.get("targetPosition") or action.get("position") or ""),
                    )
                )

            if kind == "job51_process_current_position":
                return self.with_job51_terminal(
                    lambda job51_terminal: self.job51_process_current_position(job51_terminal, opened=None)
                )

            if kind == "job51_answer_candidate_questions":
                return self.with_job51_terminal(
                    lambda job51_terminal: self.job51_answer_current_candidate_questions(job51_terminal)
                )

            if kind == "job51_request_resume":
                return self.with_job51_terminal(
                    lambda job51_terminal: self.job51_download_attachment_or_request_resume(job51_terminal)
                )

            if kind == "job51_proactive_contact_recommended_candidates":
                return self.with_job51_terminal(
                    lambda job51_terminal: self.job51_proactive_contact_recommended_candidates(
                        job51_terminal,
                        target_position=str(action.get("targetPosition") or action.get("position") or ""),
                        max_total=int(action.get("maxTotal") or action.get("count") or action.get("limit") or 10),
                        dry_run=bool(action.get("dryRun", False)),
                    )
                )

            if kind == "zhilian_process_unread_all_positions":
                return self.with_zhilian_terminal(
                    lambda zhilian_terminal: self.zhilian_process_unread_all_positions(
                        zhilian_terminal,
                        max_total=int(action.get("maxTotal") or action.get("count") or action.get("limit") or 40),
                        target_position=str(action.get("targetPosition") or action.get("position") or ""),
                    )
                )

            if kind == "zhilian_process_current_position":
                return self.with_zhilian_terminal(
                    lambda zhilian_terminal: self.zhilian_process_current_position(zhilian_terminal, opened=None)
                )

            if kind == "zhilian_answer_candidate_questions":
                return self.with_zhilian_terminal(
                    lambda zhilian_terminal: self.zhilian_answer_current_candidate_questions(zhilian_terminal)
                )

            if kind == "zhilian_request_resume":
                return self.with_zhilian_terminal(
                    lambda zhilian_terminal: self.zhilian_request_resume_from_current_conversation(zhilian_terminal)
                )

            if kind == "zhilian_proactive_contact_recommended_candidates":
                return self.with_zhilian_terminal(
                    lambda zhilian_terminal: self.zhilian_proactive_contact_recommended_candidates(
                        zhilian_terminal,
                        target_position=str(action.get("targetPosition") or action.get("position") or ""),
                        max_total=int(action.get("maxTotal") or action.get("count") or action.get("limit") or 10),
                        dry_run=bool(action.get("dryRun", False)),
                    )
                )

            if kind == "click":
                # If the model uses placeholder text like "(以上 find_element 返回的 index)",
                # automatically resolve it to the first match index.
                target = resolve_index_placeholder(target, self.last_find_element_matches)
                if is_unresolved_index_placeholder(target):
                    if is_recruiter_unsuitable_task(target):
                        target_candidate = extract_recruiter_unsuitable_candidate_name(target)
                        return self.mark_recruiter_candidate_unsuitable(
                            terminal,
                            confirmed=False,
                            open_unreplied=False,
                            target_candidate=target_candidate,
                        )
                    if is_recruiter_resume_request_task(target) or looks_like_recruiter_resume_request(target):
                        target_candidates = extract_recruiter_request_candidate_names(target)
                        if len(target_candidates) > 1:
                            return self.request_resume_for_named_candidates(terminal, target_candidates)
                        target_candidate = extract_recruiter_request_candidate_name(target)
                        return self.request_resume_from_recruiter_conversation(
                            terminal,
                            confirmed=False,
                            open_unreplied=not bool(target_candidate),
                            target_candidate=target_candidate,
                        )
                    return {
                        "blocked": True,
                        "message": "模型返回了占位符目标（find_element 返回的 index），但当前没有可用匹配结果。我已停止这次错误点击，请重新观察页面或直接使用聊天自动回复。",
                    }
                # Ensure cache is fresh before using numeric indices.
                if target.isdigit():
                    terminal.collect_page_context(limit=120)
                locator, label = terminal.find_locator(target)
                if (
                    self.require_confirm_dangerous_clicks
                    and is_dangerous(label)
                    and not is_whitelisted_send_button(label)
                    and not action.get("_confirmed")
                ):
                    pending = self.create_pending_action(action, label)
                    return {
                        "blocked": True,
                        "confirmRequired": True,
                        "pendingAction": pending,
                        "message": f"需要你确认后再执行：{safe_text(label, 80)}",
                    }
                if terminal.humanize:
                    terminal.pause_like_person("pre_action")
                    highlight_target(locator)
                humanized_locator_click(terminal, locator)
                if terminal.humanize:
                    terminal.pause_like_person("post_action")
                    if is_local_browser_page(terminal):
                        terminal.maybe_scroll_wiggle()
                        self.post_action_idle(terminal)
                message = f"已点击：{safe_text(label, 80)}"
                self.add_event("action", message)
                return {"message": message}

            if kind == "fill":
                label = self.smart_fill(terminal, target, value)
                return {"message": f"已填写：{safe_text(label, 80)}"}

            if kind == "upload":
                file_path = self.resolve_action_file(value)
                terminal.upload(target or "file", file_path)
                self.post_action_idle(terminal)
                message = f"已上传文件：{Path(file_path).name}"
                self.add_event("action", message)
                return {"message": message}

            if kind == "press":
                terminal.press(value or target or "Enter")
                self.post_action_idle(terminal)
                return {"message": f"已按键：{value or target or 'Enter'}"}

            if kind == "wait":
                ms = int(value or target or "1000")
                terminal.current_page().wait_for_timeout(ms)
                return {"message": f"已等待 {ms} ms"}

            if kind == "scroll":
                amount = int(value or target or "600")
                page = terminal.current_page()
                if not terminal.humanize:
                    page.mouse.wheel(0, amount)
                    return {"message": f"已滚动 {amount} px"}

                humanized_scroll(terminal, amount)
                if terminal.humanize:
                    terminal.pause_like_person("post_action")
                return {"message": f"已拟人化滚动 {amount} px"}

            if kind == "goto":
                terminal.goto(value or target)
                return {"message": f"已打开：{value or target}"}

            if kind == "observe":
                self.observe()
                return {"message": "已重新观察页面"}

            if kind in {"done", "stop"}:
                return {
                    "done": True,
                    "message": str(action.get("reason") or "任务已完成。"),
                }

            return {"message": f"暂不支持的动作：{json.dumps(action, ensure_ascii=False)}"}
        except Exception as error:
            self.add_event("error", str(error))
            return {"blocked": True, "message": f"执行失败：{error}"}

    @timed_agent_stage("load_chat_history", "加载聊天历史")
    def load_chat_history(self, terminal: BrowserTerminal, max_rounds: int = CHAT_HISTORY_SCROLL_ROUNDS) -> dict:
        page = terminal.current_page()
        token = f"codex_chat_history_{int(time.time() * 1000)}_{random.randint(1000, 9999)}"
        init = self.measure_current_timing_stage("find_chat_history_container", "查找聊天历史容器", lambda: safe_eval(page, f"""() => {{
          const token = {json.dumps(token)};
          const normalize = (value) => String(value || "").replace(/\\s+/g, " ").trim();
          const visible = (el) => {{
            const box = el.getBoundingClientRect();
            const style = window.getComputedStyle(el);
            return box.width > 120 && box.height > 100 && style.display !== "none" && style.visibility !== "hidden" && style.opacity !== "0";
          }};
          const selector = [
            "main",
            "section",
            "ul",
            "[role='main']",
            "[class*='chat' i]",
            "[class*='message' i]",
            "[class*='dialog' i]",
            "[class*='conversation' i]",
            "[class*='im' i]",
            "[class*='history' i]",
            "[class*='content' i]",
            "[class*='scroll' i]",
            "[class*='list' i]"
          ].join(",");
          const nodes = Array.from(new Set(Array.from(document.body ? document.body.querySelectorAll(selector) : [])));
          let best = null;
          let bestScore = 0;
          const vw = window.innerWidth || 1280;
          for (const el of nodes) {{
            if (!visible(el)) continue;
            const box = el.getBoundingClientRect();
            const rawText = el.innerText || el.textContent || "";
            const text = normalize(rawText.length > 6000 ? rawText.slice(-6000) : rawText);
            if (text.length < 8) continue;
            const cls = String(el.className || "");
            const role = String(el.getAttribute("role") || "");
            let score = 0;
            if (box.x > vw * 0.25) score += 120;
            if (box.width >= 300 && box.height >= 180) score += 80;
            if (el.scrollHeight > el.clientHeight + 30) score += 180;
            if (/chat|message|dialog|conversation|im|history|content|scroll|list/i.test(cls + " " + role)) score += 90;
            if (text.includes("发送") || text.includes("输入")) score -= 15;
            if (text.includes("全部") && text.includes("未读") && text.includes("新招呼")) score -= 260;
            if (box.x < vw * 0.22) score -= 140;
            if (score > bestScore) {{
              best = el;
              bestScore = score;
            }}
          }}
          if (!best) return {{ found: false, text: normalize(document.body ? document.body.innerText : "") }};
          best.setAttribute("data-codex-chat-history", token);
          const box = best.getBoundingClientRect();
          return {{
            found: true,
            token,
            score: bestScore,
            text: normalize(String(best.innerText || best.textContent || "").slice(-6000)),
            x: Math.round(box.x),
            y: Math.round(box.y),
            w: Math.round(box.width),
            h: Math.round(box.height),
            scrollTop: Math.round(best.scrollTop || 0),
            scrollHeight: Math.round(best.scrollHeight || 0),
            clientHeight: Math.round(best.clientHeight || 0),
            className: String(best.className || "").slice(0, 120)
          }};
        }}""") or {})
        if not isinstance(init, dict) or not init.get("found"):
            return {
                "loaded": False,
                "rounds": 0,
                "text": safe_text(str((init or {}).get("text") or ""), 3000) if isinstance(init, dict) else "",
                "reason": "没有找到可滚动的聊天历史容器。",
            }

        locator = page.locator(f"[data-codex-chat-history='{token}']").first
        stable_rounds = 0
        rounds_done = 0
        last_text = str(init.get("text") or "")
        last_scroll_height = int(init.get("scrollHeight") or 0)
        try:
            box = locator.bounding_box(timeout=2000)
        except Exception:
            box = None

        for _ in range(max_rounds):
            rounds_done += 1
            round_started = time.time()
            try:
                before = locator.evaluate(
                    """el => ({
                      text: String(el.innerText || el.textContent || "").slice(-6000).replace(/\\s+/g, " ").trim(),
                      top: Math.round(el.scrollTop || 0),
                      height: Math.round(el.scrollHeight || 0),
                      client: Math.round(el.clientHeight || 0)
                    })"""
                )
            except Exception:
                break

            if box:
                try:
                    humanized_scroll(
                        terminal,
                        -random.randint(650, 1150),
                        box=box,
                        corrective=random.random() < 0.35,
                    )
                except Exception:
                    pass
            try:
                locator.evaluate(
                    """el => {
                      const amount = Math.max(260, Math.floor((el.clientHeight || 500) * 0.85));
                      el.scrollTop = Math.max(0, (el.scrollTop || 0) - amount);
                      el.dispatchEvent(new Event("scroll", { bubbles: true }));
                      el.dispatchEvent(new WheelEvent("wheel", { deltaY: -amount, bubbles: true, cancelable: true }));
                    }"""
                )
            except Exception:
                pass
            page.wait_for_timeout(random.randint(650, 1050))

            try:
                after = locator.evaluate(
                    """el => ({
                      text: String(el.innerText || el.textContent || "").slice(-6000).replace(/\\s+/g, " ").trim(),
                      top: Math.round(el.scrollTop || 0),
                      height: Math.round(el.scrollHeight || 0),
                      client: Math.round(el.clientHeight || 0)
                    })"""
                )
            except Exception:
                break

            after_text = str(after.get("text") or "")
            after_height = int(after.get("height") or 0)
            at_top = int(after.get("top") or 0) <= 4
            changed = after_text != last_text or after_height != last_scroll_height
            last_text = after_text
            last_scroll_height = after_height
            if at_top and not changed:
                stable_rounds += 1
            else:
                stable_rounds = 0
            if stable_rounds >= 2:
                self.record_current_timing_stage(
                    "load_chat_history_scroll_round",
                    "聊天历史滚动加载一轮",
                    round_started,
                    ok=True,
                    extra={"round": rounds_done, "stable": stable_rounds, "atTop": at_top},
                )
                break
            self.record_current_timing_stage(
                "load_chat_history_scroll_round",
                "聊天历史滚动加载一轮",
                round_started,
                ok=True,
                extra={"round": rounds_done, "stable": stable_rounds, "atTop": at_top},
            )

        try:
            restore_started = time.time()
            locator.evaluate(
                """el => {
                  el.scrollTop = el.scrollHeight || el.scrollTop || 0;
                  el.dispatchEvent(new Event("scroll", { bubbles: true }));
                }"""
            )
            page.wait_for_timeout(random.randint(350, 650))
            self.record_current_timing_stage("restore_chat_history_bottom", "聊天历史回到底部", restore_started, ok=True)
        except Exception:
            self.record_current_timing_stage("restore_chat_history_bottom", "聊天历史回到底部", restore_started, ok=False)
            pass

        return {
            "loaded": True,
            "rounds": rounds_done,
            "text": safe_text(last_text, 5000),
            "container": {
                "score": init.get("score"),
                "x": init.get("x"),
                "y": init.get("y"),
                "w": init.get("w"),
                "h": init.get("h"),
                "className": init.get("className"),
            },
        }

    def extract_chat_messages(self, terminal: BrowserTerminal) -> list[dict]:
        page = terminal.current_page()
        messages = safe_eval(page, """() => {
          const normalize = (value) => String(value || "").replace(/\\s+/g, " ").trim();
          const visible = (el) => {
            const box = el.getBoundingClientRect();
            const style = window.getComputedStyle(el);
            return box.width > 4 && box.height > 4 && style.display !== "none" && style.visibility !== "hidden" && style.opacity !== "0";
          };
          const cleanText = (text, time, status) => {
            let value = normalize(text);
            if (time && value.startsWith(time)) value = normalize(value.slice(time.length));
            if (status && value.startsWith(status)) value = normalize(value.slice(status.length));
            return value;
          };
          const rows = Array.from(document.querySelectorAll("li.message-item, [class*='message-item' i]"));
          const out = [];
          const vw = window.innerWidth || 1280;
          for (const row of rows) {
            if (!visible(row)) continue;
            const box = row.getBoundingClientRect();
            const cls = String(row.className || "");
            const raw = normalize(row.innerText || row.textContent || "");
            if (!raw || raw.length < 1) continue;
            const timeNode = row.querySelector(".item-time, [class*='time' i]");
            const statusNode = row.querySelector(".message-status, [class*='status' i]");
            const mineNode = row.querySelector(".item-myself, [class*='item-myself' i], [class*='myself' i]");
            const friendNode = row.querySelector(".item-friend, [class*='item-friend' i], [class*='friend' i]");
            const contentRoot = mineNode || friendNode || row;
            const textNode = contentRoot.querySelector(".text") || contentRoot.querySelector(".message-content") || contentRoot;
            const time = normalize(timeNode ? (timeNode.innerText || timeNode.textContent || "") : "");
            const status = normalize(statusNode ? (statusNode.innerText || statusNode.textContent || "") : "");
            let text = cleanText(textNode ? (textNode.innerText || textNode.textContent || "") : raw, time, status);
            if (!text || text === time || text === status) {
              text = cleanText(raw, time, status);
            }
            if (!text || text === time || text === status) continue;
            let sender = "unknown";
            const low = cls.toLowerCase();
            if (mineNode || low.includes("item-myself") || low.includes("myself") || low.includes("self") || low.includes("mine")) {
              sender = "me";
            } else if (friendNode || low.includes("item-friend") || low.includes("friend") || low.includes("other")) {
              sender = "other";
            } else {
              sender = box.x + box.width * 0.5 > vw * 0.55 ? "me" : "other";
            }
            out.push({
              sender,
              text,
              rawText: raw,
              status,
              time,
              className: cls.slice(0, 120),
              x: Math.round(box.x),
              y: Math.round(box.y),
              w: Math.round(box.width),
              h: Math.round(box.height)
            });
          }
          out.sort((a, b) => a.y - b.y || a.x - b.x);
          return out.slice(-120);
        }""")
        if not isinstance(messages, list):
            return []
        normalized = []
        for item in messages:
            if not isinstance(item, dict):
                continue
            text_value = safe_text(str(item.get("text") or "").strip(), 500)
            if not text_value:
                continue
            sender = str(item.get("sender") or "unknown")
            if sender not in {"me", "other", "unknown"}:
                sender = "unknown"
            normalized.append({
                "sender": sender,
                "text": text_value,
                "status": safe_text(str(item.get("status") or ""), 30),
                "time": safe_text(str(item.get("time") or ""), 30),
                "rawText": safe_text(str(item.get("rawText") or ""), 600),
                "className": safe_text(str(item.get("className") or ""), 120),
                "x": item.get("x"),
                "y": item.get("y"),
            })
        return normalized

    def read_current_applicant_context(self, terminal: BrowserTerminal) -> dict:
        page = terminal.current_page()
        info = safe_eval(page, r"""() => {
          const normalize = (value) => String(value || "").replace(/\s+/g, " ").trim();
          const visible = (el) => {
            if (!el) return false;
            const box = el.getBoundingClientRect();
            const style = window.getComputedStyle(el);
            return box.width > 10 && box.height > 8 && box.bottom > 0 && box.y < window.innerHeight
              && style.display !== "none" && style.visibility !== "hidden" && style.opacity !== "0";
          };
          const selected = Array.from(document.querySelectorAll(
            ".geek-item.selected, [class*='geek-item'][class*='selected']"
          )).find(visible);
          const row = selected ? (selected.closest(".geek-item-wrap") || selected) : null;
          const text = normalize(row ? (row.innerText || row.textContent || "") : "");
          const nameNode = row ? row.querySelector(".geek-name, [class*='geek-name'], [class*='name']") : null;
          const jobNode = row ? row.querySelector(".source-job, [class*='source-job']") : null;
          let name = normalize(nameNode ? (nameNode.innerText || nameNode.textContent || "") : "");
          let appliedPosition = normalize(jobNode ? (jobNode.innerText || jobNode.textContent || "") : "");

          if (!name || !appliedPosition) {
            let core = text.replace(/^\d+\s+/, "").replace(/^\d{1,2}:\d{2}\s+/, "");
            if (!name) {
              const nameMatch = core.match(/^([\u4e00-\u9fffA-Za-z·]{2,8})\s+/);
              if (nameMatch) name = nameMatch[1];
            }
            if (!appliedPosition && name && core.startsWith(name)) {
              const rest = normalize(core.slice(name.length));
              const stopMatch = rest.match(/^(.{2,30}?)(?:\s+(?:您好|你好|BOSS|Boss|HR|Hr|[^\s]+\.pdf)|$)/);
              if (stopMatch) appliedPosition = normalize(stopMatch[1]);
            }
          }

          const headerNodes = Array.from(document.querySelectorAll(
            ".chat-title, .chat-header, [class*='chat-title'], [class*='conversation-header'], [class*='detail']"
          )).filter(visible).map((el) => normalize(el.innerText || el.textContent || "")).filter(Boolean);
          const rowBox = row ? row.getBoundingClientRect() : null;
          return {
            name,
            appliedPosition,
            label: text,
            headers: headerNodes.slice(0, 8),
            source: row ? "selected-geek-item" : "",
            x: rowBox ? Math.round(rowBox.x) : null,
            y: rowBox ? Math.round(rowBox.y) : null
          };
        }""")
        if not isinstance(info, dict):
            return {}
        applied_position = clean_applied_position(str(info.get("appliedPosition") or ""))
        return {
            "name": safe_text(str(info.get("name") or ""), 40),
            "appliedPosition": applied_position,
            "label": safe_text(str(info.get("label") or ""), 180),
            "headers": info.get("headers") if isinstance(info.get("headers"), list) else [],
            "source": safe_text(str(info.get("source") or ""), 40),
            "x": info.get("x"),
            "y": info.get("y"),
        }

    @timed_agent_stage("read_chat_context", "读取聊天记录")
    def read_chat_context(self, terminal: BrowserTerminal, history: dict | None = None) -> dict:
        page = terminal.current_page()
        text = safe_eval(page, "() => document.body ? document.body.innerText : ''") or ""
        detail = safe_eval(page, """() => {
          const normalize = (value) => String(value || "").replace(/\\s+/g, " ").trim();
          const visible = (el) => {
            const box = el.getBoundingClientRect();
            const style = window.getComputedStyle(el);
            return box.width > 120 && box.height > 80 && style.display !== "none" && style.visibility !== "hidden" && style.opacity !== "0";
          };
          const selector = [
            "main",
            "section",
            "[role='main']",
            "[class*='chat' i]",
            "[class*='message' i]",
            "[class*='dialog' i]",
            "[class*='conversation' i]",
            "[class*='im' i]",
            "[class*='content' i]"
          ].join(",");
          const nodes = Array.from(document.body ? document.body.querySelectorAll(selector) : []);
          let best = null;
          let bestScore = 0;
          const vw = window.innerWidth || 1280;
          for (const el of nodes) {
            if (!visible(el)) continue;
            const box = el.getBoundingClientRect();
            const label = normalize(el.innerText || el.textContent || "");
            if (label.length < 12) continue;
            let score = Math.min(label.length, 2400) / 20;
            if (box.x > vw * 0.25) score += 80;
            if (box.width > 300 && box.height > 180) score += 60;
            if (/chat|message|dialog|conversation|im/i.test(String(el.className || ""))) score += 50;
            if (label.includes("\u53d1\u9001") || label.includes("\u8f93\u5165")) score += 20;
            if (label.includes("\u5168\u90e8") && label.includes("\u672a\u8bfb") && label.includes("\u65b0\u62db\u547c")) score -= 180;
            if (score > bestScore) {
              best = { text: label, score, x: Math.round(box.x), y: Math.round(box.y), w: Math.round(box.width), h: Math.round(box.height) };
              bestScore = score;
            }
          }
          return best || { text: normalize(document.body ? document.body.innerText : ""), score: 0 };
        }""") or {}
        recent_source = str(history.get("text") or "") if isinstance(history, dict) and history.get("text") else (
            detail.get("text") if isinstance(detail, dict) else ""
        )
        recent = safe_text(recent_source or text, 1600)
        messages = self.extract_chat_messages(terminal)
        applicant = self.read_current_applicant_context(terminal)
        applied_position = str(applicant.get("appliedPosition") or "")
        last_message = last_effective_chat_message(messages)
        last_other = last_effective_chat_message(messages, sender="other")
        intent = classify_chat_intent(last_other.get("text", "") if last_other else "")
        conversation_key = build_conversation_key(page.url, messages, applicant.get("label") or applicant.get("name"))
        boss_rules = load_boss_chat_rules()
        position_reply = select_position_reply(applied_position, boss_rules)
        company_knowledge_base = select_company_knowledge_base(boss_rules, applied_position)
        context = {
            "title": page.title(),
            "url": page.url,
            "recentText": recent,
            "pageTextPreview": safe_text(text, 900),
            "chatDetailSource": detail if isinstance(detail, dict) else {},
            "applicant": applicant,
            "appliedPosition": applied_position,
            "positionReply": position_reply,
            "companyKnowledgeBase": company_knowledge_base,
            "loadedHistory": history or {},
            "messages": messages[-80:],
            "lastMessage": last_message,
            "lastOtherMessage": last_other,
            "lastSender": last_message.get("sender") if last_message else "",
            "lastOtherSignature": chat_message_signature(last_other) if last_other else "",
            "shouldReply": bool(last_message and last_message.get("sender") == "other"),
            "intent": intent,
            "conversationKey": conversation_key,
            "summary": (
                f"已读取当前聊天页面上下文；应聘岗位：{safe_text(applied_position, 60)}；"
                f"{safe_text(recent, 260)}"
            ),
        }
        context["memory"] = self.refresh_chat_memory(context, conversation_key)
        context["companyKnowledgeHit"] = match_company_knowledge_answer(context)
        return context

    def check_chat_monitor(self) -> dict:
        with self.lock:
            if not has_model_key():
                raise AgentError("还没有配置模型 API Key，无法根据对方消息生成候选回复。")
            terminal = self.get_terminal()
            unread_state = read_unread_badge_state(terminal)
            unread_signature = str(unread_state.get("signature") or "")
            unread_changed = bool(unread_signature and unread_signature != self.chat_monitor_unread_signature)
            if unread_state.get("count", 0):
                self.chat_monitor_unread_signature = unread_signature
                self.chat_monitor_suggestions = []
                message = (
                    f"检测到未读红点：{unread_state.get('count')} 条。"
                    "本轮不会读取当前打开的聊天框，请使用自动回复流程先打开未读会话。"
                )
                if unread_changed:
                    self.add_event("chat", f"检测到未读红点：{unread_state.get('count')} 条，已进入未读优先模式")
                return {
                    "changed": unread_changed,
                    "message": message,
                    "suggestions": [],
                    "unread": unread_state,
                    "context": {"unreadPriority": True},
                }

            context = self.read_chat_context(terminal)
            signature = chat_context_signature(context.get("recentText", ""))
            text_changed = bool(signature and signature != self.chat_monitor_signature)
            if not unread_changed and signature and signature == self.chat_monitor_signature:
                return {
                    "changed": False,
                    "message": "没有检测到新的聊天内容变化。",
                    "suggestions": self.chat_monitor_suggestions,
                    "unread": unread_state,
                    "context": context,
                }

            suggestions = ask_agent_model_for_reply_suggestions(context) if text_changed and context.get("shouldReply") else []
            self.chat_monitor_signature = signature
            self.chat_monitor_unread_signature = unread_signature
            self.chat_monitor_suggestions = suggestions
            if unread_changed and unread_state.get("count", 0):
                self.add_event("chat", f"检测到未读红点：{unread_state.get('count')} 条，等待自动回复流程打开会话")
                message = f"检测到未读红点：{unread_state.get('count')} 条。"
            else:
                self.add_event("chat", f"检测到聊天内容变化，生成 {len(suggestions)} 条候选回复")
                message = f"检测到聊天内容变化，已生成 {len(suggestions)} 条候选回复。"
            return {
                "changed": True,
                "message": message,
                "suggestions": suggestions,
                "unread": unread_state,
                "context": context,
            }

    def auto_reply_chat_once(self, auto_send: bool = False, force: bool = False) -> dict:
        with self.lock:
            if not has_model_key():
                raise AgentError("还没有配置模型 API Key，无法自动回复。")
            if not force and time.time() < self.chat_monitor_cooldown_until:
                return {
                    "changed": False,
                    "message": "刚刚完成一次发送，自动回复冷却中，避免重复回复同一会话。",
                    "cooldown": True,
                }
            pending_send = self.pending_send_confirmation()
            if pending_send:
                return {
                    "changed": False,
                    "message": "已有一条回复草稿正在等待你确认发送，本轮自动检查先暂停。",
                    "pending": True,
                }
            terminal = self.get_terminal()
            unread_state = read_unread_badge_state(terminal)
            unread_signature = str(unread_state.get("signature") or "")
            unread_changed = bool(unread_signature and unread_signature != self.chat_monitor_unread_signature)
            if (
                not force
                and unread_state.get("count", 0)
                and unread_signature
                and unread_signature == self.chat_monitor_handled_unread_signature
            ):
                return {
                    "changed": False,
                    "message": "这批未读消息已经生成过一条回复，等待红点变化或你确认发送。",
                    "unread": unread_state,
                }
            opened = (
                self.open_unreplied_chat_if_present(terminal, require_unread_badge=True)
                if unread_state.get("count", 0)
                else None
            )
            if unread_state.get("count", 0) and not opened:
                return {
                    "changed": False,
                    "message": "检测到未读消息，但没有成功打开未读会话；本轮不会读取当前已打开会话，避免回复错人。",
                    "unread": unread_state,
                }
            opened_context = self.read_chat_context(terminal) if opened else {}
            if opened and unread_state.get("count", 0):
                match_state = opened_thread_matches_context(opened, opened_context)
                opened["matchState"] = match_state
                if not match_state.get("matched"):
                    return {
                        "changed": False,
                        "message": (
                            "已点击疑似未读会话，但页面详情没有稳定切换到该会话；"
                            "本轮停止，避免把第十个人的聊天误当成第二个人来回复。"
                        ),
                        "openedThread": opened,
                        "unread": unread_state,
                        "context": opened_context,
                    }
            if opened and not opened_context.get("shouldReply"):
                return {
                    "changed": False,
                    "message": "已打开疑似未读会话，但底部最后一条有效消息不是对方发来的，本轮不生成回复。",
                    "openedThread": opened,
                    "unread": unread_state,
                    "context": opened_context,
                }
            history = self.load_chat_history(terminal) if opened else {}
            context = self.read_chat_context(terminal, history=history)
            if opened and opened_context.get("shouldReply"):
                opened_last = opened_context.get("lastMessage") if isinstance(opened_context.get("lastMessage"), dict) else {}
                opened_last_other = opened_context.get("lastOtherMessage") if isinstance(opened_context.get("lastOtherMessage"), dict) else {}
                context["lastMessage"] = opened_last
                context["lastOtherMessage"] = opened_last_other or opened_last
                context["lastSender"] = opened_last.get("sender") or "other"
                context["lastOtherSignature"] = chat_message_signature(opened_last_other or opened_last)
                context["shouldReply"] = True
                context["intent"] = classify_chat_intent(str((opened_last_other or opened_last).get("text") or ""))
            conversation_key = build_conversation_key(
                context.get("url", ""),
                context.get("messages", []),
                opened.get("label") if isinstance(opened, dict) else None,
            )
            context["conversationKey"] = conversation_key
            context["memory"] = self.refresh_chat_memory(
                context,
                conversation_key,
                opened_label=opened.get("label") if isinstance(opened, dict) else None,
            )
            state = self.get_chat_state(conversation_key)
            last_other_signature = str(context.get("lastOtherSignature") or "")
            if not context.get("shouldReply"):
                if conversation_key:
                    self.set_chat_state(
                        conversation_key,
                        "skipped",
                        reason="last_message_not_from_other",
                        lastOtherSignature=last_other_signature,
                        intent=context.get("intent", {}),
                    )
                return {
                    "changed": False,
                    "message": "最后一条有效消息不是对方发来的，本轮不生成回复。",
                    "openedThread": opened,
                    "unread": unread_state,
                    "context": context,
                }
            if (
                not force
                and state.get("lastOtherSignature")
                and last_other_signature
                and state.get("lastOtherSignature") == last_other_signature
                and state.get("status") in {"waiting_confirm", "sent", "drafted"}
            ):
                return {
                    "changed": False,
                    "message": f"这个会话的最新对方消息已处于“{state.get('status')}”状态，不重复生成。",
                    "conversationState": state,
                    "openedThread": opened,
                    "unread": unread_state,
                    "context": context,
                }
            signature = chat_context_signature(context.get("recentText", ""))
            if not force and not opened and not unread_changed and signature and signature == self.chat_monitor_signature:
                return {
                    "changed": False,
                    "message": "没有检测到新的聊天内容变化。",
                    "suggestions": self.chat_monitor_suggestions,
                    "unread": unread_state,
                    "context": context,
                }

            suggestions = ask_agent_model_for_reply_suggestions(context)
            self.chat_monitor_signature = signature
            self.chat_monitor_unread_signature = unread_signature
            self.chat_monitor_suggestions = suggestions
            if not suggestions:
                if conversation_key:
                    self.set_chat_state(
                        conversation_key,
                        "skipped",
                        reason="model_returned_no_suggestion",
                        lastOtherSignature=last_other_signature,
                        intent=context.get("intent", {}),
                    )
                return {
                    "changed": True,
                    "message": (
                        "已打开疑似未回复会话，但模型判断暂时不需要回复。"
                        if opened else "检测到聊天内容变化，但模型判断暂时不需要回复。"
                    ),
                    "openedThread": opened,
                    "suggestions": [],
                    "unread": unread_state,
                    "context": context,
                }

            chosen = safe_text(str(suggestions[0].get("text") or "").strip(), CHAT_REPLY_MAX_CHARS)
            if not chosen:
                return {
                    "changed": True,
                    "message": "检测到聊天内容变化，但候选回复为空。",
                    "suggestions": suggestions,
                    "unread": unread_state,
                    "context": context,
                }

            # Only local/test pages may fully auto-send. On external sites we fill a draft
            # and create a confirmation request, so the user stays in control of messages.
            allow_auto_send = bool(auto_send) and is_local_browser_page(terminal)
            previous_confirm = self.require_confirm_send_message
            if not allow_auto_send:
                self.require_confirm_send_message = True
            try:
                fill_result = self.fill_chat_suggestion(chosen)
            finally:
                self.require_confirm_send_message = previous_confirm
            pending = fill_result.get("pendingAction")
            if conversation_key:
                pending_token = pending.get("token") if isinstance(pending, dict) else ""
                if pending_token and pending_token in self.pending_actions:
                    self.pending_actions[pending_token]["action"]["_conversationKey"] = conversation_key
                    self.pending_actions[pending_token]["action"]["_lastOtherSignature"] = last_other_signature
                self.set_chat_state(
                    conversation_key,
                    "waiting_confirm" if pending else ("sent" if allow_auto_send else "drafted"),
                    lastOtherSignature=last_other_signature,
                    intent=context.get("intent", {}),
                    draft=chosen,
                    pendingToken=pending_token,
                    openedLabel=opened.get("label") if isinstance(opened, dict) else "",
                )
            if unread_signature:
                self.chat_monitor_handled_unread_signature = unread_signature

            after_context = self.read_chat_context(terminal)
            after_signature = chat_context_signature(after_context.get("recentText", ""))
            if after_signature:
                self.chat_monitor_signature = after_signature

            mode = "已自动发送" if allow_auto_send else "已自动填入草稿，等待确认发送"
            return {
                "changed": True,
                "message": mode,
                "suggestions": suggestions,
                "chosen": chosen,
                "openedThread": opened,
                "unread": unread_state,
                "autoSent": allow_auto_send,
                "reply": fill_result.get("reply") or mode,
                "pendingAction": fill_result.get("pendingAction"),
                "send": fill_result.get("send"),
                "page": fill_result.get("page"),
                "context": after_context,
            }

    def open_unreplied_chat_if_present(self, terminal: BrowserTerminal, require_unread_badge: bool = False) -> dict | None:
        prepare_result = {}
        if require_unread_badge:
            prepare_result = prepare_unread_chat_list(terminal)
        target = find_unreplied_chat_target(terminal, require_unread_badge=require_unread_badge)
        if not target and require_unread_badge:
            prepare_result = prepare_unread_chat_list(terminal)
            target = find_unreplied_chat_target(terminal, require_unread_badge=require_unread_badge)
        if not target:
            return None
        locator = target["locator"]
        label = str(target.get("label") or "未回复会话")
        if terminal.humanize:
            terminal.pause_like_person("pre_action")
            highlight_target(locator)
        clicked = False
        if target.get("reason") == "unread-badge":
            try:
                box = locator.bounding_box(timeout=2000)
                if box:
                    x = box["x"] + box["width"] / 2
                    y = box["y"] + box["height"] / 2
                    humanized_point_click(terminal, x, y)
                    clicked = True
            except Exception:
                clicked = False
        if not clicked and terminal.visual_cursor:
            try:
                humanized_locator_click(terminal, locator, force=True)
            except Exception:
                locator.click(timeout=8000, force=True)
        elif not clicked:
            humanized_locator_click(terminal, locator, force=True)
        terminal.current_page().wait_for_timeout(random.randint(650, 1100))
        message = f"已打开疑似未回复会话：{safe_text(label, 80)}"
        self.add_event("chat", message)
        return {
            "label": safe_text(label, 160),
            "reason": target.get("reason", ""),
            "message": message,
            "x": target.get("x"),
            "y": target.get("y"),
            "w": target.get("w"),
            "h": target.get("h"),
            "prepare": prepare_result if isinstance(prepare_result, dict) else {},
        }

    def fill_chat_suggestion(self, text: str) -> dict:
        with self.lock:
            if not text.strip():
                raise AgentError("候选回复为空，无法填入。")
            terminal = self.get_terminal()
            label = self.smart_fill(terminal, "聊天", text.strip())
            if self.require_confirm_send_message or not is_local_browser_page(terminal):
                pending = self.create_send_confirmation()
                return {
                    "reply": f"已填入草稿：{safe_text(label, 80)}。需要你确认后再发送。",
                    "pendingAction": pending,
                    "page": {
                        "title": terminal.current_page().title(),
                        "url": terminal.current_page().url,
                    },
                }
            send_action = find_send_action(terminal)
            result = self.execute_action(terminal, send_action)
            return {
                "reply": f"已填入草稿：{safe_text(label, 80)}。{result.get('message', '已尝试发送。')}",
                "send": result,
                "page": {
                    "title": terminal.current_page().title(),
                    "url": terminal.current_page().url,
                },
            }

    def send_chat_resume_from_current_conversation(self, terminal: BrowserTerminal, confirmed: bool = False) -> dict:
        button = find_chat_resume_button(terminal)
        if not button.get("found"):
            return {
                "blocked": True,
                "message": "当前聊天页没有找到“发简历”按钮。请先切到 BOSS 聊天详情页，或让页面完成加载后再试。",
                "state": button,
            }

        label = str(button.get("label") or "发简历")
        reason = str(button.get("reason") or "")
        if button.get("disabled"):
            message = "找到了“发简历”按钮，但当前不可用。"
            if reason:
                message += f" 页面提示：{safe_text(reason, 120)}"
            else:
                message += " 可能需要等待对方回复、切换到可沟通状态，或先完成平台要求的步骤。"
            return {
                "blocked": True,
                "message": message,
                "state": {k: v for k, v in button.items() if k != "locator"},
            }

        if not confirmed and not is_local_browser_page(terminal):
            pending = self.create_pending_action(
                {"action": "chat_send_resume", "_pendingType": "send_resume"},
                "发送简历给当前聊天对象",
            )
            return {
                "blocked": True,
                "confirmRequired": True,
                "pendingAction": pending,
                "message": "我已找到可用的“发简历”按钮。发送简历会把你的个人简历发给当前聊天对象，需要你确认后再执行。",
                "state": {k: v for k, v in button.items() if k != "locator"},
            }

        locator = button.get("locator")
        if locator is None:
            return {
                "blocked": True,
                "message": "找到了“发简历”按钮的信息，但没有拿到可点击元素，请重新观察页面后再试。",
            }
        if terminal.humanize:
            terminal.pause_like_person("pre_action")
            highlight_target(locator)
        humanized_locator_click(terminal, locator, force=True)
        if terminal.humanize:
            terminal.pause_like_person("post_action")
        terminal.current_page().wait_for_timeout(random.randint(900, 1400))
        after = inspect_chat_resume_after_click(terminal)
        message = "已点击“发简历”按钮。"
        if after.get("needsFollowup"):
            message += f" 页面出现后续确认/选择项：{safe_text(after.get('summary', ''), 160)}。我不会继续点最终发送，除非你再次确认。"
        elif after.get("sentLike"):
            message += " 页面看起来已经出现简历发送相关记录，请你确认聊天记录是否已发出。"
        else:
            message += " 如果页面弹出了简历选择或确认框，请告诉我下一步，我会继续按确认流程处理。"
        self.add_event("chat", message)
        return {
            "message": message,
            "state": {k: v for k, v in button.items() if k != "locator"},
            "after": after,
        }

    @timed_agent_stage("send_common_phrase", "发送常用语/话术")
    def send_recruiter_common_phrase(
        self,
        terminal: BrowserTerminal,
        phrase: str = "",
        phrase_key: str = "",
        target_candidate: str = "",
    ) -> dict:
        target_candidate = clean_recruiter_candidate_name(target_candidate)
        opened = None
        if target_candidate:
            current = read_recruiter_selected_candidate(terminal)
            current_label = str(current.get("label") or "")
            if candidate_label_matches(current_label, target_candidate):
                opened = {"label": current_label, "matchedBy": "current", "targetCandidate": target_candidate}
            else:
                target = find_recruiter_candidate_by_name(terminal, target_candidate, scroll_attempts=10)
                if not target:
                    return {
                        "blocked": True,
                        "message": f"没有在当前招聘会话列表里找到候选人：{safe_text(target_candidate, 40)}。",
                        "targetCandidate": target_candidate,
                    }
                locator = target.get("locator")
                if locator is None:
                    return {
                        "blocked": True,
                        "message": f"找到了候选人：{safe_text(target_candidate, 40)}，但没有拿到可点击元素。",
                        "candidate": {k: v for k, v in target.items() if k != "locator"},
                    }
                if terminal.humanize:
                    terminal.pause_like_person("pre_action")
                    highlight_target(locator)
                humanized_locator_click(terminal, locator, force=True)
                if terminal.humanize:
                    terminal.pause_like_person("post_action")
                terminal.current_page().wait_for_timeout(random.randint(900, 1400))
                opened = {k: v for k, v in target.items() if k != "locator"}

        context = self.read_chat_context(terminal)
        position_reply = context.get("positionReply") if isinstance(context.get("positionReply"), dict) else {}
        if not is_ai_app_basic_conditions_position(context, position_reply):
            return {
                "blocked": True,
                "message": (
                    "已按规则拦截：常用语/基础条件话术只允许发送给 AI 应用开发相关岗位，"
                    f"当前岗位是 {safe_text(str(context.get('appliedPosition') or '未识别岗位'), 60)}。"
                ),
                "opened": opened,
                "contextPosition": safe_text(str(context.get("appliedPosition") or ""), 80),
            }
        if not phrase:
            if phrase_key in {"basic_conditions", "initial_conditions", "基础条件", "岗位基础条件"}:
                phrase = str(position_reply.get("initialCommonPhrase") or "")
            if not phrase:
                phrase = str(position_reply.get("initialCommonPhrase") or BASIC_CONDITIONS_PHRASE)
        phrase = safe_text(phrase.strip(), 400)
        if not phrase:
            return {"blocked": True, "message": "没有拿到要发送的常用语内容。"}

        candidate = read_recruiter_selected_candidate(terminal)
        candidate_label = str(candidate.get("label") or "")

        cache_key = "basic_conditions"
        button = {}
        cached_button = {}
        if not is_common_phrase_panel_open(terminal):
            cached_button = self.measure_current_timing_stage(
                "click_cached_common_phrase_button",
                "按缓存位置打开常用语",
                lambda: self.click_cached_common_phrase_button(terminal, cache_key),
            )
        if not is_common_phrase_panel_open(terminal):
            button = self.measure_current_timing_stage(
                "find_common_phrase_button",
                "查找常用语按钮",
                lambda: find_common_phrase_button(terminal),
            )
            if not button.get("found"):
                return {
                    "blocked": True,
                    "message": "没有找到聊天工具栏里的“常用语”按钮。",
                    "candidate": candidate,
                    "state": button,
                    "cache": cached_button,
                }
            self.update_common_phrase_cache(cache_key, buttonBox={
                "x": button.get("x"),
                "y": button.get("y"),
                "w": button.get("w"),
                "h": button.get("h"),
            })
        clear_chat_editor(terminal)
        locator = button.get("locator")
        if not is_common_phrase_panel_open(terminal) and locator is None:
            return {
                "blocked": True,
                "message": "找到了“常用语”按钮信息，但没有拿到可点击元素。",
                "candidate": candidate,
            }
        if not is_common_phrase_panel_open(terminal) and terminal.humanize:
            terminal.pause_like_person("pre_action")
            highlight_target(locator)
        if not is_common_phrase_panel_open(terminal):
            open_panel_started = time.time()
            humanized_locator_click(terminal, locator, force=True)
            if terminal.humanize:
                terminal.pause_like_person("post_action")
            terminal.current_page().wait_for_timeout(random.randint(350, 700))
            panel_opened = is_common_phrase_panel_open(terminal)
            self.record_current_timing_stage("open_common_phrase_panel", "打开常用语面板", open_panel_started, ok=panel_opened)
            if not panel_opened:
                if terminal.humanize:
                    terminal.pause_like_person("pre_action")
                    highlight_target(locator)
                retry_panel_started = time.time()
                humanized_locator_click(terminal, locator, force=True)
                if terminal.humanize:
                    terminal.pause_like_person("post_action")
                terminal.current_page().wait_for_timeout(random.randint(450, 850))
                self.record_current_timing_stage(
                    "open_common_phrase_panel_retry",
                    "重试打开常用语面板",
                    retry_panel_started,
                    ok=is_common_phrase_panel_open(terminal),
                )

        item = self.measure_current_timing_stage(
            "find_common_phrase_item",
            "查找常用语内容",
            lambda: find_common_phrase_item(terminal, phrase),
        )
        if not item.get("found"):
            return {
                "blocked": True,
                "message": f"常用语面板里没有找到这句话：{safe_text(phrase, 80)}",
                "candidate": candidate,
                "state": item,
            }
        direct_send = self.measure_current_timing_stage(
            "click_cached_common_phrase_send",
            "按缓存位置发送常用语",
            lambda: self.click_cached_common_phrase_send(terminal, phrase, item, cache_key),
        )
        if not direct_send.get("clicked"):
            direct_send = self.measure_current_timing_stage(
                "click_common_phrase_send",
                "点击常用语发送",
                lambda: click_common_phrase_row_send_button(terminal, phrase, item),
            )
        if direct_send.get("clicked"):
            self.update_common_phrase_cache(cache_key, sendBox={
                "x": direct_send.get("x"),
                "y": direct_send.get("y"),
                "w": direct_send.get("w"),
                "h": direct_send.get("h"),
            }, rowBox=direct_send.get("rowBox") if isinstance(direct_send.get("rowBox"), dict) else {
                "x": item.get("x"),
                "y": item.get("y"),
                "w": item.get("w"),
                "h": item.get("h"),
            }, phrase=safe_text(phrase, 240))
        if not direct_send.get("clicked"):
            return {
                "blocked": True,
                "message": "已打开“常用语”并找到目标话术，但没有成功触发/点击该话术右侧的“发送”按钮；已停止，避免误点聊天输入框。",
                "candidate": candidate,
                "state": {k: v for k, v in item.items() if k != "locator"},
                "directSend": direct_send,
            }
        if not direct_send.get("clicked"):
            item_locator = item.get("locator")
            if item_locator is None:
                fallback_item = click_common_phrase_item_by_text(terminal, phrase)
                if not fallback_item.get("clicked"):
                    return {
                        "blocked": True,
                        "message": "找到了常用语文本，但没有拿到可点击元素，也没有找到右侧发送按钮。",
                        "candidate": candidate,
                        "state": {k: v for k, v in item.items() if k != "locator"},
                        "directSend": direct_send,
                        "fallback": fallback_item,
                    }
            else:
                try:
                    if terminal.humanize:
                        terminal.pause_like_person("pre_action")
                        highlight_target(item_locator)
                    humanized_locator_click(terminal, item_locator, force=True)
                except Exception as error:
                    fallback_item = click_common_phrase_item_by_text(terminal, phrase)
                    if not fallback_item.get("clicked"):
                        return {
                            "blocked": True,
                            "message": f"找到了常用语文本，但点击失败：{safe_text(str(error), 180)}",
                            "candidate": candidate,
                            "state": {k: v for k, v in item.items() if k != "locator"},
                            "directSend": direct_send,
                            "fallback": fallback_item,
                        }
            if terminal.humanize:
                terminal.pause_like_person("post_action")
            terminal.current_page().wait_for_timeout(random.randint(420, 780))

            editor_text = read_chat_editor_text(terminal)
            if phrase[:20] not in editor_text:
                return {
                    "blocked": True,
                    "message": f"已点击常用语，但输入框里没有检测到预期文本。当前输入框：{safe_text(editor_text, 120)}",
                    "candidate": candidate,
                    "state": {k: v for k, v in item.items() if k != "locator"},
                    "directSend": direct_send,
                }

            send_action = find_send_action(terminal)
            send_result = self.execute_action(terminal, send_action)
        else:
            send_result = {"message": "已点击常用语右侧发送按钮", "directSend": direct_send}
        message = f"已通过“常用语”向候选人发送：{safe_text(phrase, 120)}"
        self.add_event("chat", message)
        return {
            "message": message,
            "candidate": candidate,
            "opened": opened,
            "phrase": phrase,
            "state": {
                "button": {k: v for k, v in button.items() if k != "locator"},
                "item": {k: v for k, v in item.items() if k != "locator"},
            },
            "send": send_result,
        }

    @timed_agent_stage("knowledge_answer", "知识库/规则答疑")
    def answer_recruiter_knowledge_question(
        self,
        terminal: BrowserTerminal,
        context: dict,
        candidate_label: str,
        conversation_key: str,
        candidate_state_key: str,
        previous_state: dict | None = None,
        send_message=None,
    ) -> dict:
        previous_state = previous_state if isinstance(previous_state, dict) else {}
        last_message = context.get("lastMessage") if isinstance(context.get("lastMessage"), dict) else {}
        if last_message.get("sender") != "other":
            return {}
        knowledge_base = context.get("companyKnowledgeBase") if isinstance(context.get("companyKnowledgeBase"), dict) else {}
        if str(context.get("appliedPosition") or "").strip() and not knowledge_base.get("enabled"):
            return {}
        self.measure_current_timing_stage(
            "ensure_conversation_review_for_knowledge",
            "答疑复盘",
            lambda: ensure_candidate_conversation_review(context, previous_state),
        )
        question_messages = recent_unanswered_question_messages(context, previous_state)
        knowledge_context = knowledge_question_context(context, question_messages) if question_messages else dict(context)
        silent_hit = match_company_knowledge_silent_question(knowledge_context)
        if silent_hit:
            if not question_messages:
                fallback_last_other = context.get("lastOtherMessage") if isinstance(context.get("lastOtherMessage"), dict) else {}
                if fallback_last_other:
                    question_messages = [fallback_last_other]
                    knowledge_context = knowledge_question_context(context, question_messages)
            knowledge_signatures = knowledge_context.get("knowledgeQuestionSignatures")
            if not isinstance(knowledge_signatures, list):
                knowledge_signatures = [chat_message_signature(item) for item in question_messages if chat_message_signature(item)]
            last_other = knowledge_context.get("lastOtherMessage") if isinstance(knowledge_context.get("lastOtherMessage"), dict) else {}
            last_other_signature = str(knowledge_context.get("lastOtherSignature") or chat_message_signature(last_other))
            state_payload = {
                "candidateLabel": safe_text(candidate_label, 160),
                "knowledgeTopic": safe_text(str(silent_hit.get("topic") or ""), 80),
                "knowledgeAnswer": "",
                "knowledgeSilentSkipped": True,
                "knowledgeMatchedPattern": safe_text(str(silent_hit.get("matchedPattern") or ""), 120),
                "lastOtherSignature": last_other_signature,
                "lastOther": safe_text(str(last_other.get("text") or ""), 180),
                "knowledgeAnsweredSignatures": [str(item) for item in knowledge_signatures if str(item or "").strip()][-RECENT_UNANSWERED_OTHER_LIMIT:],
                "knowledgeQuestionMessages": [
                    safe_text(str(item.get("text") or ""), 180)
                    for item in question_messages
                    if isinstance(item, dict)
                ],
                "knowledgeEvidence": [silent_hit],
            }
            if conversation_key:
                self.set_chat_state(conversation_key, "knowledge_silent_skipped", **state_payload)
            if candidate_state_key:
                self.set_chat_state(candidate_state_key, "knowledge_silent_skipped", **state_payload)
            self.set_recruiter_basic_state(
                conversation_key,
                candidate_label,
                "knowledge_silent_skipped",
                context=context,
                **state_payload,
            )
            user_question_items = build_recruiter_unclear_question_items(
                candidate_label,
                knowledge_context,
                question_messages,
                action="knowledge_silent_skipped",
                screening_status="silent",
                answer="",
                knowledge_hit=silent_hit,
                force_save=True,
            )
            append_recruiter_user_questions(user_question_items)
            append_recruiter_unclear_questions(user_question_items)
            message = (
                "命中知识库沉默规则，本轮不回复也不继续推进："
                f"{safe_text(str(silent_hit.get('matchedPattern') or ''), 80)}"
            )
            self.add_event("chat", message)
            return {
                "answered": False,
                "skipped": True,
                "silentSkipped": True,
                "skipReason": "silent_question",
                "message": message,
                "knowledgeHit": silent_hit,
                "knowledgeAnsweredSignatures": state_payload["knowledgeAnsweredSignatures"],
                "basis": {
                    "questionMessages": state_payload["knowledgeQuestionMessages"],
                    "matchedPattern": state_payload["knowledgeMatchedPattern"],
                },
            }
        if not question_messages:
            return {}

        last_other = knowledge_context.get("lastOtherMessage") if isinstance(knowledge_context.get("lastOtherMessage"), dict) else {}
        last_other_text = str(last_other.get("text") or "").strip()
        knowledge_signatures = knowledge_context.get("knowledgeQuestionSignatures")
        if not isinstance(knowledge_signatures, list):
            knowledge_signatures = [chat_message_signature(item) for item in question_messages if chat_message_signature(item)]
        answered_signatures = normalize_answered_message_signatures(previous_state)
        if knowledge_signatures and all(str(item) in answered_signatures for item in knowledge_signatures):
            return {}
        hit = {}
        if has_model_key():
            try:
                hit = ask_agent_model_for_company_knowledge_reply(knowledge_context)
            except Exception as error:
                hit = {
                    "source": "companyKnowledgeBase.model_error",
                    "error": safe_text(str(error), 160),
                }
        if not hit.get("answer"):
            hit = match_company_knowledge_answer(knowledge_context)
        if not hit.get("answer"):
            hit = context.get("companyKnowledgeHit") if isinstance(context.get("companyKnowledgeHit"), dict) else {}
        answer = strip_reply_terminal_punctuation(str(hit.get("answer") or "").strip())
        if not answer:
            if hit.get("answerSkipped") or hit.get("unknownSkipped"):
                user_question_items = build_recruiter_unclear_question_items(
                    candidate_label,
                    knowledge_context,
                    question_messages,
                    action="knowledge_unknown_skipped",
                    screening_status="unclear",
                    answer="",
                    knowledge_hit=hit,
                )
                append_recruiter_user_questions(user_question_items)
                append_recruiter_unclear_questions(user_question_items)
            return {}
        if is_unknown_knowledge_reply(answer, knowledge_context):
            user_question_items = build_recruiter_unclear_question_items(
                candidate_label,
                knowledge_context,
                question_messages,
                action="knowledge_unknown_skipped",
                screening_status="unclear",
                answer="",
                knowledge_hit={**hit, "source": str(hit.get("source") or "companyKnowledgeBase.unknown_skipped"), "unknownSkipped": True},
            )
            append_recruiter_user_questions(user_question_items)
            append_recruiter_unclear_questions(user_question_items)
            return {}
        last_other_signature = str(knowledge_context.get("lastOtherSignature") or chat_message_signature(last_other))
        if (
            previous_state.get("status") == "knowledge_answered_waiting"
            and last_other_signature
            and previous_state.get("lastOtherSignature") == last_other_signature
        ):
            return {}
        answer = avoid_repeated_reply(answer, context)
        if callable(send_message):
            label = "平台聊天输入框"
            send_result = send_message(answer)
            verification = send_result.get("verify") if isinstance(send_result, dict) and isinstance(send_result.get("verify"), dict) else {
                "verified": bool(isinstance(send_result, dict) and not send_result.get("blocked") and send_result.get("verified", True))
            }
            if isinstance(send_result, dict) and send_result.get("sent") and not send_result.get("blocked") and not verification.get("verified"):
                verification = {**verification, "verified": True, "source": "send_result_clicked_and_cleared"}
            send_package = {"send": send_result, "verification": verification, "attempts": [send_result] if isinstance(send_result, dict) else []}
        else:
            label = self.smart_fill(terminal, "聊天", answer)
            send_package = self.send_current_chat_reply_with_verification(
                terminal,
                answer,
                max_attempts=CHAT_SEND_MAX_ATTEMPTS,
            )
            send_result = send_package.get("send", {})
            verification = send_package.get("verification", {})
        if not verification.get("verified"):
            return {
                "blocked": True,
                "message": f"已填写知识库回复，但没有确认发送成功：{safe_text(answer, 80)}",
                "answer": answer,
                "knowledgeHit": hit,
                "inputLabel": safe_text(label, 80),
                "send": send_result,
            }
        state_payload = {
            "candidateLabel": safe_text(candidate_label, 160),
            "knowledgeTopic": safe_text(str(hit.get("topic") or ""), 80),
            "knowledgeSubQueries": hit.get("subQueries", [])[:4] if isinstance(hit.get("subQueries"), list) else [],
            "knowledgeAnswer": safe_text(answer, 80),
            "lastOtherSignature": last_other_signature,
            "lastOther": safe_text(str(last_other.get("text") or ""), 180),
            "knowledgeAnsweredSignatures": [str(item) for item in knowledge_signatures if str(item or "").strip()][-RECENT_UNANSWERED_OTHER_LIMIT:],
            "knowledgeQuestionMessages": [
                safe_text(str(item.get("text") or ""), 180)
                for item in question_messages
                if isinstance(item, dict)
            ],
            "knowledgeEvidence": hit.get("selectedEvidence", [])[:5] if isinstance(hit.get("selectedEvidence"), list) else hit.get("hits", [])[:5] if isinstance(hit.get("hits"), list) else [],
        }
        if conversation_key:
            self.set_chat_state(conversation_key, "knowledge_answered_waiting", **state_payload)
        if candidate_state_key:
            self.set_chat_state(candidate_state_key, "knowledge_answered_waiting", **state_payload)
        self.set_recruiter_basic_state(
            conversation_key,
            candidate_label,
            "knowledge_answered_waiting",
            context=context,
            **state_payload,
        )
        sub_queries = state_payload.get("knowledgeSubQueries") if isinstance(state_payload.get("knowledgeSubQueries"), list) else []
        if sub_queries:
            message = f"已按知识库回复候选人问题：{safe_text(answer, 80)}（覆盖：{safe_text('；'.join(str(item) for item in sub_queries), 120)}）"
        else:
            message = f"已按知识库回复候选人问题：{safe_text(answer, 80)}"
        user_question_items = build_recruiter_unclear_question_items(
            candidate_label,
            knowledge_context,
            question_messages,
            action="knowledge_answered",
            screening_status="answered",
            answer=answer,
            knowledge_hit=hit,
        )
        append_recruiter_user_questions(user_question_items)
        if is_unknown_knowledge_reply(answer, knowledge_context):
            for item in user_question_items:
                item["action"] = "knowledge_unknown_answer_sent"
                item["screeningStatus"] = "unclear"
            append_recruiter_unclear_questions(user_question_items)
        self.add_event("chat", message)
        return {
            "answered": True,
            "message": message,
            "answer": answer,
            "knowledgeHit": hit,
            "inputLabel": safe_text(label, 80),
            "send": send_result,
            "verification": verification,
            "attempts": send_package.get("attempts", []),
            "knowledgeAnsweredSignatures": state_payload["knowledgeAnsweredSignatures"],
            "basis": {
                "questionMessages": state_payload["knowledgeQuestionMessages"],
                "subQueries": state_payload["knowledgeSubQueries"],
                "evidence": state_payload["knowledgeEvidence"],
                "answer": safe_text(answer, 120),
            },
        }

    def answer_current_recruiter_questions(
        self,
        terminal: BrowserTerminal,
        target_candidate: str = "",
    ) -> dict:
        self.check_pause()
        opened = None
        target_candidate = clean_recruiter_candidate_name(target_candidate)
        if target_candidate:
            current = read_recruiter_selected_candidate(terminal)
            current_label = str(current.get("label") or "")
            if candidate_label_matches(current_label, target_candidate):
                opened = {"label": current_label, "matchedBy": "current", "targetCandidate": target_candidate}
            else:
                target = find_recruiter_candidate_by_name(terminal, target_candidate, scroll_attempts=10)
                if not target:
                    return {
                        "blocked": True,
                        "message": f"没有在当前招聘会话列表里找到候选人：{safe_text(target_candidate, 40)}。",
                        "targetCandidate": target_candidate,
                    }
                locator = target.get("locator")
                if locator is None:
                    return {
                        "blocked": True,
                        "message": f"找到了候选人：{safe_text(target_candidate, 40)}，但没有拿到可点击元素。",
                        "candidate": {k: v for k, v in target.items() if k != "locator"},
                        "targetCandidate": target_candidate,
                    }
                if terminal.humanize:
                    terminal.pause_like_person("pre_action")
                    highlight_target(locator)
                humanized_locator_click(terminal, locator, force=True)
                if terminal.humanize:
                    terminal.pause_like_person("post_action")
                terminal.current_page().wait_for_timeout(random.randint(900, 1400))
                opened = {k: v for k, v in target.items() if k != "locator"}
                maybe_human_reading_pause(terminal, reason="candidate_open", text_hint=str(opened.get("label") or ""))

        history = self.load_chat_history(terminal, max_rounds=CHAT_HISTORY_SCROLL_ROUNDS)
        context = self.read_chat_context(terminal, history=history)
        candidate = read_recruiter_selected_candidate(terminal)
        candidate_label = str(candidate.get("label") or "")
        knowledge_base = context.get("companyKnowledgeBase") if isinstance(context.get("companyKnowledgeBase"), dict) else {}
        position_reply = context.get("positionReply") if isinstance(context.get("positionReply"), dict) else {}
        position_screening = knowledge_base.get("screening") if isinstance(knowledge_base.get("screening"), dict) else {}
        applied_position = safe_text(str(context.get("appliedPosition") or ""), 80)
        if is_unconfigured_recruiter_position(context, position_reply, position_screening):
            return {
                "message": f"当前岗位未添加到知识库，已按规则跳过不回复：{applied_position or '未识别岗位'}。",
                "candidate": candidate,
                "opened": opened,
                "answered": False,
                "skippedUnconfiguredPosition": True,
            }
        conversation_key = str(context.get("conversationKey") or "")
        candidate_state_key = recruiter_basic_candidate_state_key(candidate_label)
        previous_state = self.get_chat_state(conversation_key) or self.get_chat_state(candidate_state_key)
        result = self.answer_recruiter_knowledge_question(
            terminal,
            context,
            candidate_label,
            conversation_key,
            candidate_state_key,
            previous_state=previous_state,
        )
        if knowledge_result_stops_flow(result):
            return {
                **result,
                "candidate": candidate,
                "opened": opened,
            }
        return {
            "message": f"当前候选人没有检测到需要知识库回复的未处理问题：{safe_text(candidate_label, 80)}。",
            "candidate": candidate,
            "opened": opened,
            "answered": False,
        }

    def _run_job51_terminal_sync(self, callback):
        terminal_obj = BrowserTerminal(
            JOB51_CDP_URL,
            page_index=0,
            auto_start=False,
            visual_cursor=True,
            humanize=True,
            pace="normal",
        )
        terminal = None
        try:
            terminal = terminal_obj.__enter__()
            terminal.automation_speed_multiplier = self.automation_speed_multiplier
            apply_automation_speed_multiplier(terminal)
            job51_pages = []
            for page in terminal.all_pages():
                url = str(getattr(page, "url", "") or "")
                try:
                    title = page.title()
                except Exception:
                    title = ""
                is_ehire_page = "://ehire.51job.com" in url
                is_chat_page = is_ehire_page and "/Revision/chat" in url
                is_job51_page = is_ehire_page or "51job" in title or ("51job.com" in url and "webchat.7moor.com" not in url)
                if is_job51_page:
                    job51_pages.append((0 if is_chat_page else 1 if is_ehire_page else 2, page))
            if job51_pages:
                job51_pages.sort(key=lambda item: item[0])
                terminal.page = job51_pages[0][1]
            return callback(terminal)
        finally:
            if terminal is not None:
                try:
                    terminal_obj.__exit__(None, None, None)
                except Exception:
                    pass

    def with_job51_terminal(self, callback, timeout_seconds: int | None = None):
        result_box: dict[str, object] = {}

        def worker() -> None:
            try:
                result_box["result"] = self._run_job51_terminal_sync(callback)
            except Exception as error:
                result_box["error"] = error

        timeout = max(30, int(timeout_seconds or JOB51_WORKER_TIMEOUT_SECONDS))
        thread = threading.Thread(target=worker, name="job51-playwright-worker", daemon=True)
        thread.start()
        thread.join(timeout)
        if thread.is_alive():
            raise TimeoutError(f"51job 浏览器操作超过 {timeout} 秒仍未返回，已停止等待；请检查 51 页面是否卡在弹窗、简历预览或发送确认上。")
        if "error" in result_box:
            raise result_box["error"]  # type: ignore[misc]
        return result_box.get("result")

    def job51_dismiss_interruptions(self, terminal: BrowserTerminal, reason: str = "") -> dict:
        page = terminal.current_page()
        closed: list[dict] = []
        for _ in range(5):
            target = safe_eval(page, """() => {
              const normalize = value => String(value || '').replace(/\\s+/g, ' ').trim();
              const visible = el => {
                if (!el || !el.isConnected) return false;
                const box = el.getBoundingClientRect();
                const style = window.getComputedStyle(el);
                return box.width > 6 && box.height > 6
                  && style.display !== 'none'
                  && style.visibility !== 'hidden'
                  && style.opacity !== '0'
                  && box.bottom >= 0
                  && box.right >= 0
                  && box.top <= window.innerHeight
                  && box.left <= window.innerWidth;
              };
              const rect = el => {
                const box = el.getBoundingClientRect();
                return { x: Math.round(box.x), y: Math.round(box.y), w: Math.round(box.width), h: Math.round(box.height) };
              };
              const candidates = [];
              const add = (el, reason, score) => {
                if (!el || !visible(el)) return;
                candidates.push({
                  reason,
                  score,
                  text: normalize(el.innerText || el.textContent || ''),
                  className: String(el.className || ''),
                  tag: el.tagName,
                  rect: rect(el)
                });
                el.setAttribute('data-codex-job51-dismiss', '1');
              };
              const exactCloseText = /^(关闭|跳过|知道了|我知道了|稍后再说|暂不使用|不用了|取消|不感兴趣|×|x)$/i;
              const softCloseText = /(不感兴趣|暂不|稍后|关闭|跳过|知道了|我知道了)/;
              const blockerRoots = Array.from(document.querySelectorAll([
                '#driver-popover-item',
                '.ai-guide-dialog',
                '.wechat-notify',
                '.el-message-box__wrapper',
                '.el-dialog__wrapper',
                '.el-popover',
                '.driver-popover',
                '[class*="guide" i]',
                '[class*="advert" i]',
                '[class*="ad-" i]'
              ].join(','))).filter(visible);
              for (const root of blockerRoots) {
                const rootText = normalize(root.innerText || root.textContent || '');
                const rootClass = String(root.className || '');
                const looksBlocking = /(AI|推荐|广告|微信通知|新人才|意向推荐|学生频道|开通|去开启|简历不错过|智能回复|助手|提示)/.test(rootText + ' ' + rootClass);
                if (!looksBlocking && !root.matches('#driver-popover-item,.ai-guide-dialog,.wechat-notify,.el-message-box__wrapper')) continue;
                const buttons = Array.from(root.querySelectorAll('button,[role="button"],.close,.el-icon-close,[class*="close" i],[class*="cancel" i]'));
                for (const btn of buttons) {
                  const text = normalize(btn.innerText || btn.textContent || btn.getAttribute('aria-label') || btn.getAttribute('title') || '');
                  const cls = String(btn.className || '');
                  if (exactCloseText.test(text) || softCloseText.test(text) || /close|cancel|driver-close|icon-close/i.test(cls)) {
                    add(btn, `close_blocker:${rootText.slice(0, 40) || rootClass.slice(0, 40)}`, text === '不感兴趣' ? 140 : 120);
                  }
                }
              }
              const directSelectors = [
                'button.ai-guide-btn-no',
                'button.driver-close-btn',
                '.wechat-notify .close',
                '.wechat-notify .el-icon-close',
                '.ai-guide-dialog button.ai-guide-btn-no'
              ];
              for (const selector of directSelectors) {
                for (const el of Array.from(document.querySelectorAll(selector))) add(el, `selector:${selector}`, 160);
              }
              const target = candidates.sort((a, b) => b.score - a.score)[0];
              if (!target) return null;
              return target;
            }""")
            if not isinstance(target, dict):
                break
            locator = page.locator("[data-codex-job51-dismiss='1']").first
            try:
                if locator.count():
                    locator.click(timeout=3000, force=True)
                    page.wait_for_timeout(random.randint(260, 620))
                    closed.append({
                        "reason": safe_text(str(target.get("reason") or reason or "dismissed"), 120),
                        "text": safe_text(str(target.get("text") or ""), 80),
                        "className": safe_text(str(target.get("className") or ""), 80),
                    })
            except Exception as error:
                closed.append({
                    "reason": "dismiss_failed",
                    "text": safe_text(str(target.get("text") or ""), 80),
                    "error": safe_text(str(error), 120),
                })
                break
            finally:
                try:
                    page.locator("[data-codex-job51-dismiss='1']").evaluate_all("els => els.forEach(el => el.removeAttribute('data-codex-job51-dismiss'))")
                except Exception:
                    pass
        return {"closed": closed, "count": len(closed), "reason": reason}

    def job51_open_chat_page(self, terminal: BrowserTerminal) -> dict:
        page = terminal.current_page()
        self.job51_dismiss_interruptions(terminal, reason="before_open_chat")
        if "ehire.51job.com" in str(page.url) and "/Revision/chat" in str(page.url):
            return {"opened": True, "url": page.url, "title": page.title(), "source": "current"}
        nav = page.locator("#sensor_talentcommunicate").first
        try:
            if nav.count():
                if terminal.humanize:
                    terminal.pause_like_person("pre_action")
                    highlight_target(nav)
                humanized_locator_click(terminal, nav, force=True)
                if terminal.humanize:
                    terminal.pause_like_person("post_action")
                page.wait_for_timeout(random.randint(1200, 1800))
                return {"opened": True, "url": page.url, "title": page.title(), "source": "left_nav"}
        except Exception:
            pass
        page.goto(JOB51_CHAT_URL, wait_until="domcontentloaded", timeout=15000)
        page.wait_for_timeout(random.randint(1200, 1800))
        return {"opened": True, "url": page.url, "title": page.title(), "source": "goto"}

    def job51_select_all_positions(self, terminal: BrowserTerminal) -> dict:
        page = terminal.current_page()
        self.job51_dismiss_interruptions(terminal, reason="before_select_all_positions")
        token = f"codex_job51_all_positions_{int(time.time() * 1000)}_{random.randint(1000, 9999)}"
        result = safe_eval(page, """token => {
          const normalize = value => String(value || '').replace(/\\s+/g, ' ').trim();
          const visible = el => {
            const box = el.getBoundingClientRect();
            const style = window.getComputedStyle(el);
            return box.width > 4 && box.height > 4 && style.display !== 'none' && style.visibility !== 'hidden';
          };
          const selectors = [
            '.position-menu .menu-item',
            '.position-menu [class*="menu-item"]',
            '[class*="position-menu"] [class*="menu-item"]',
            '[class*="position"] [class*="menu-item"]',
            '.menu-item_content_short',
            '.menu-item-all'
          ];
          const seen = new Set();
          const nodes = [];
          for (const selector of selectors) {
            for (const el of Array.from(document.querySelectorAll(selector))) {
              if (seen.has(el)) continue;
              seen.add(el);
              nodes.push(el);
            }
          }
          if (!nodes.length) {
            for (const el of Array.from(document.querySelectorAll('button,[role="button"],a')).slice(0, 300)) {
              const text = normalize(el.textContent || '');
              if (/全部岗位|全部职位|^全部$/.test(text)) nodes.push(el);
            }
          }
          const candidates = nodes.filter(visible).map(el => {
            const text = normalize(el.textContent || '');
            const cls = String(el.className || '');
            const box = el.getBoundingClientRect();
            let score = 0;
            if (/menu-item-all/.test(cls)) score += 300;
            if (/position|menu-item/.test(cls)) score += 80;
            if (/^全部岗位$|^全部职位$/.test(text)) score += 500;
            else if (/全部岗位|全部职位/.test(text) && text.length <= 20) score += 360;
            else if (/^全部$/.test(text)) score += 180;
            if (/is-active|active|selected|checked/.test(cls)) score += 30;
            return { el, text, cls, score, y: box.y };
          }).filter(item => item.score > 0).sort((a, b) => b.score - a.score || a.y - b.y);
          const best = candidates[0];
          if (!best) return { selected: false, reason: 'all_positions_not_found' };
          best.el.setAttribute('data-codex-job51-all-positions', token);
          return {
            selected: true,
            label: best.text,
            className: best.cls,
            alreadyActive: /is-active|active|selected|checked/.test(best.cls)
          };
        }""", token)
        if not isinstance(result, dict) or not result.get("selected"):
            return result if isinstance(result, dict) else {"selected": False, "reason": "all_positions_not_found"}
        if result.get("alreadyActive"):
            return {**result, "clicked": False}
        locator = page.locator(f"[data-codex-job51-all-positions='{token}']").first
        try:
            if terminal.humanize:
                terminal.pause_like_person("pre_action")
                highlight_target(locator)
            humanized_locator_click(terminal, locator, force=True)
            if terminal.humanize:
                terminal.pause_like_person("post_action")
            page.wait_for_timeout(random.randint(900, 1400))
            return {**result, "clicked": True}
        except Exception as error:
            return {"selected": False, "reason": safe_text(str(error), 160), "state": result}
        finally:
            try:
                page.locator("[data-codex-job51-all-positions]").evaluate_all("els => els.forEach(el => el.removeAttribute('data-codex-job51-all-positions'))")
            except Exception:
                pass

    def job51_prepare_unread_filter(self, terminal: BrowserTerminal) -> dict:
        page = terminal.current_page()
        self.job51_dismiss_interruptions(terminal, reason="before_unread_filter")
        unread = page.locator("label.el-checkbox.btn.unread-checkbox").first
        try:
            if not unread.count():
                return {"found": False, "reason": "unread_checkbox_not_found"}
            state = unread.evaluate("""el => ({
              checked: el.classList.contains('is-checked') || !!el.querySelector('input:checked'),
              text: String(el.innerText || el.textContent || '').replace(/\\s+/g, ' ').trim()
            })""")
            if not isinstance(state, dict):
                state = {}
            if not state.get("checked"):
                if terminal.humanize:
                    terminal.pause_like_person("pre_action")
                    highlight_target(unread)
                humanized_locator_click(terminal, unread, force=True)
                if terminal.humanize:
                    terminal.pause_like_person("post_action")
                page.wait_for_timeout(random.randint(900, 1300))
                return {"found": True, "clicked": True, "state": state}
            return {"found": True, "clicked": False, "state": state}
        except Exception as error:
            return {"found": False, "reason": safe_text(str(error), 160)}

    def job51_find_next_thread(
        self,
        terminal: BrowserTerminal,
        exclude_labels: list[str] | None = None,
        allowed_positions: tuple[str, ...] | list[str] = JOB51_CONFIGURED_POSITIONS,
    ) -> dict | None:
        exclude_labels = exclude_labels or []
        allowed_clean = [clean_applied_position(item) for item in allowed_positions if clean_applied_position(item)]
        page = terminal.current_page()
        rows = page.locator("#conversation-list .list-item")
        try:
            count = rows.count()
        except Exception:
            count = 0
        for index in range(count):
            row = rows.nth(index)
            try:
                label = safe_text(row.inner_text(timeout=800), 300)
            except Exception:
                continue
            label_key = compact_conversation_label(label)
            if not label or any(compact_conversation_label(item) and compact_conversation_label(item) in label_key for item in exclude_labels):
                continue
            if "平台推荐" in label or "为你推荐的人才" in label:
                continue
            if re.search(r"\[(送达|已读)\]", label):
                continue
            job = safe_text(safe_eval(page, f"""() => {{
              const row = document.querySelectorAll('#conversation-list .list-item')[{index}];
              const node = row ? row.querySelector('.jobname') : null;
              return node ? String(node.innerText || node.textContent || '').replace(/\\s+/g, ' ').trim() : '';
            }}""") or "", 100)
            if not job and re.search(r"\[(平台推荐|推荐)\]", label):
                continue
            clean_job = clean_applied_position(job or label)
            clean_label = clean_applied_position(label)
            if allowed_clean and not any(
                pos in clean_job
                or clean_job in pos
                or pos in clean_label
                or job51_position_label_matches(clean_job, pos)
                or job51_position_label_matches(clean_label, pos)
                for pos in allowed_clean
            ):
                continue
            try:
                box = row.bounding_box(timeout=1000)
            except Exception:
                box = None
            return {
                "index": index,
                "label": label,
                "job": job,
                "locator": row,
                "x": round(box["x"]) if box else None,
                "y": round(box["y"]) if box else None,
            }
        return None

    def job51_scroll_conversation_list(self, terminal: BrowserTerminal) -> dict:
        page = terminal.current_page()
        result = safe_eval(page, """() => {
          const el = document.querySelector('#conversation-list');
          if (!el) return { scrolled: false, reason: 'missing_list' };
          const before = el.scrollTop || 0;
          el.scrollTop = before + Math.max(260, Math.floor((el.clientHeight || 500) * 0.85));
          el.dispatchEvent(new Event('scroll', { bubbles: true }));
          return { scrolled: Math.abs((el.scrollTop || 0) - before) > 2, before, after: el.scrollTop || 0 };
        }""")
        page.wait_for_timeout(random.randint(520, 860))
        return result if isinstance(result, dict) else {"scrolled": False}

    def job51_wait_chat_ready(self, terminal: BrowserTerminal, timeout_ms: int = 5000) -> bool:
        try:
            terminal.current_page().wait_for_selector("#drop-area.input-textarea_self, #drop-area", timeout=timeout_ms)
            return True
        except Exception:
            return False

    def job51_extract_chat_messages(self, terminal: BrowserTerminal) -> list[dict]:
        page = terminal.current_page()
        messages = safe_eval(page, """() => {
          const normalize = value => String(value || '').replace(/\\s+/g, ' ').trim();
          const visible = el => {
            const box = el.getBoundingClientRect();
            const style = window.getComputedStyle(el);
            return box.width > 4 && box.height > 4 && style.display !== 'none' && style.visibility !== 'hidden' && style.opacity !== '0';
          };
          const rows = Array.from(document.querySelectorAll('div.message-item.mine, div.message-item.others'));
          return rows.filter(visible).map(row => {
            const box = row.getBoundingClientRect();
            const cls = String(row.className || '');
            const sender = cls.includes('mine') ? 'me' : 'other';
            let text = normalize(row.innerText || row.textContent || '');
            text = text.replace(/^未读\\s+/, '').trim();
            return {
              sender,
              text,
              rawText: normalize(row.innerText || row.textContent || ''),
              className: cls,
              x: Math.round(box.x),
              y: Math.round(box.y)
            };
          }).filter(item => item.text && !/^\\d{1,2}:\\d{2}$/.test(item.text)).slice(-120);
        }""")
        if not isinstance(messages, list):
            return []
        out: list[dict] = []
        for item in messages:
            if not isinstance(item, dict):
                continue
            text = safe_text(str(item.get("text") or "").strip(), 500)
            if not text:
                continue
            sender = str(item.get("sender") or "")
            if sender not in {"me", "other"}:
                continue
            out.append({
                "sender": sender,
                "text": text,
                "rawText": safe_text(str(item.get("rawText") or text), 600),
                "status": "",
                "time": "",
                "className": safe_text(str(item.get("className") or ""), 120),
                "x": item.get("x"),
                "y": item.get("y"),
            })
        return out

    @timed_agent_stage("job51_verify_reply_sent", "51job发送后检查")
    def job51_verify_reply_sent_in_current_chat(self, terminal: BrowserTerminal, text: str) -> dict:
        expected = normalize_reply_fingerprint(str(text or ""))
        if not expected:
            return {"verified": False, "reason": "empty_expected"}
        try:
            terminal.current_page().wait_for_timeout(random.randint(650, 1050))
            messages = self.job51_extract_chat_messages(terminal)
        except Exception as error:
            return {"verified": False, "reason": safe_text(str(error), 160)}
        last_my: dict = {}
        for item in reversed(messages[-12:]):
            if not isinstance(item, dict) or item.get("sender") != "me":
                continue
            last_my = item
            actual = normalize_reply_fingerprint(str(item.get("text") or ""))
            if expected and actual and (expected in actual or actual in expected):
                return {
                    "verified": True,
                    "message": safe_text(str(item.get("text") or ""), 120),
                    "source": "job51_message_item",
                }
        current_input = safe_text(str(safe_eval(
            terminal.current_page(),
            "() => String((document.querySelector('#drop-area') || {}).innerText || '')",
        ) or ""), 240)
        return {
            "verified": False,
            "reason": "reply_not_found_in_recent_51job_my_messages",
            "lastMy": safe_text(str(last_my.get("text") or ""), 120) if isinstance(last_my, dict) else "",
            "inputContainsExpected": bool(expected and expected in normalize_reply_fingerprint(current_input)),
            "inputText": current_input,
        }

    def job51_read_chat_context(
        self,
        terminal: BrowserTerminal,
        history: dict | None = None,
        opened: dict | None = None,
    ) -> dict:
        page = terminal.current_page()
        text = safe_eval(page, "() => document.body ? document.body.innerText : ''") or ""
        header = safe_eval(page, """() => {
          const normalize = value => String(value || '').replace(/\\s+/g, ' ').trim();
          const nameNode = document.querySelector('div.im_userName span.username-text, div.im_userName, span.username-text');
          const selected = Array.from(document.querySelectorAll('#conversation-list .list-item')).find(el => {
            const cls = String(el.className || '');
            return /active|current|selected|checked/i.test(cls);
          });
          const jobNode = selected ? selected.querySelector('.jobname') : null;
          return {
            name: normalize(nameNode ? (nameNode.innerText || nameNode.textContent || '') : ''),
            selectedLabel: normalize(selected ? (selected.innerText || selected.textContent || '') : ''),
            selectedJob: normalize(jobNode ? (jobNode.innerText || jobNode.textContent || '') : '')
          };
        }""") or {}
        messages = self.job51_extract_chat_messages(terminal)
        opened = opened if isinstance(opened, dict) else {}
        opened_label = str(opened.get("label") or "")
        opened_job = str(opened.get("job") or "")
        selected_label = str((header or {}).get("selectedLabel") or "")
        selected_job = str((header or {}).get("selectedJob") or "")
        header_name = safe_text(str((header or {}).get("name") or ""), 60)
        opened_name = safe_text(str(recruiter_candidate_name_from_label(opened_label)), 60)
        selected_name = safe_text(str(recruiter_candidate_name_from_label(selected_label)), 60)
        applicant_name = safe_text(str(opened_name or header_name or selected_name), 60)
        applied_position = clean_applied_position(str(opened_job or ""))
        identity_warnings: list[dict] = []
        if opened_name and header_name and not recruiter_candidate_names_match(opened_name, header_name):
            identity_warnings.append({
                "type": "opened_header_name_mismatch",
                "openedName": opened_name,
                "headerName": header_name,
            })
        if opened_name and selected_name and not recruiter_candidate_names_match(opened_name, selected_name):
            identity_warnings.append({
                "type": "opened_selected_name_mismatch",
                "openedName": opened_name,
                "selectedName": selected_name,
            })
        if not applied_position and not identity_warnings:
            applied_position = clean_applied_position(selected_job)
        if not applied_position and opened_label:
            for position in JOB51_CONFIGURED_POSITIONS:
                if clean_applied_position(position) in clean_applied_position(opened_label):
                    applied_position = clean_applied_position(position)
                    break
        if not applied_position and applicant_name:
            haystack = str(text or "")
            name_index = haystack.find(applicant_name)
            while name_index >= 0 and not applied_position:
                after_name = haystack[name_index: name_index + 900]
                communication_match = re.search(r"沟通职位[:：]\s*([^\r\n]{1,120})", after_name)
                if communication_match:
                    communication_text = clean_applied_position(communication_match.group(1))
                    for position in JOB51_CONFIGURED_POSITIONS:
                        if clean_applied_position(position) in communication_text:
                            applied_position = clean_applied_position(position)
                            break
                if applied_position:
                    break
                nearby = haystack[name_index: name_index + 240]
                for position in JOB51_CONFIGURED_POSITIONS:
                    if clean_applied_position(position) in clean_applied_position(nearby):
                        applied_position = clean_applied_position(position)
                        break
                name_index = haystack.find(applicant_name, name_index + max(1, len(applicant_name)))
        recent_source = str(history.get("text") or "") if isinstance(history, dict) and history.get("text") else text
        last_message = last_effective_chat_message(messages)
        last_other = last_effective_chat_message(messages, sender="other")
        boss_rules = load_boss_chat_rules()
        position_reply = select_position_reply(applied_position, boss_rules)
        company_knowledge_base = select_company_knowledge_base(boss_rules, applied_position)
        label = safe_text(opened_label or selected_label or applicant_name, 180)
        conversation_key = build_conversation_key(page.url, messages, label or applicant_name)
        context = {
            "title": page.title(),
            "url": page.url,
            "platform": "51job",
            "recentText": safe_text(recent_source, 1600),
            "pageTextPreview": safe_text(text, 900),
            "applicant": {
                "name": applicant_name,
                "appliedPosition": applied_position,
                "label": label,
                "source": "51job-chat",
                "openedLabel": safe_text(opened_label, 180),
                "openedName": opened_name,
                "headerName": header_name,
                "selectedLabel": safe_text(selected_label, 180),
                "selectedName": selected_name,
                "selectedJob": clean_applied_position(selected_job),
                "identityWarnings": identity_warnings,
                "headerNameMismatch": any(item.get("type") == "opened_header_name_mismatch" for item in identity_warnings),
            },
            "appliedPosition": applied_position,
            "positionReply": position_reply,
            "companyKnowledgeBase": company_knowledge_base,
            "loadedHistory": history or {},
            "messages": messages[-80:],
            "lastMessage": last_message,
            "lastOtherMessage": last_other,
            "lastSender": last_message.get("sender") if last_message else "",
            "lastOtherSignature": chat_message_signature(last_other) if last_other else "",
            "shouldReply": bool(last_message and last_message.get("sender") == "other"),
            "intent": classify_chat_intent(last_other.get("text", "") if last_other else ""),
            "conversationKey": conversation_key,
            "summary": f"51job 当前会话：{safe_text(label, 80)}；岗位：{safe_text(applied_position, 60)}",
        }
        context["memory"] = self.refresh_chat_memory(context, conversation_key)
        context["companyKnowledgeHit"] = match_company_knowledge_answer(context)
        return context

    @timed_agent_stage("job51_send_message", "51job 发送消息")
    def job51_send_message_with_verification(self, terminal: BrowserTerminal, text: str) -> dict:
        text = strip_reply_terminal_punctuation(str(text or "").strip())
        if not text:
            return {"blocked": True, "message": "51job 待发送内容为空"}
        page = terminal.current_page()
        self.job51_dismiss_interruptions(terminal, reason="before_send_message")
        input_locator = page.locator("#drop-area.input-textarea_self, #drop-area, [contenteditable='true']").first
        try:
            if not input_locator.count():
                return {"blocked": True, "message": "51job 没有找到聊天输入框 #drop-area，已停止避免填错位置"}
            else:
                if terminal.humanize:
                    terminal.pause_like_person("pre_action")
                    highlight_target(input_locator)
                    humanized_locator_click(terminal, input_locator, force=True)
                input_locator.fill("", timeout=8000)
                input_locator.type(text, delay=random.randint(CHAT_TYPE_DELAY_MS[0], CHAT_TYPE_DELAY_MS[1]), timeout=12000)
                if terminal.humanize:
                    terminal.pause_like_person("post_action")
                label = "#drop-area.input-textarea_self"
        except Exception as error:
            return {
                "blocked": True,
                "message": f"51job 填写聊天输入框失败，已停止避免填错位置：{safe_text(str(error), 160)}",
            }
        page.wait_for_timeout(random.randint(260, 520))
        self.job51_dismiss_interruptions(terminal, reason="after_fill_before_send")
        send_button = page.locator("button.el-button.new-send-button.el-button--primary, button.new-send-button").first
        if not send_button.count():
            send_package = self.send_current_chat_reply_with_verification(terminal, text, max_attempts=CHAT_SEND_MAX_ATTEMPTS)
            return {
                "message": "51job 已尝试通过通用发送按钮发送",
                "inputLabel": safe_text(label, 80),
                "send": send_package.get("send", {}),
                "verification": send_package.get("verification", {}),
                "attempts": send_package.get("attempts", []),
                "blocked": not bool((send_package.get("verification") or {}).get("verified")),
            }
        if terminal.humanize:
            terminal.pause_like_person("pre_action")
            highlight_target(send_button)
        send_button.click(timeout=8000, force=True)
        if terminal.humanize:
            terminal.pause_like_person("post_action")
        page.wait_for_timeout(random.randint(720, 1120))
        current_input = safe_text(str(safe_eval(page, "() => String((document.querySelector('#drop-area') || {}).innerText || '')") or ""), 240)
        if normalize_reply_fingerprint(text) in normalize_reply_fingerprint(current_input):
            try:
                self.job51_dismiss_interruptions(terminal, reason="send_retry_blocked_by_overlay")
            except Exception:
                pass
            try:
                send_button.click(timeout=8000, force=True)
                page.wait_for_timeout(random.randint(900, 1300))
            except Exception:
                pass
        verification = self.job51_verify_reply_sent_in_current_chat(terminal, text)
        return {
            "message": "51job 已发送并校验" if verification.get("verified") else "51job 已点击发送，但未在最近消息中校验到文本",
            "inputLabel": safe_text(label, 80),
            "send": {"message": "clicked 51job send button", "blocked": not bool(verification.get("verified"))},
            "verification": verification,
            "blocked": not bool(verification.get("verified")),
        }

    @timed_agent_stage("job51_send_common_word", "51job 发送常用语")
    def job51_send_common_word_with_verification(self, terminal: BrowserTerminal, phrase: str) -> dict:
        phrase = safe_text(str(phrase or "").strip(), 400)
        if not phrase:
            return {"blocked": True, "message": "51job 待发送常用语为空"}
        page = terminal.current_page()
        self.job51_dismiss_interruptions(terminal, reason="before_send_common_word")
        if not self.job51_wait_chat_ready(terminal, timeout_ms=3500):
            return {
                "blocked": True,
                "message": "51job 当前不是单聊输入页，未发送常用语，避免在批量/列表页误操作。",
            }

        safe_eval(page, """() => {
          const editor = document.querySelector('#drop-area.input-textarea_self, #drop-area');
          if (!editor) return false;
          editor.focus();
          editor.innerHTML = '';
          editor.textContent = '';
          editor.dispatchEvent(new InputEvent('input', { bubbles: true, inputType: 'deleteContentBackward', data: null }));
          editor.dispatchEvent(new Event('change', { bubbles: true }));
          return true;
        }""")

        button = {}
        if not is_job51_common_word_panel_open(terminal):
            button = self.measure_current_timing_stage(
                "job51_find_common_word_button",
                "51job 查找常用语按钮",
                lambda: find_job51_common_word_button(terminal),
            )
            if not button.get("found"):
                return {
                    "blocked": True,
                    "message": "51job 没有找到单聊工具栏里的“常用语”按钮。",
                    "state": button,
                }
            locator = button.get("locator")
            if locator is None:
                return {
                    "blocked": True,
                    "message": "51job 找到了“常用语”按钮信息，但没有拿到可点击元素。",
                    "state": {k: v for k, v in button.items() if k != "locator"},
                }
            if terminal.humanize:
                terminal.pause_like_person("pre_action")
                highlight_target(locator)
            humanized_locator_click(terminal, locator, force=True)
            if terminal.humanize:
                terminal.pause_like_person("post_action")
            page.wait_for_timeout(random.randint(450, 800))
            if not is_job51_common_word_panel_open(terminal):
                try:
                    humanized_locator_click(terminal, locator, force=True)
                    page.wait_for_timeout(random.randint(500, 900))
                except Exception:
                    pass

        item = self.measure_current_timing_stage(
            "job51_find_common_word_item",
            "51job 查找常用语内容",
            lambda: find_job51_common_word_item(terminal, phrase),
        )
        if not item.get("found"):
            return {
                "blocked": True,
                "message": f"51job 常用语面板里没有找到这句话：{safe_text(phrase, 80)}",
                "state": item,
                "button": {k: v for k, v in button.items() if k != "locator"},
            }

        direct_send = self.measure_current_timing_stage(
            "job51_click_common_word_send",
            "51job 点击常用语发送",
            lambda: click_job51_common_word_send_button(terminal, phrase, item),
        )
        send_result: dict = {"directSend": direct_send}
        if not direct_send.get("clicked"):
            item_locator = item.get("locator")
            if item_locator is None:
                return {
                    "blocked": True,
                    "message": "51job 找到了常用语文本，但没有拿到可点击元素，也没有找到右侧发送按钮。",
                    "state": {k: v for k, v in item.items() if k != "locator"},
                    "directSend": direct_send,
                }
            try:
                if terminal.humanize:
                    terminal.pause_like_person("pre_action")
                    highlight_target(item_locator)
                humanized_locator_click(terminal, item_locator, force=True)
                if terminal.humanize:
                    terminal.pause_like_person("post_action")
                page.wait_for_timeout(random.randint(350, 650))
            except Exception as error:
                return {
                    "blocked": True,
                    "message": f"51job 点击常用语条目失败：{safe_text(str(error), 160)}",
                    "state": {k: v for k, v in item.items() if k != "locator"},
                    "directSend": direct_send,
                }
            editor_text = safe_text(str(safe_eval(
                page,
                "() => String((document.querySelector('#drop-area') || {}).innerText || '')",
            ) or ""), 500)
            if normalize_reply_fingerprint(phrase) not in normalize_reply_fingerprint(editor_text):
                return {
                    "blocked": True,
                    "message": f"51job 已点击常用语，但输入框没有出现目标内容：{safe_text(editor_text, 120)}",
                    "state": {k: v for k, v in item.items() if k != "locator"},
                    "directSend": direct_send,
                }
            send_button = page.locator("button.el-button.new-send-button.el-button--primary, button.new-send-button").first
            if not send_button.count():
                return {
                    "blocked": True,
                    "message": "51job 常用语已填入输入框，但没有找到发送按钮。",
                    "state": {k: v for k, v in item.items() if k != "locator"},
                    "directSend": direct_send,
                }
            if terminal.humanize:
                terminal.pause_like_person("pre_action")
                highlight_target(send_button)
            send_button.click(timeout=8000, force=True)
            if terminal.humanize:
                terminal.pause_like_person("post_action")
            page.wait_for_timeout(random.randint(800, 1300))
            send_result = {
                "message": "51job 已点击常用语条目并点击发送按钮",
                "directSend": direct_send,
                "filledThenSent": True,
            }
        else:
            page.wait_for_timeout(random.randint(800, 1300))
            send_result = {"message": "51job 已点击常用语右侧发送按钮", "directSend": direct_send}

        verification = self.job51_verify_reply_sent_in_current_chat(terminal, phrase)
        message = "51job 已通过常用语发送并校验" if verification.get("verified") else "51job 已触发常用语发送，但最近消息中未校验到文本"
        return {
            "message": message,
            "phrase": phrase,
            "send": send_result,
            "verification": verification,
            "state": {
                "button": {k: v for k, v in button.items() if k != "locator"},
                "item": {k: v for k, v in item.items() if k != "locator"},
            },
            "blocked": not bool(verification.get("verified")),
        }

    def job51_request_resume_from_current_conversation(self, terminal: BrowserTerminal) -> dict:
        page = terminal.current_page()
        candidate = self.job51_read_chat_context(terminal).get("applicant", {})
        candidate_label = str(candidate.get("label") or candidate.get("name") or "")
        state = safe_eval(page, """() => {
          const normalize = value => String(value || '').replace(/\\s+/g, ' ').trim();
          const text = normalize(document.body ? document.body.innerText : '');
          const visible = el => {
            const box = el.getBoundingClientRect();
            const style = window.getComputedStyle(el);
            return box.width > 8 && box.height > 8 && style.display !== 'none' && style.visibility !== 'hidden' && style.opacity !== '0';
          };
          const buttons = Array.from(document.querySelectorAll('div.operate-item, button, [role="button"]'))
            .filter(visible)
            .map((el, index) => ({ index, text: normalize(el.innerText || el.textContent || ''), disabled: !!el.disabled || el.classList.contains('is-disabled') }))
            .filter(item => item.text);
          return { text, buttons };
        }""") or {}
        body_text = str(state.get("text") or "") if isinstance(state, dict) else ""
        if re.search(r"(已.{0,6}求.{0,4}简历|已.{0,6}索.{0,4}简历|简历.{0,6}已发送|已收到.{0,4}简历)", body_text):
            return {
                "message": f"51job 检测到已求过或已收到简历，跳过重复点击：{safe_text(candidate_label, 80)}",
                "skipped": True,
                "skipReason": "already_requested",
                "candidate": candidate,
            }
        buttons = state.get("buttons") if isinstance(state, dict) and isinstance(state.get("buttons"), list) else []
        target_index = None
        target_text = ""
        for item in buttons:
            label = str(item.get("text") or "")
            if item.get("disabled"):
                continue
            if "简历" in label and re.search(r"(求|要|索|获取|交换|申请|请求)", label):
                target_index = int(item.get("index") or 0)
                target_text = label
                break
        if target_index is None:
            return {
                "blocked": True,
                "message": f"51job 当前会话未找到可用的求简历按钮：{safe_text(candidate_label, 80)}",
                "candidate": candidate,
                "buttons": buttons[:12],
            }
        locator = page.locator('div.operate-item, button, [role="button"]').nth(target_index)
        if terminal.humanize:
            terminal.pause_like_person("pre_action")
            highlight_target(locator)
        humanized_locator_click(terminal, locator, force=True)
        if terminal.humanize:
            terminal.pause_like_person("post_action")
        page.wait_for_timeout(random.randint(900, 1400))
        confirm = page.locator("button").filter(has_text=re.compile("确定|确认|发送|索要|求简历")).first
        confirmed = False
        try:
            if confirm.count():
                if terminal.humanize:
                    terminal.pause_like_person("pre_action")
                    highlight_target(confirm)
                humanized_locator_click(terminal, confirm, force=True)
                if terminal.humanize:
                    terminal.pause_like_person("post_action")
                page.wait_for_timeout(random.randint(900, 1400))
                confirmed = True
        except Exception:
            confirmed = False
        message = f"51job 已点击求简历：{safe_text(candidate_label, 80)}"
        if confirmed:
            message += "，并处理了确认按钮"
        return {
            "message": message,
            "candidate": candidate,
            "clickedText": safe_text(target_text, 80),
            "confirmed": confirmed,
        }

    def job51_find_resume_attachment(self, terminal: BrowserTerminal) -> dict:
        page = terminal.current_page()
        token = f"codex_job51_resume_attachment_{int(time.time() * 1000)}_{random.randint(1000, 9999)}"
        info = safe_eval(page, """(args) => {
          const token = args.token;
          const normalize = value => String(value || '').replace(/\\s+/g, ' ').trim();
          const visible = el => {
            if (!el || !el.isConnected) return false;
            const box = el.getBoundingClientRect();
            const style = window.getComputedStyle(el);
            return box.width > 8 && box.height > 8
              && style.display !== 'none'
              && style.visibility !== 'hidden'
              && style.opacity !== '0'
              && box.bottom >= 0
              && box.right >= 0
              && box.top <= window.innerHeight
              && box.left <= window.innerWidth;
          };
          const rect = el => {
            const box = el.getBoundingClientRect();
            return { x: Math.round(box.x), y: Math.round(box.y), w: Math.round(box.width), h: Math.round(box.height) };
          };
          const textOf = el => normalize(el ? (el.innerText || el.textContent || '') : '');
          const attrText = el => normalize([
            el.getAttribute('aria-label'),
            el.getAttribute('title'),
            el.getAttribute('download'),
            el.getAttribute('href'),
            el.getAttribute('data-url'),
            el.getAttribute('data-href'),
            el.className
          ].filter(Boolean).join(' '));
          const candidates = [];
          const seen = new Set();
          const selector = [
            'a',
            'button',
            '[role="button"]',
            '[onclick]',
            '[class*="resume" i]',
            '[class*="jianli" i]',
            '[class*="attach" i]',
            '[class*="file" i]',
            '[class*="download" i]',
            '.item-container-resume',
            '.resume-card'
          ].join(',');
          for (const el of Array.from(document.querySelectorAll(selector))) {
            if (!visible(el)) continue;
            if (el.closest('#conversation-list,.conversation-list,[class*="conversation-list" i],nav,header,.menu,.sidebar')) continue;
            const clickable = el.closest('a,button,[role="button"],[onclick]') || el;
            if (!visible(clickable)) continue;
            const key = clickable.tagName + ':' + rect(clickable).x + ':' + rect(clickable).y + ':' + normalize(clickable.outerHTML || '').slice(0, 80);
            if (seen.has(key)) continue;
            seen.add(key);

            const messageRoot = el.closest('div.message-item,div.im-message-item,.im-message-item,[class*="message-item" i]');
            const rootText = textOf(messageRoot || el);
            const ownText = textOf(el);
            const clickableText = textOf(clickable);
            const href = clickable.href || clickable.getAttribute('href') || el.href || el.getAttribute('href') || '';
            const download = clickable.getAttribute('download') || el.getAttribute('download') || '';
            const className = String(clickable.className || el.className || '');
            const haystack = normalize([ownText, clickableText, rootText, attrText(el), attrText(clickable), href, download].join(' '));
            const hasResumeWord = /(附件简历|简历附件|在线简历|简历|resume|cv|附件|文件)/i.test(haystack);
            const hasFileExt = /\\.(pdf|docx?|PDF|DOCX?)(\\?|#|$|\\s)/.test(haystack);
            const hasDownloadWord = /(下载|download|导出|保存)/i.test(haystack);
            if (!hasResumeWord && !hasFileExt) continue;
            if (/(求简历|索要简历|要简历|请求简历|发送简历|上传简历)/.test(haystack) && !hasFileExt && !/(附件|下载|在线简历)/.test(haystack)) continue;

            let score = 0;
            if (hasFileExt) score += 110;
            if (/附件简历|简历附件/.test(haystack)) score += 100;
            if (hasDownloadWord) score += 80;
            if (/在线简历/.test(haystack)) score += 45;
            if (/附件|文件/.test(haystack)) score += 35;
            if (messageRoot) score += 30;
            if (/others/.test(String(messageRoot?.className || ''))) score += 12;
            if (/download|resume|attach|file/i.test(className)) score += 12;
            if (clickable.matches('a,button,[role="button"]')) score += 10;
            if (/(职位管理|职位发布|批量|全部岗位|未读|主动联系|人才望远镜)/.test(haystack)) score -= 120;
            if (score < 40) continue;

            const box = rect(clickable);
            candidates.push({
              score,
              text: normalize(ownText || clickableText || rootText).slice(0, 240),
              rootText: rootText.slice(0, 360),
              href,
              download,
              tag: clickable.tagName,
              className: className.slice(0, 160),
              rect: box,
              element: clickable
            });
          }
          candidates.sort((a, b) => (b.score - a.score) || ((b.rect?.y || 0) - (a.rect?.y || 0)));
          const best = candidates[0];
          if (!best) return { found: false, reason: 'resume_attachment_not_found', candidates: [] };
          best.element.setAttribute('data-codex-job51-resume-attachment', token);
          return {
            found: true,
            token,
            candidate: {
              score: best.score,
              text: best.text,
              rootText: best.rootText,
              href: best.href,
              download: best.download,
              tag: best.tag,
              className: best.className,
              rect: best.rect
            },
            candidates: candidates.slice(0, 8).map(item => ({
              score: item.score,
              text: item.text,
              rootText: item.rootText,
              href: item.href,
              download: item.download,
              tag: item.tag,
              className: item.className,
              rect: item.rect
            }))
          };
        }""", {"token": token})
        return info if isinstance(info, dict) else {"found": False, "reason": "resume_attachment_scan_failed"}

    def job51_find_preview_download_button(self, page) -> dict:
        token = f"codex_job51_preview_download_{int(time.time() * 1000)}_{random.randint(1000, 9999)}"
        info = safe_eval(page, """(args) => {
          const token = args.token;
          const normalize = value => String(value || '').replace(/\\s+/g, ' ').trim();
          const visible = el => {
            if (!el || !el.isConnected) return false;
            const box = el.getBoundingClientRect();
            const style = window.getComputedStyle(el);
            return box.width > 8 && box.height > 8
              && style.display !== 'none'
              && style.visibility !== 'hidden'
              && style.opacity !== '0'
              && box.bottom >= 0
              && box.right >= 0
              && box.top <= window.innerHeight
              && box.left <= window.innerWidth;
          };
          const rect = el => {
            const box = el.getBoundingClientRect();
            return { x: Math.round(box.x), y: Math.round(box.y), w: Math.round(box.width), h: Math.round(box.height) };
          };
          const candidates = [];
          for (const el of Array.from(document.querySelectorAll('a,button,[role="button"],[onclick],[class*="download" i]'))) {
            if (!visible(el)) continue;
            const text = normalize([
              el.innerText,
              el.textContent,
              el.getAttribute('aria-label'),
              el.getAttribute('title'),
              el.getAttribute('download'),
              el.getAttribute('href'),
              el.className
            ].filter(Boolean).join(' '));
            let score = 0;
            if (/(下载|download|保存|导出)/i.test(text)) score += 90;
            if (/\\.(pdf|docx?|PDF|DOCX?)(\\?|#|$|\\s)/.test(text)) score += 70;
            if (/(简历|resume|cv)/i.test(text)) score += 20;
            if (/(取消|关闭|发送|求简历|职位|筛选|刷新)/.test(text)) score -= 80;
            if (score < 50) continue;
            candidates.push({
              score,
              text: text.slice(0, 160),
              href: el.href || el.getAttribute('href') || '',
              download: el.getAttribute('download') || '',
              tag: el.tagName,
              className: String(el.className || '').slice(0, 140),
              rect: rect(el),
              element: el
            });
          }
          candidates.sort((a, b) => b.score - a.score);
          const best = candidates[0];
          if (!best) return { found: false, reason: 'preview_download_button_not_found', candidates: [] };
          best.element.setAttribute('data-codex-job51-preview-download', token);
          return {
            found: true,
            token,
            candidate: {
              score: best.score,
              text: best.text,
              href: best.href,
              download: best.download,
              tag: best.tag,
              className: best.className,
              rect: best.rect
            },
            candidates: candidates.slice(0, 5).map(item => ({
              score: item.score,
              text: item.text,
              href: item.href,
              download: item.download,
              tag: item.tag,
              className: item.className,
              rect: item.rect
            }))
          };
        }""", {"token": token})
        return info if isinstance(info, dict) else {"found": False, "reason": "preview_download_scan_failed"}

    def job51_fetch_attachment_href(self, page, href: str, original_name: str = "") -> dict:
        href = str(href or "").strip()
        if not href or href.startswith(("blob:", "javascript:", "#")):
            return {"ok": False, "reason": "unsupported_href"}
        absolute_url = urljoin(str(getattr(page, "url", "") or JOB51_CHAT_URL), href)
        suffix = resume_attachment_suffix(original_name, absolute_url)
        if suffix not in LOCAL_FILE_EXTENSIONS:
            return {"ok": False, "reason": "href_not_resume_file", "url": safe_text(absolute_url, 240)}
        response = page.context.request.get(absolute_url, timeout=15000)
        if not response.ok:
            return {"ok": False, "reason": f"http_{response.status}", "url": safe_text(absolute_url, 240)}
        body = response.body()
        if not body:
            return {"ok": False, "reason": "empty_response", "url": safe_text(absolute_url, 240)}
        headers = response.headers or {}
        filename = response_attachment_filename(headers, original_name or absolute_url)
        return {
            "ok": True,
            "bytes": body,
            "filename": filename,
            "url": safe_text(absolute_url, 240),
            "contentType": safe_text(headers.get("content-type", ""), 120),
        }

    def job51_fetch_visible_resume_blob_pdf(self, page, filename_hint: str = "") -> dict:
        payload = safe_eval(page, """async (args) => {
          const normalize = value => String(value || '').replace(/\\s+/g, ' ').trim();
          const visible = el => {
            if (!el || !el.isConnected) return false;
            const box = el.getBoundingClientRect();
            const style = window.getComputedStyle(el);
            return box.width > 80 && box.height > 80
              && style.display !== 'none'
              && style.visibility !== 'hidden'
              && style.opacity !== '0'
              && box.bottom >= 0
              && box.right >= 0
              && box.top <= window.innerHeight
              && box.left <= window.innerWidth;
          };
          const frames = Array.from(document.querySelectorAll('iframe,embed,object'))
            .map(el => ({
              el,
              src: el.src || el.data || el.getAttribute('src') || el.getAttribute('data') || '',
              title: normalize(el.title || el.getAttribute('aria-label') || ''),
              className: String(el.className || '')
            }))
            .filter(item => item.src && String(item.src).startsWith('blob:') && visible(item.el));
          const target = frames[0];
          if (!target) return { ok: false, reason: 'visible_resume_blob_not_found' };
          try {
            const response = await fetch(target.src);
            const buffer = await response.arrayBuffer();
            const bytes = new Uint8Array(buffer);
            const isPdf = bytes.length >= 5
              && bytes[0] === 37 && bytes[1] === 80 && bytes[2] === 68 && bytes[3] === 70 && bytes[4] === 45;
            if (!isPdf) {
              return {
                ok: false,
                reason: 'blob_is_not_pdf',
                src: target.src,
                contentType: response.headers.get('content-type') || '',
                size: bytes.length
              };
            }
            let binary = '';
            const chunkSize = 0x8000;
            for (let index = 0; index < bytes.length; index += chunkSize) {
              binary += String.fromCharCode(...bytes.subarray(index, index + chunkSize));
            }
            return {
              ok: true,
              src: target.src,
              contentType: response.headers.get('content-type') || 'application/pdf',
              size: bytes.length,
              filename: args.filenameHint || '51job_resume.pdf',
              base64: btoa(binary)
            };
          } catch (error) {
            return { ok: false, reason: 'blob_fetch_failed', src: target.src, error: String(error && error.message || error) };
          }
        }""", {"filenameHint": filename_hint or "51job_resume.pdf"})
        if not isinstance(payload, dict) or not payload.get("ok"):
            return payload if isinstance(payload, dict) else {"ok": False, "reason": "visible_resume_blob_scan_failed"}
        try:
            content = base64.b64decode(str(payload.get("base64") or ""), validate=True)
        except Exception as error:
            return {"ok": False, "reason": "blob_base64_decode_failed", "error": safe_text(str(error), 160)}
        if not content.startswith(b"%PDF-"):
            return {"ok": False, "reason": "blob_decoded_not_pdf", "size": len(content)}
        return {
            "ok": True,
            "bytes": content,
            "filename": sanitize_filename(str(payload.get("filename") or filename_hint or "51job_resume.pdf")),
            "url": safe_text(str(payload.get("src") or ""), 240),
            "contentType": safe_text(str(payload.get("contentType") or "application/pdf"), 120),
            "size": len(content),
        }

    def job51_resume_download_memory_keys(
        self,
        context: dict | None,
        candidate_name: str = "",
        applied_position: str = "",
    ) -> list[str]:
        context = context if isinstance(context, dict) else {}
        applicant = context.get("applicant") if isinstance(context.get("applicant"), dict) else {}
        label = safe_text(str(applicant.get("label") or ""), 180)
        conversation_key = safe_text(str(context.get("conversationKey") or ""), 160)
        candidate_name = safe_text(str(candidate_name or applicant.get("name") or recruiter_candidate_name_from_label(label)), 60)
        applied_position = safe_text(str(applied_position or applicant.get("appliedPosition") or context.get("appliedPosition") or ""), 100)
        identity = build_recruiter_candidate_identity(context, label, conversation_key)
        raw_keys = [
            str(identity.get("identityKey") or ""),
            conversation_key,
            compact_conversation_label(label),
            compact_conversation_label(f"{candidate_name}|{applied_position}"),
        ]
        keys: list[str] = []
        for raw in raw_keys:
            raw = str(raw or "").strip()
            if not raw:
                continue
            key = "job51_resume_download|" + stable_digest(raw, 24)
            if key not in keys:
                keys.append(key)
        return keys

    def job51_find_downloaded_resume_memory(
        self,
        context: dict | None,
        candidate_name: str = "",
        applied_position: str = "",
    ) -> dict:
        context = context if isinstance(context, dict) else {}
        candidate_name = safe_text(str(candidate_name or ""), 60)
        applied_position = clean_applied_position(str(applied_position or ""))
        index: dict = {}
        for memory_file in scoped_json_siblings(JOB51_RESUME_DOWNLOADS_FILE):
            data = load_json(memory_file, {})
            if isinstance(data, dict):
                index.update(data)
        for key in self.job51_resume_download_memory_keys(context, candidate_name, applied_position):
            item = index.get(key)
            if not isinstance(item, dict):
                continue
            file_path = Path(str(item.get("filePath") or ""))
            if file_path.exists() and file_path.is_file():
                item_name = safe_text(str(item.get("candidateName") or ""), 60)
                item_position = clean_applied_position(str(item.get("appliedPosition") or ""))
                if item_name and candidate_name and not recruiter_candidate_names_match(item_name, candidate_name):
                    continue
                if item_position and applied_position and item_position != clean_applied_position(applied_position):
                    continue
                if not job51_resume_path_matches_candidate(file_path, candidate_name, applied_position):
                    continue
                return {
                    **item,
                    "memoryKey": key,
                    "fileHash": str(item.get("fileHash") or job51_resume_file_hash(file_path)),
                    "fileSize": int(item.get("fileSize") or file_path.stat().st_size or 0),
                    "source": "job51_resume_download_index",
                }
        if candidate_name and candidate_name != "未知候选人" and applied_position and applied_position != "未知岗位":
            account_part = safe_resume_file_part(f"{AGENT_ACCOUNT_ID}_{AGENT_ACCOUNT_NAME}", AGENT_ACCOUNT_ID)
            folders = [JOB51_RESUME_DIR / account_part]
            try:
                folders.extend(path for path in JOB51_RESUME_DIR.iterdir() if path.is_dir() and path not in folders)
            except Exception:
                pass
            name_part = safe_resume_file_part(candidate_name, "未知候选人")
            position_part = safe_resume_file_part(applied_position, "未知岗位")
            matches: list[Path] = []
            try:
                for folder in folders:
                    if not folder.exists():
                        continue
                    matches.extend(
                        path
                        for path in folder.glob(f"{name_part}_{position_part}_51job_*")
                        if path.is_file() and path.suffix.lower() in LOCAL_FILE_EXTENSIONS
                    )
                matches = sorted(matches, key=lambda path: path.stat().st_mtime, reverse=True)
            except Exception:
                matches = []
            if matches:
                latest = matches[0]
                return {
                    "candidateName": candidate_name,
                    "appliedPosition": applied_position,
                    "filePath": str(latest),
                    "filename": latest.name,
                    "fileHash": job51_resume_file_hash(latest),
                    "fileSize": latest.stat().st_size,
                    "downloadedAt": time.strftime("%Y-%m-%d %H:%M:%S", time.localtime(latest.stat().st_mtime)),
                    "source": "job51_resume_folder_match",
                }
        return {}

    def job51_validate_resume_download_context(
        self,
        context: dict | None,
        candidate_name: str,
        applied_position: str,
    ) -> dict:
        context = context if isinstance(context, dict) else {}
        applicant = context.get("applicant") if isinstance(context.get("applicant"), dict) else {}
        label = safe_text(str(applicant.get("label") or ""), 180)
        warnings = applicant.get("identityWarnings") if isinstance(applicant.get("identityWarnings"), list) else []
        candidate_name = safe_text(str(candidate_name or ""), 60)
        applied_position = clean_applied_position(str(applied_position or ""))
        if not candidate_name or candidate_name == "未知候选人":
            return {
                "ok": False,
                "blocked": True,
                "reason": "job51_candidate_name_unknown",
                "message": "51job 当前候选人姓名未识别，已停止下载，避免把附件记到错误候选人名下。",
            }
        if not applied_position or applied_position == "未知岗位":
            return {
                "ok": False,
                "blocked": True,
                "reason": "job51_position_unknown",
                "message": "51job 当前沟通岗位未识别，已停止下载，避免把附件记到错误岗位名下。",
            }
        if warnings:
            return {
                "ok": False,
                "blocked": True,
                "reason": "job51_candidate_identity_mismatch",
                "message": "51job 当前聊天头部与刚打开的联系人不一致，已停止下载，等待页面同步后再处理。",
                "warnings": warnings,
            }
        if label and not candidate_label_matches(label, candidate_name):
            return {
                "ok": False,
                "blocked": True,
                "reason": "job51_candidate_label_mismatch",
                "message": "51job 当前候选人姓名与会话列表标签不一致，已停止下载，避免串人保存。",
                "label": label,
                "candidateName": candidate_name,
            }
        return {
            "ok": True,
            "candidateName": candidate_name,
            "appliedPosition": applied_position,
            "label": label,
        }

    def job51_mark_resume_downloaded(self, context: dict | None, result: dict) -> dict:
        context = context if isinstance(context, dict) else {}
        result = result if isinstance(result, dict) else {}
        applicant = context.get("applicant") if isinstance(context.get("applicant"), dict) else {}
        candidate_label = safe_text(str(applicant.get("label") or result.get("candidateLabel") or ""), 180)
        candidate_name = safe_text(str(result.get("candidateName") or applicant.get("name") or recruiter_candidate_name_from_label(candidate_label)), 60)
        applied_position = clean_applied_position(str(result.get("appliedPosition") or applicant.get("appliedPosition") or context.get("appliedPosition") or ""))
        conversation_key = safe_text(str(context.get("conversationKey") or ""), 160)
        file_path = Path(str(result.get("filePath") or ""))
        file_hash = str(result.get("fileHash") or "")
        file_size = int(result.get("fileSize") or 0)
        if file_path.exists() and file_path.is_file():
            file_hash = file_hash or job51_resume_file_hash(file_path)
            try:
                file_size = file_size or file_path.stat().st_size
            except Exception:
                file_size = file_size or 0
        item = {
            "platform": "51job",
            "accountId": AGENT_ACCOUNT_ID,
            "accountName": AGENT_ACCOUNT_NAME,
            "candidateName": candidate_name,
            "candidateLabel": candidate_label,
            "appliedPosition": applied_position,
            "conversationKey": conversation_key,
            "filePath": str(result.get("filePath") or ""),
            "filename": str(result.get("filename") or ""),
            "fileHash": file_hash,
            "fileSize": file_size,
            "downloadMethod": str(result.get("downloadMethod") or ""),
            "downloadedAt": time.strftime("%Y-%m-%d %H:%M:%S"),
        }
        index = load_json(JOB51_RESUME_DOWNLOADS_FILE, {})
        if not isinstance(index, dict):
            index = {}
        keys = self.job51_resume_download_memory_keys(context, candidate_name, applied_position)
        for key in keys:
            index[key] = item
        save_json(JOB51_RESUME_DOWNLOADS_FILE, index)
        self.set_recruiter_basic_state(
            conversation_key,
            candidate_label or candidate_name,
            "job51_resume_downloaded",
            context=context,
            platform="51job",
            resumeDownloaded=True,
            resumeFilePath=item["filePath"],
            resumeFilename=item["filename"],
            resumeDownloadMethod=item["downloadMethod"],
        )
        return {"keys": keys, "item": item}

    def job51_close_resume_download_surfaces(self, terminal: BrowserTerminal, origin_page=None) -> dict:
        origin_page = origin_page or terminal.current_page()
        context = origin_page.context
        closed_pages: list[dict] = []
        for page in list(context.pages):
            if page == origin_page:
                continue
            try:
                url = str(getattr(page, "url", "") or "")
                title = page.title()
            except Exception:
                url = ""
                title = ""
            haystack = f"{url} {title}"
            should_close = (
                "ehire.51job.com" in url
                and "/Revision/chat" not in url
                and re.search(r"(resume|jianli|preview|download|pdf|doc|简历|预览)", haystack, flags=re.I)
            )
            if not should_close:
                continue
            try:
                page.close()
                closed_pages.append({"url": safe_text(url, 180), "title": safe_text(title, 80)})
            except Exception:
                pass
        try:
            origin_page.bring_to_front()
        except Exception:
            pass
        clicked = safe_eval(origin_page, """() => {
          const normalize = value => String(value || '').replace(/\\s+/g, ' ').trim();
          const visible = el => {
            if (!el || !el.isConnected) return false;
            const box = el.getBoundingClientRect();
            const style = getComputedStyle(el);
            return box.width > 8 && box.height > 8 && style.display !== 'none' && style.visibility !== 'hidden' && style.opacity !== '0';
          };
          const roots = Array.from(document.querySelectorAll([
            '.con.con-ehire',
            '.con-close',
            '.el-dialog__wrapper',
            '.el-dialog',
            '.resume-common-dialog',
            '.IM-resume-operation',
            '.con-container',
            '.new-resume-online-main-ui',
            '.resume-detail-wrap',
            '[class*="resume-detail" i]',
            '[class*="resume-online" i]',
            '[class*="preview" i]'
          ].join(','))).filter(root => {
            if (!visible(root)) return false;
            const text = normalize(root.innerText || root.textContent || '');
            const className = String(root.className || '');
            return /con-ehire|con-close|IM-resume|resume|cv/i.test(className)
              || /(简历|附件|预览|下载|求职意向|个人优势|工作经历|resume|cv)/i.test(text + ' ' + className);
          });
          let clicked = 0;
          for (const root of roots) {
            const candidates = Array.from(root.querySelectorAll('button,a,[role="button"],i,span,div')).filter(el => {
              if (!visible(el)) return false;
              const text = normalize([el.innerText, el.textContent, el.getAttribute('aria-label'), el.getAttribute('title'), el.className].filter(Boolean).join(' '));
              if (/(关闭|close|el-dialog__headerbtn|icon-close|btn-close|\\bclose\\b|×|x)/i.test(text)) return true;
              return false;
            }).sort((a, b) => {
              const ar = a.getBoundingClientRect();
              const br = b.getBoundingClientRect();
              return (br.y - ar.y) || (br.x - ar.x);
            });
            const target = candidates[0];
            if (!target) continue;
            target.click();
            clicked += 1;
            break;
          }
          return { clicked };
        }""") or {}
        try:
            origin_page.wait_for_timeout(random.randint(300, 650))
        except Exception:
            pass
        return {
            "closedPages": closed_pages,
            "closedInlineSurfaces": int((clicked if isinstance(clicked, dict) else {}).get("clicked") or 0),
        }

    def job51_resume_download_suitability_guard(
        self,
        terminal: BrowserTerminal,
        context: dict | None,
        previous_state: dict | None = None,
        accepted_by_flow: dict | None = None,
    ) -> dict:
        context = context if isinstance(context, dict) else {}
        if isinstance(accepted_by_flow, dict) and accepted_by_flow.get("accepted"):
            return {
                "allowed": True,
                "reason": accepted_by_flow.get("reason") or "accepted_by_current_screening_flow",
                "source": accepted_by_flow.get("source") or "current_flow",
                "screening": accepted_by_flow.get("screening") if isinstance(accepted_by_flow.get("screening"), dict) else {},
            }

        candidate = context.get("applicant") if isinstance(context.get("applicant"), dict) else {}
        candidate_label = str(candidate.get("label") or candidate.get("name") or "")
        conversation_key = str(context.get("conversationKey") or "")
        candidate_state_key = recruiter_basic_candidate_state_key(candidate_label)
        previous_state = previous_state if isinstance(previous_state, dict) else (
            self.get_chat_state(conversation_key) or self.get_chat_state(candidate_state_key)
        )
        status = str((previous_state or {}).get("status") or "")
        if status.startswith(("position_screening_accepted", "basic_conditions_accepted")) or status == "job51_resume_downloaded":
            return {
                "allowed": True,
                "reason": "previous_state_accepted",
                "source": "chat_state",
                "stateStatus": status,
            }

        position_reply = context.get("positionReply") if isinstance(context.get("positionReply"), dict) else {}
        knowledge_base = context.get("companyKnowledgeBase") if isinstance(context.get("companyKnowledgeBase"), dict) else {}
        screening_rules = knowledge_base.get("screening") if isinstance(knowledge_base.get("screening"), dict) else {}
        messages = context.get("messages", []) if isinstance(context.get("messages"), list) else []

        if should_use_position_screening_flow(context, position_reply):
            analysis = analyze_position_screening(messages, screening_rules)
            if analysis.get("status") != "not_asked" and context.get("lastSender") == "other":
                try:
                    analysis = enhance_position_screening_with_model(context, screening_rules, analysis, previous_state)
                except Exception as error:
                    analysis = {
                        **analysis,
                        "modelEnhanceError": safe_text(str(error), 160),
                    }
            return {
                "allowed": analysis.get("status") == "accept",
                "reason": analysis.get("reason") or analysis.get("status") or "position_screening_unknown",
                "source": "position_screening",
                "screening": analysis,
                "message": "51job 当前候选人尚未通过岗位筛选，不能下载简历。" if analysis.get("status") != "accept" else "",
            }

        if is_explicit_ai_app_basic_conditions_position(context):
            phrase = str(position_reply.get("initialCommonPhrase") or BASIC_CONDITIONS_PHRASE).strip()
            screening = analyze_basic_condition_screening(messages, phrase)
        screening = apply_basic_waiting_state_to_screening(screening, previous_state, context)
        if screening.get("status") != "not_asked" and context.get("lastSender") == "other":
            rule_screening = screening
            try:
                screening = enhance_basic_condition_screening_with_model(context, phrase, screening, previous_state)
                screening = preserve_zhilian_basic_acceptance_after_model(screening, rule_screening, platform="job51")
            except Exception as error:
                screening = {
                    **screening,
                        "modelEnhanceError": safe_text(str(error), 160),
                    }
            return {
                "allowed": screening.get("status") == "accept",
                "reason": screening.get("reason") or screening.get("status") or "basic_conditions_unknown",
                "source": "basic_conditions",
                "screening": screening,
                "message": "51job 当前候选人尚未明确接受 AI 岗位基础条件，不能下载简历。" if screening.get("status") != "accept" else "",
            }

        return {
            "allowed": False,
            "reason": "suitability_not_confirmed",
            "source": "unknown",
            "message": "51job 当前候选人没有明确的合适判断，不能下载简历。",
        }

    def job51_is_online_resume_detail_page(self, page) -> bool:
        try:
            url = str(getattr(page, "url", "") or "")
        except Exception:
            url = ""
        if "/Revision/talent/resume/detail" in url:
            return True
        state = safe_eval(page, """() => {
          const normalize = value => String(value || '').replace(/\\s+/g, ' ').trim();
          const text = normalize(document.body ? document.body.innerText : '');
          const hasImResumeSurface = !!document.querySelector([
            '#sensor_imresume_download',
            '#sensor_imresume_print',
            '.IM-resume-operation',
            '.con-container .resume',
            '.baseinfo-container.IM-resume-item',
            '.IM-base-module.IM-resume-item'
          ].join(','));
          if (hasImResumeSurface && /求职意向/.test(text) && /(个人优势|工作经历|教育经历)/.test(text)) return true;
          return /(人才状态|投递日期|求职意向)/.test(text) && /(保存|打印|转发|更多操作)/.test(text) && /(简历|工作经历|教育经历|个人优势)/.test(text);
        }""")
        return bool(state)

    def job51_find_online_resume_entry(self, terminal: BrowserTerminal) -> dict:
        page = terminal.current_page()
        token = f"codex_job51_online_resume_{int(time.time() * 1000)}_{random.randint(1000, 9999)}"
        info = safe_eval(page, """(args) => {
          const token = args.token;
          const normalize = value => String(value || '').replace(/\\s+/g, ' ').trim();
          const visible = el => {
            if (!el || !el.isConnected) return false;
            const box = el.getBoundingClientRect();
            const style = window.getComputedStyle(el);
            return box.width > 8 && box.height > 8
              && style.display !== 'none'
              && style.visibility !== 'hidden'
              && style.opacity !== '0'
              && box.bottom >= 0
              && box.right >= 0
              && box.top <= window.innerHeight
              && box.left <= window.innerWidth;
          };
          const rect = el => {
            const box = el.getBoundingClientRect();
            return { x: Math.round(box.x), y: Math.round(box.y), w: Math.round(box.width), h: Math.round(box.height) };
          };
          const textOf = el => normalize(el ? (el.innerText || el.textContent || '') : '');
          const candidates = [];
          const seen = new Set();
          const selector = [
            '#sensor_Bchat_newzxjl',
            '.chat-user-operate .file-style.online',
            '.chat-user-operate .file-style',
            '.chat-user-operate [tabindex]',
            '.resume-element',
            '.item-container-resume',
            '.resume-card',
            '[class*="resume" i]',
            '[class*="file-style" i]',
            'a',
            'button',
            '[role="button"]',
            '[onclick]'
          ].join(',');
          for (const el of Array.from(document.querySelectorAll(selector))) {
            if (!visible(el)) continue;
            if (el.closest('#conversation-list,.conversation-list,[class*="conversation-list" i],nav,header,.menu,.sidebar')) continue;
            const clickable = el.closest('a,button,[role="button"],[onclick],#sensor_Bchat_newzxjl,.chat-user-operate .file-style,.chat-user-operate [tabindex],.resume-element,.item-container-resume,[class*="resume" i],[class*="file-style" i]') || el;
            if (!visible(clickable)) continue;
            const root = el.closest('div.message-item,div.im-message-item,.im-message-item,[class*="message-item" i]') || clickable;
            const haystack = normalize([
              textOf(el),
              textOf(clickable),
              textOf(root),
              el.getAttribute('aria-label'),
              el.getAttribute('title'),
              clickable.getAttribute('aria-label'),
              clickable.getAttribute('title'),
              clickable.getAttribute('href'),
              el.className,
              clickable.className
            ].filter(Boolean).join(' '));
            if (!/在线简历/.test(haystack)) continue;
            if (/(求简历|索要简历|要简历|请求简历|上传简历)/.test(haystack) && !/在线简历/.test(haystack)) continue;
            const box = rect(clickable);
            const key = `${clickable.tagName}:${box.x}:${box.y}:${haystack.slice(0, 80)}`;
            if (seen.has(key)) continue;
            seen.add(key);
            let score = 100;
            if (/sensor_Bchat_newzxjl|file-style online|chat-user-operate/i.test(haystack)) score += 80;
            if (/resume-element|item-container-resume|resume-card/i.test(String(clickable.className || '') + ' ' + String(root.className || ''))) score += 140;
            if (/在线简历/.test(textOf(clickable))) score += 60;
            if (/在线简历/.test(textOf(root))) score += 35;
            if (/others|left|message/i.test(String(root.className || ''))) score += 15;
            if (box.x > 260) score += 10;
            if (/(批量|职位管理|全部岗位|未读|人才望远镜|主动联系)/.test(haystack)) score -= 120;
            candidates.push({
              score,
              text: haystack.slice(0, 260),
              tag: clickable.tagName,
              className: String(clickable.className || '').slice(0, 160),
              rect: box,
              element: clickable
            });
          }
          candidates.sort((a, b) => (b.score - a.score) || ((b.rect?.y || 0) - (a.rect?.y || 0)));
          const best = candidates[0];
          if (!best || best.score < 80) return { found: false, reason: 'online_resume_entry_not_found', candidates: candidates.slice(0, 8) };
          best.element.setAttribute('data-codex-job51-online-resume', token);
          return {
            found: true,
            token,
            candidate: {
              score: best.score,
              text: best.text,
              tag: best.tag,
              className: best.className,
              rect: best.rect
            },
            candidates: candidates.slice(0, 8).map(item => ({
              score: item.score,
              text: item.text,
              tag: item.tag,
              className: item.className,
              rect: item.rect
            }))
          };
        }""", {"token": token})
        return info if isinstance(info, dict) else {"found": False, "reason": "online_resume_scan_failed"}

    def job51_open_online_resume_detail(self, terminal: BrowserTerminal, entry: dict) -> dict:
        origin_page = terminal.current_page()
        locator = origin_page.locator(f"[data-codex-job51-online-resume='{entry.get('token')}']").first
        if not locator.count():
            return {"ok": False, "reason": "online_resume_entry_element_missing", "entry": {k: v for k, v in entry.items() if k != "token"}}

        before_pages = list(getattr(origin_page.context, "pages", []) or [])
        detail_page = None
        opened_by = "current_page"
        clicked_entry = False
        try:
            with origin_page.context.expect_page(timeout=8000) as page_info:
                if terminal.humanize:
                    terminal.pause_like_person("pre_action")
                    highlight_target(locator)
                humanized_locator_click(terminal, locator, force=True)
                clicked_entry = True
                if terminal.humanize:
                    terminal.pause_like_person("post_action")
            detail_page = page_info.value
            opened_by = "new_page"
        except Exception:
            if not clicked_entry:
                try:
                    if terminal.humanize:
                        terminal.pause_like_person("pre_action")
                        highlight_target(locator)
                    humanized_locator_click(terminal, locator, force=True)
                    clicked_entry = True
                    if terminal.humanize:
                        terminal.pause_like_person("post_action")
                except Exception as error:
                    return {"ok": False, "reason": "online_resume_click_failed", "error": safe_text(str(error), 160)}

        origin_page.wait_for_timeout(random.randint(900, 1400))
        pages = list(getattr(origin_page.context, "pages", []) or [])
        if detail_page is None:
            new_pages = [page for page in pages if page not in before_pages]
            for page in reversed(new_pages + pages):
                try:
                    if self.job51_is_online_resume_detail_page(page):
                        detail_page = page
                        opened_by = "detected_page"
                        break
                except Exception:
                    continue
        if detail_page is None and self.job51_is_online_resume_detail_page(origin_page):
            detail_page = origin_page
            opened_by = "same_page"
        if detail_page is None:
            return {
                "ok": False,
                "reason": "online_resume_detail_not_opened",
                "entry": {k: v for k, v in entry.items() if k != "token"},
                "pages": [
                    {"url": safe_text(str(getattr(page, "url", "") or ""), 180), "title": safe_text(page.title(), 80)}
                    for page in pages[-6:]
                ],
            }

        try:
            detail_page.bring_to_front()
            detail_page.wait_for_load_state("domcontentloaded", timeout=8000)
        except Exception:
            pass
        try:
            detail_page.wait_for_selector("body", timeout=5000)
        except Exception:
            pass
        terminal.page = detail_page
        return {
            "ok": True,
            "page": detail_page,
            "originPage": origin_page,
            "openedBy": opened_by,
            "url": safe_text(str(getattr(detail_page, "url", "") or ""), 240),
            "title": safe_text(detail_page.title(), 100),
            "entry": {k: v for k, v in entry.items() if k != "token"},
        }

