def should_use_position_screening_flow(context: dict, position_reply: dict | None = None) -> bool:
    if not isinstance(context, dict):
        return False
    position_reply = position_reply if isinstance(position_reply, dict) else {}
    # AI 应用开发相关岗位已有“公司基本情况常用语”专用流程，先保持稳定路径。
    if (
        str(position_reply.get("initialCommonPhrase") or "").strip()
        and is_ai_app_basic_conditions_position(context, position_reply)
    ):
        return False
    knowledge_base = context.get("companyKnowledgeBase") if isinstance(context.get("companyKnowledgeBase"), dict) else {}
    screening = knowledge_base.get("screening") if isinstance(knowledge_base.get("screening"), dict) else {}
    return bool(normalize_position_screening_questions(screening))


def is_unconfigured_recruiter_position(
    context: dict,
    position_reply: dict | None = None,
    position_screening: dict | None = None,
) -> bool:
    if not isinstance(context, dict):
        return False
    position_reply = position_reply if isinstance(position_reply, dict) else {}
    knowledge_base = context.get("companyKnowledgeBase") if isinstance(context.get("companyKnowledgeBase"), dict) else {}
    if position_screening is None:
        position_screening = knowledge_base.get("screening") if isinstance(knowledge_base.get("screening"), dict) else {}
    position_screening = position_screening if isinstance(position_screening, dict) else {}
    has_initial_phrase = (
        bool(str(position_reply.get("initialCommonPhrase") or "").strip())
        and is_ai_app_basic_conditions_position(context, position_reply)
    )
    has_screening_questions = bool(normalize_position_screening_questions(position_screening))
    has_knowledge_base = bool(knowledge_base.get("enabled"))
    return not has_initial_phrase and not has_screening_questions and not has_knowledge_base


def position_screening_question_matches(message_text: str, question_text: str) -> bool:
    message_compact = compact_position_screening_text(message_text)
    question_compact = compact_position_screening_text(question_text)
    if not message_compact or not question_compact:
        return False
    if question_compact in message_compact:
        return True
    if len(message_compact) >= 8 and message_compact in question_compact:
        return True
    generic_terms = {
        "你好",
        "您好",
        "可以",
        "接受",
        "可以接受",
        "能接受",
        "可以接受吗",
        "能接受吗",
        "你能接受吗",
        "这个岗位",
        "我们这边",
        "这边",
        "岗位",
        "需要",
    }
    terms = []
    for item in re.split(r"[，,。？?、\s]+", str(question_text or "")):
        compact_item = compact_position_screening_text(item)
        if len(compact_item) < 2 or compact_item in generic_terms:
            continue
        if any(compact_item.endswith(suffix) and compact_item[:-len(suffix)] in generic_terms for suffix in ("吗", "么")):
            continue
        terms.append(compact_item)
    if not terms:
        return False
    matched = sum(1 for term in terms if term in message_compact)
    return matched >= max(1, min(2, len(terms)))


def classify_position_screening_answer(question_text: str, answer_text: str) -> dict:
    raw = str(answer_text or "").strip()
    compact = compact_position_screening_text(raw)
    if not compact:
        return {
            "status": "waiting",
            "confidence": 0.0,
            "reason": "empty_answer",
            "sourceText": "",
        }

    if any(term in compact for term in ("没问题", "没有问题", "没啥问题")):
        return {
            "status": "accept",
            "confidence": 0.86,
            "reason": "explicit_accept",
            "sourceText": safe_text(raw, 160),
        }

    question_compact = compact_position_screening_text(question_text)
    if any(term in question_compact for term in ("弱电电工证", "弱电证", "电工证")):
        cert_reject_patterns = (
            r"^(没|没有|无)$",
            r"(没有|没|无)(?:弱电)?(?:电工)?证",
            r"(没有|没|无)(?:考|办|拿|取得|持有)",
            r"(还没|未)(?:考|办|拿|取得|持有)",
            r"(暂时|目前)?(?:没有|没|无)",
        )
        if any(re.search(pattern, compact) for pattern in cert_reject_patterns):
            return {
                "status": "reject",
                "confidence": 0.9,
                "reason": "missing_required_certificate",
                "sourceText": safe_text(raw, 160),
            }
        cert_accept_patterns = (
            r"^(有|有的|有证|有)$",
            r"(有|持有|取得|考了|拿了)(?:弱电)?(?:电工)?证",
            r"(弱电)?(?:电工)?证(?:有|齐全|在手)",
        )
        if any(re.search(pattern, compact) for pattern in cert_accept_patterns):
            return {
                "status": "accept",
                "confidence": 0.88,
                "reason": "has_required_certificate",
                "sourceText": safe_text(raw, 160),
            }

    reject_patterns = (
        r"不太能接受",
        r"不能接受",
        r"不接受",
        r"接受不了",
        r"不可以",
        r"不行",
        r"不考虑",
        r"不会",
        r"不懂",
        r"不熟悉",
        r"不了解",
        r"没(?:有)?(?:相关)?(?:经验|经历|做过|了解|接触|销售)",
        r"没有(?:相关)?(?:经验|经历|做过|了解|接触|销售)",
        r"无(?:相关)?(?:经验|经历)",
        r"不太(?:了解|熟悉|懂|会|接受)",
        r"不是很(?:了解|熟悉|懂|会|接受)",
    )
    if any(re.search(pattern, compact) for pattern in reject_patterns):
        return {
            "status": "reject",
            "confidence": 0.84,
            "reason": "explicit_reject_or_missing_required_experience",
            "sourceText": safe_text(raw, 160),
        }

    hesitation_terms = ("考虑", "想想", "看看", "再说", "了解一下", "稍后", "晚点")
    if any(term in compact for term in hesitation_terms):
        return {
            "status": "unclear",
            "confidence": 0.58,
            "reason": "candidate_is_considering",
            "sourceText": safe_text(raw, 160),
        }

    accept_patterns = (
        r"可以接受",
        r"能接受",
        r"可以",
        r"接受",
        r"有的",
        r"有过",
        r"有(?:相关)?(?:经验|经历)",
        r"做过",
        r"了解过",
        r"了解",
        r"熟悉",
        r"懂",
        r"会",
        r"是的",
        r"对",
        r"行的",
        r"ok",
        r"okay",
    )
    if any(re.search(pattern, compact) for pattern in accept_patterns):
        return {
            "status": "accept",
            "confidence": 0.78,
            "reason": "explicit_accept_or_has_required_experience",
            "sourceText": safe_text(raw, 160),
        }

    return {
        "status": "unclear",
        "confidence": 0.35,
        "reason": "no_clear_position_screening_answer",
        "sourceText": safe_text(raw, 160),
    }


def compact_messages_for_screening_model(messages: list[dict], limit: int = SCREENING_MODEL_MESSAGE_LIMIT) -> list[dict]:
    if not isinstance(messages, list):
        return []
    compacted: list[dict] = []
    start = max(0, len(messages) - max(4, int(limit or SCREENING_MODEL_MESSAGE_LIMIT)))
    for index, item in enumerate(messages[start:], start=start):
        if not isinstance(item, dict):
            continue
        text = safe_text(str(item.get("text") or "").strip(), 220)
        if not text or not is_effective_chat_text(text):
            continue
        sender = str(item.get("sender") or "unknown")
        if sender not in {"me", "other", "unknown"}:
            sender = "unknown"
        compacted.append({
            "index": index,
            "sender": sender,
            "text": text,
            "time": safe_text(str(item.get("time") or ""), 30),
        })
    return compacted


def question_by_id_or_text(questions: list[dict], question_id: str = "", question_text: str = "") -> dict:
    question_id = str(question_id or "").strip()
    question_text = str(question_text or "").strip()
    question_text_compact = compact_position_screening_text(question_text)
    if question_id:
        for question in questions:
            if str(question.get("id") or "").strip() == question_id:
                return question
    if question_text_compact:
        for question in questions:
            if position_screening_question_matches_any(question_text, question):
                return question
            if compact_position_screening_text(str(question.get("text") or "")) == question_text_compact:
                return question
    return {}


def normalize_screening_status(value: str) -> str:
    status = str(value or "").strip().lower()
    aliases = {
        "pass": "accept",
        "passed": "accept",
        "accepted": "accept",
        "yes": "accept",
        "fail": "reject",
        "failed": "reject",
        "rejected": "reject",
        "no": "reject",
        "unknown": "unclear",
        "pending": "waiting",
    }
    status = aliases.get(status, status)
    return status if status in {"not_asked", "waiting", "accept", "reject", "unclear"} else "unclear"


def normalize_model_condition_results(model_result: dict, questions: list[dict], fallback_progress: list[dict] | None = None) -> list[dict]:
    fallback_progress = fallback_progress if isinstance(fallback_progress, list) else []
    fallback_by_id: dict[str, dict] = {}
    for item in fallback_progress:
        if not isinstance(item, dict):
            continue
        question = item.get("question") if isinstance(item.get("question"), dict) else {}
        qid = str(question.get("id") or "").strip()
        if qid:
            fallback_by_id[qid] = item

    raw_results = model_result.get("conditionResults")
    if not isinstance(raw_results, list):
        raw_results = model_result.get("conditions") if isinstance(model_result.get("conditions"), list) else []
    raw_by_id: dict[str, dict] = {}
    for item in raw_results:
        if not isinstance(item, dict):
            continue
        matched = question_by_id_or_text(
            questions,
            str(item.get("id") or item.get("questionId") or ""),
            str(item.get("question") or item.get("text") or ""),
        )
        qid = str(matched.get("id") or item.get("id") or item.get("questionId") or "").strip()
        if qid:
            raw_by_id[qid] = item

    normalized: list[dict] = []
    for question in questions:
        qid = str(question.get("id") or "").strip()
        raw = raw_by_id.get(qid, {})
        fallback = fallback_by_id.get(qid, {})
        fallback_status = str(fallback.get("status") or "")
        status = normalize_screening_status(str(raw.get("status") or raw.get("judgement") or fallback_status or "not_asked"))
        evidence = safe_text(str(raw.get("evidence") or raw.get("sourceText") or raw.get("answer") or fallback.get("answerText") or ""), 180)
        try:
            confidence = float(raw.get("confidence") if raw.get("confidence") is not None else (fallback.get("judgement") or {}).get("confidence", 0.0))
        except Exception:
            confidence = 0.0
        fallback_asked = bool(fallback.get("asked")) if fallback else False
        asked = raw.get("asked")
        if asked is None:
            asked = fallback_asked if fallback else status not in {"not_asked"}
        if not fallback_asked:
            evidence_matches_question = bool(evidence) and position_screening_question_matches_any(evidence, question)
            if not evidence_matches_question:
                asked = False
                status = "not_asked"
        normalized.append({
            "question": question,
            "asked": bool(asked),
            "answerText": evidence,
            "status": status,
            "judgement": {
                "status": status,
                "confidence": confidence,
                "reason": safe_text(str(raw.get("reason") or raw.get("basis") or (fallback.get("judgement") or {}).get("reason") or ""), 120),
                "sourceText": evidence,
            },
            "modelEvidence": evidence,
        })
    return normalized


def enforce_screening_mode_decision(
    model_result: dict,
    questions: list[dict],
    progress: list[dict],
    mode: str,
) -> tuple[str, str, dict]:
    requested_status = normalize_screening_status(str(model_result.get("status") or model_result.get("decision") or "unclear"))
    mode = str(mode or "ask_required_questions").strip() or "ask_required_questions"
    accepted = [item for item in progress if item.get("status") == "accept"]
    rejected = [item for item in progress if item.get("status") == "reject"]
    waiting = [item for item in progress if item.get("status") == "waiting"]
    unclear = [item for item in progress if item.get("status") == "unclear"]
    not_asked = [item for item in progress if item.get("status") == "not_asked"]
    required_questions = [item for item in questions if item.get("required", True)]
    required_ids = {str(item.get("id") or "") for item in required_questions}
    accepted_required = [
        item for item in accepted
        if str((item.get("question") or {}).get("id") or "") in required_ids
    ]
    rejected_required = [
        item for item in rejected
        if str((item.get("question") or {}).get("id") or "") in required_ids
    ]

    if mode == "ask_any_required_question":
        if accepted_required:
            return "accept", "model_any_required_question_accepted", accepted_required[0].get("question") or {}
        if len(rejected_required) >= len(required_questions) and required_questions:
            return "reject", "model_all_any_required_questions_rejected", rejected_required[-1].get("question") or {}
        if waiting:
            return "waiting", "model_waiting_for_any_required_question_answer", waiting[0].get("question") or {}
        if not_asked:
            return "not_asked", "model_need_ask_next_any_required_question", not_asked[0].get("question") or {}
        if unclear:
            return "unclear", "model_any_required_question_unclear", unclear[-1].get("question") or {}
        return requested_status, "model_any_required_question_decision", {}

    if rejected_required:
        return "reject", "model_required_question_rejected", rejected_required[0].get("question") or {}
    if required_questions and len(accepted_required) >= len(required_questions):
        return "accept", "model_all_required_questions_accepted", accepted_required[-1].get("question") or {}
    if waiting:
        return "waiting", "model_waiting_for_required_question_answer", waiting[0].get("question") or {}
    if not_asked:
        return "not_asked", "model_need_ask_next_required_question", not_asked[0].get("question") or {}
    if unclear:
        return "unclear", "model_required_question_answer_unclear", unclear[0].get("question") or {}
    return requested_status, "model_required_question_decision", {}


def build_model_screening_analysis(
    model_result: dict,
    questions: list[dict],
    progress: list[dict],
    mode: str,
    context: dict,
    fallback: dict,
    flow_name: str,
) -> dict:
    status, reason, decision_question = enforce_screening_mode_decision(model_result, questions, progress, mode)
    raw_status = normalize_screening_status(str(model_result.get("status") or model_result.get("decision") or ""))
    final_reason = reason if raw_status and raw_status != status else str(model_result.get("reason") or reason)
    last_other = context.get("lastOtherMessage") if isinstance(context.get("lastOtherMessage"), dict) else {}
    latest_answer_text = safe_text(
        str(model_result.get("latestAnswerText") or model_result.get("evidence") or (last_other or {}).get("text") or ""),
        180,
    )
    analysis = {
        **fallback,
        "status": status,
        "reason": safe_text(str(final_reason), 120),
        "mode": mode,
        "questions": questions,
        "progress": progress,
        "decisionQuestion": decision_question,
        "lastOther": last_other,
        "latestAnswerText": latest_answer_text,
        "modelDecision": {
            "enabled": True,
            "flow": flow_name,
            "rawStatus": safe_text(str(model_result.get("status") or model_result.get("decision") or ""), 40),
            "reason": safe_text(str(model_result.get("reason") or ""), 160),
            "confidence": model_result.get("confidence"),
            "summary": safe_text(str(model_result.get("summary") or model_result.get("analysis") or ""), 220),
            "shouldRequestResume": bool(model_result.get("shouldRequestResume")) and status == "accept",
            "shouldSkip": bool(model_result.get("shouldSkip")),
        },
    }
    if status == "not_asked" and decision_question:
        analysis["nextQuestion"] = decision_question
    if status in {"accept", "reject", "unclear"}:
        analysis["decisionBasis"] = build_screening_decision_basis(
            status,
            analysis.get("reason") or "",
            basic_message=fallback.get("basicMessage") if isinstance(fallback.get("basicMessage"), dict) else {},
            last_other=last_other,
            other_messages=recent_unanswered_other_messages(context, max_count=5),
            judgement={
                "reason": analysis.get("reason") or "",
                "confidence": model_result.get("confidence"),
            },
            decision_message=last_other,
        )
    return analysis


def ask_agent_model_for_position_screening_decision(
    context: dict,
    screening: dict,
    rule_analysis: dict,
    previous_state: dict | None = None,
) -> dict:
    if not has_model_key():
        return {}
    questions = normalize_position_screening_questions(screening)
    if not questions:
        return {}
    messages = context.get("messages") if isinstance(context.get("messages"), list) else []
    previous_state = previous_state if isinstance(previous_state, dict) else {}
    has_screening_signal = bool(previous_state.get("lastQuestion"))
    if not has_screening_signal:
        for item in messages:
            if not isinstance(item, dict) or item.get("sender") != "me":
                continue
            if any(position_screening_question_matches_any(str(item.get("text") or ""), question) for question in questions):
                has_screening_signal = True
                break
    if not has_screening_signal and str(rule_analysis.get("status") or "") == "not_asked":
        return {}

    compact_messages = compact_messages_for_screening_model(messages)
    config = load_model_config()
    api_key = config.get("apiKey")
    if not api_key:
        return {}
    compact_screening = {
        "mode": str(screening.get("mode") or "ask_required_questions"),
        "passRule": safe_text(str(screening.get("passRule") or ""), 220),
        "failRule": safe_text(str(screening.get("failRule") or ""), 220),
        "questions": questions,
    }
    system_prompt = """
你是招聘自动化里的“岗位筛选结构化判定器”，不是自由聊天助手。
你只能根据岗位 screening 配置和聊天记录判断候选人是否满足当前岗位筛选问题。

规则：
1. 不要新增筛选条件，不要修改岗位原本要问的问题，只能围绕 input.screening.questions 判断。
2. 每个 conditionResults 必须对应一个配置里的 question id。
3. 如果我方问了一个筛选问题，候选人的后续回复可能同时回答多个问题；你要把这些回答映射到所有对应条件。
4. 如果没有问过某个必问问题，且候选人也没有明确主动回答它，该条件是 not_asked。
5. ask_required_questions：任意必问项明确不满足 => reject；所有必问项明确满足 => accept；缺少必问项 => not_asked 或 waiting/unclear。
6. ask_any_required_question：任意一个问题明确满足 => accept；所有问题都明确不满足 => reject；否则继续问/等待。
7. “考虑下/再看看/了解一下/晚点说”是 unclear，不是 accept。
8. 候选人发简历、附件、PDF，不能单独视为通过；只有筛选条件满足时 shouldRequestResume 才能为 true。
9. 只输出 JSON，不要 Markdown。

输出格式：
{
  "status": "not_asked | waiting | accept | reject | unclear",
  "reason": "简短原因",
  "confidence": 0.0,
  "conditionResults": [
    {"id": "question id", "status": "not_asked | waiting | accept | reject | unclear", "asked": true, "evidence": "候选人原话", "reason": "原因", "confidence": 0.0}
  ],
  "nextQuestionId": "下一条需要问的问题id，若不需要则为空",
  "shouldRequestResume": false,
  "shouldSkip": false,
  "summary": "一句话说明依据"
}
""".strip()
    user_prompt = {
        "appliedPosition": context.get("appliedPosition") or "",
        "screening": compact_screening,
        "messages": compact_messages,
        "previousState": {
            "status": previous_state.get("status") or "",
            "lastQuestionId": previous_state.get("lastQuestionId") or "",
            "lastQuestion": previous_state.get("lastQuestion") or "",
        },
        "ruleAnalysis": {
            "status": rule_analysis.get("status") or "",
            "reason": rule_analysis.get("reason") or "",
            "latestAnswerText": rule_analysis.get("latestAnswerText") or "",
        },
    }
    payload = {
        "model": PROACTIVE_SEMANTIC_MODEL or config.get("model", DEFAULT_MODEL_CONFIG["model"]),
        "messages": [
            {"role": "system", "content": system_prompt},
            {"role": "user", "content": json.dumps(user_prompt, ensure_ascii=False)},
        ],
        "temperature": 0.05,
        "response_format": {"type": "json_object"},
    }
    content = call_chat_completion(config, api_key, payload, timeout=SCREENING_MODEL_TIMEOUT_SECONDS)
    parsed = parse_json_object(content)
    return parsed if isinstance(parsed, dict) else {}


def normalize_candidate_conversation_review(raw: dict, context: dict, previous_state: dict | None = None) -> dict:
    raw = raw if isinstance(raw, dict) else {}
    previous_state = previous_state if isinstance(previous_state, dict) else {}
    status = str(raw.get("acceptanceStatus") or raw.get("acceptance") or raw.get("basicConditionStatus") or "").strip().lower()
    status_aliases = {
        "accepted": "accept",
        "yes": "accept",
        "pass": "accept",
        "rejected": "reject",
        "no": "reject",
        "unknown": "unclear",
        "pending": "waiting",
    }
    status = status_aliases.get(status, status)
    if status not in {"accept", "reject", "unclear", "waiting", ""}:
        status = "unclear"

    def clean_question_items(values: object) -> list[dict]:
        cleaned: list[dict] = []
        if not isinstance(values, list):
            return cleaned
        for item in values[:RECENT_UNANSWERED_OTHER_LIMIT * 2]:
            if not isinstance(item, dict):
                continue
            text = safe_text(str(item.get("text") or item.get("question") or item.get("sourceText") or ""), 180)
            if not text:
                continue
            try:
                message_index = int(item.get("messageIndex"))
            except Exception:
                message_index = None
            cleaned.append({
                "text": text,
                "question": text,
                "topic": safe_text(str(item.get("topic") or item.get("topicHint") or ""), 60),
                "sourceText": safe_text(str(item.get("sourceText") or text), 180),
                "messageIndex": message_index,
                "time": safe_text(str(item.get("time") or ""), 30),
                "answered": bool(item.get("answered", False)),
                "reason": safe_text(str(item.get("reason") or ""), 120),
            })
        return cleaned[-RECENT_UNANSWERED_OTHER_LIMIT:]

    def clean_answered_items(values: object) -> list[dict]:
        cleaned: list[dict] = []
        if not isinstance(values, list):
            return cleaned
        for item in values[:12]:
            if not isinstance(item, dict):
                continue
            text = safe_text(str(item.get("text") or item.get("question") or ""), 180)
            answer = safe_text(str(item.get("answer") or item.get("reply") or ""), 120)
            if not text and not answer:
                continue
            cleaned.append({
                "text": text,
                "answer": answer,
                "topic": safe_text(str(item.get("topic") or item.get("topicHint") or ""), 60),
                "reason": safe_text(str(item.get("reason") or ""), 120),
            })
        return cleaned

    unanswered = clean_question_items(raw.get("unansweredQuestions") or raw.get("pendingQuestions") or raw.get("questionsToAnswer"))
    answered = clean_answered_items(raw.get("answeredQuestions") or raw.get("resolvedQuestions"))
    actions_done = raw.get("actionsDone") if isinstance(raw.get("actionsDone"), list) else raw.get("handledActions") if isinstance(raw.get("handledActions"), list) else []
    review = {
        "modelEnabled": True,
        "acceptanceStatus": status,
        "pendingReplyNeeded": bool(raw.get("pendingReplyNeeded") or raw.get("needsReply") or unanswered),
        "shouldRequestResume": bool(raw.get("shouldRequestResume")),
        "shouldSkip": bool(raw.get("shouldSkip")),
        "recommendedNextAction": safe_text(str(raw.get("recommendedNextAction") or raw.get("nextAction") or ""), 60),
        "summary": safe_text(str(raw.get("summary") or raw.get("conversationSummary") or ""), 500),
        "unansweredQuestions": unanswered,
        "answeredQuestions": answered,
        "actionsDone": [safe_text(str(item), 80) for item in actions_done[:12]],
        "rawConfidence": raw.get("confidence"),
        "lastOtherSignature": str((context.get("lastOtherSignature") or "")) if isinstance(context, dict) else "",
        "previousStatus": safe_text(str(previous_state.get("status") or ""), 40),
    }
    return review


def ask_agent_model_for_candidate_conversation_review(
    context: dict,
    previous_state: dict | None = None,
    rule_analysis: dict | None = None,
) -> dict:
    if not has_model_key():
        return {}
    config = load_model_config()
    api_key = config.get("apiKey")
    if not api_key:
        return {}
    previous_state = previous_state if isinstance(previous_state, dict) else {}
    messages = context.get("messages") if isinstance(context.get("messages"), list) else []
    compact_messages = compact_messages_for_screening_model(messages, limit=SCREENING_MODEL_MESSAGE_LIMIT)
    if not compact_messages:
        return {}
    kb = context.get("companyKnowledgeBase") if isinstance(context.get("companyKnowledgeBase"), dict) else {}
    memory = context.get("memory") if isinstance(context.get("memory"), dict) else {}
    rule_pending = [
        {
            "text": safe_text(str(item.get("text") or ""), 180),
            "time": safe_text(str(item.get("time") or ""), 30),
            "signature": chat_message_signature(item),
        }
        for item in recent_unanswered_other_messages(context, previous_state)
        if isinstance(item, dict)
    ]
    system_prompt = """
你是招聘智能体里的“候选人会话复盘器”，不是自由聊天助手。
你的任务是阅读近几轮 BOSS 招聘聊天，结构化判断候选人说了什么、我们处理过什么、还有哪些问题没回复、候选人是否接受基础条件，以及下一步应该做什么。

必须遵守：
1. 以 messages 为准，sender=other 是候选人，sender=me 是我方。
2. 判断 unansweredQuestions 时，不要只看问号；“加班时间和工作时间”“住宿情况”“薪资待遇”这种名词式追问也算问题。
3. 如果候选人同一轮既表示接受，又追问问题，应同时输出 acceptanceStatus=accept 和 unansweredQuestions，recommendedNextAction 应是 answer_then_request_resume。
4. 如果我方后续消息已经回答过某个问题，不要把它放进 unansweredQuestions。
5. 不要编造知识库里没有的信息；这里只做结构化判断，不直接生成长回复。
6. 未配置岗位或没有知识库时，也要如实输出 pending 问题，但 shouldRequestResume 不要乱设 true。
7. 只输出 JSON，不要 Markdown。

输出格式：
{
  "acceptanceStatus": "accept | reject | unclear | waiting",
  "pendingReplyNeeded": true,
  "unansweredQuestions": [
    {"text": "候选人未回复的问题", "messageIndex": 12, "sourceText": "候选人原话", "topic": "工时/住宿/薪资等", "reason": "为什么未回复"}
  ],
  "answeredQuestions": [
    {"text": "已回答的问题", "answer": "我方已回答内容", "topic": "主题"}
  ],
  "actionsDone": ["已发送基础情况", "已求简历", "已答疑"],
  "shouldRequestResume": false,
  "shouldSkip": false,
  "recommendedNextAction": "answer_only | request_resume | answer_then_request_resume | send_basic_conditions | skip | wait",
  "summary": "一句话总结当前候选人状态",
  "confidence": 0.0
}
""".strip()
    user_prompt = {
        "appliedPosition": context.get("appliedPosition") or "",
        "candidate": (context.get("applicant") if isinstance(context.get("applicant"), dict) else {}),
        "messages": compact_messages,
        "memory": {
            "summary": safe_text(str(memory.get("summary") or ""), 500),
            "recentMyMessages": list(memory.get("recentMyMessages") or [])[-6:],
            "recentOtherMessages": list(memory.get("recentOtherMessages") or [])[-6:],
        },
        "knowledgeBase": compact_company_knowledge_base_for_model(kb) if kb.get("enabled") else {},
        "previousState": {
            "status": previous_state.get("status") or "",
            "stage": previous_state.get("stage") or "",
            "knowledgeAnsweredSignatures": previous_state.get("knowledgeAnsweredSignatures") or [],
            "conversationReview": previous_state.get("conversationReview") if isinstance(previous_state.get("conversationReview"), dict) else {},
        },
        "ruleSignals": {
            "ruleAnalysis": rule_analysis if isinstance(rule_analysis, dict) else {},
            "recentUnansweredOtherMessages": rule_pending,
        },
    }
    payload = {
        "model": config.get("model", DEFAULT_MODEL_CONFIG["model"]),
        "messages": [
            {"role": "system", "content": system_prompt},
            {"role": "user", "content": json.dumps(user_prompt, ensure_ascii=False)},
        ],
        "temperature": 0.05,
        "response_format": {"type": "json_object"},
    }
    content = call_chat_completion(config, api_key, payload, timeout=SCREENING_MODEL_TIMEOUT_SECONDS)
    parsed = parse_json_object(content)
    return parsed if isinstance(parsed, dict) else {}


def ensure_candidate_conversation_review(
    context: dict,
    previous_state: dict | None = None,
    rule_analysis: dict | None = None,
) -> dict:
    if not isinstance(context, dict):
        return {}
    previous_state = previous_state if isinstance(previous_state, dict) else {}
    existing = context.get("conversationReview")
    if isinstance(existing, dict) and existing.get("modelEnabled"):
        return existing
    previous_review = previous_state.get("conversationReview") if isinstance(previous_state.get("conversationReview"), dict) else {}
    current_last_other_signature = str(context.get("lastOtherSignature") or "").strip()
    previous_last_other_signature = str(previous_review.get("lastOtherSignature") or "").strip()
    if (
        previous_review.get("modelEnabled")
        and current_last_other_signature
        and previous_last_other_signature == current_last_other_signature
    ):
        context["conversationReview"] = previous_review
        if isinstance(context.get("memory"), dict):
            context["memory"]["conversationReview"] = compact_candidate_conversation_review(previous_review)
        return previous_review
    try:
        raw = ask_agent_model_for_candidate_conversation_review(context, previous_state, rule_analysis)
    except Exception as error:
        review = {
            "modelEnabled": False,
            "error": safe_text(str(error), 180),
            "summary": "",
            "unansweredQuestions": [],
            "answeredQuestions": [],
        }
        context["conversationReview"] = review
        return review
    if not raw:
        return {}
    review = normalize_candidate_conversation_review(raw, context, previous_state)
    context["conversationReview"] = review
    if isinstance(context.get("memory"), dict):
        context["memory"]["conversationReview"] = compact_candidate_conversation_review(review)
    return review


def enhance_position_screening_with_model(
    context: dict,
    screening: dict,
    rule_analysis: dict,
    previous_state: dict | None = None,
) -> dict:
    questions = normalize_position_screening_questions(screening)
    if not questions:
        return rule_analysis
    if (
        str(rule_analysis.get("status") or "") == "reject"
        and str(rule_analysis.get("reason") or "") == "candidate_message_matched_disqualifying_pattern"
    ):
        preserved = dict(rule_analysis)
        preserved["modelDecision"] = {
            "enabled": False,
            "flow": "position_screening",
            "reason": "rule_disqualifying_message_preserved",
        }
        return preserved
    try:
        model_result = ask_agent_model_for_position_screening_decision(context, screening, rule_analysis, previous_state)
    except Exception as error:
        enriched = dict(rule_analysis)
        enriched["modelDecision"] = {
            "enabled": False,
            "error": safe_text(str(error), 180),
            "flow": "position_screening",
        }
        return enriched
    if not model_result:
        return rule_analysis
    progress = normalize_model_condition_results(model_result, questions, rule_analysis.get("progress") if isinstance(rule_analysis.get("progress"), list) else [])
    mode = str((screening or {}).get("mode") or rule_analysis.get("mode") or "ask_required_questions").strip() or "ask_required_questions"
    return build_model_screening_analysis(
        model_result,
        questions,
        progress,
        mode,
        context,
        rule_analysis,
        "position_screening",
    )


def ask_agent_model_for_basic_condition_decision(
    context: dict,
    phrase: str,
    rule_analysis: dict,
    previous_state: dict | None = None,
) -> dict:
    if not has_model_key():
        return {}
    messages = context.get("messages") if isinstance(context.get("messages"), list) else []
    compact_messages = compact_messages_for_screening_model(messages)
    if not compact_messages:
        return {}
    config = load_model_config()
    api_key = config.get("apiKey")
    if not api_key:
        return {}
    conditions = basic_condition_screening_questions()
    previous_state = previous_state if isinstance(previous_state, dict) else {}
    system_prompt = """
你是 AI 应用开发实习生基础条件筛选的结构化判定器。
你只能根据我方已发送的基础情况话术、候选人最近回复、以及硬性条件判断是否可以求简历。

硬性条件：
- 日薪150能否接受
- 单休能否接受
- 线下工作能否接受
- 至少实习六个月能否接受
- 工作地点能否接受

规则：
1. “基本情况可以/都能接受/这些都可以/没问题”可以视为所有硬性条件 accept。
2. “工作地点可以接受/地点能接受”只代表工作地点，不代表薪资、单休、线下、六个月都接受。
3. 候选人只问问题、只发简历、只发附件、只说可以发简历，都不能单独视为 accept。
4. 候选人明确不能线下、不能单休、不能实习六个月、不接受薪资/日薪150、不能接受工作地点 => reject。
5. 候选人不能尽快到岗不是硬性拒绝；到岗时间问题只算 unclear 或知识库问答，不要 reject。
6. “考虑下/再看看/了解一下/晚点回复”是 unclear。
7. accept 只有在所有硬性条件都明确接受，或用“都能接受/基本情况都可以”总括接受时成立。
8. 如果候选人说“只能/最多/只可以实习四个月、三个月、五个月”“只能暑假 2-3 个月”“开学要回学校所以无法满六个月”等少于六个月，即使同时说“其他都接受”，也必须判 reject，six_months 条件为 reject。
9. 只输出 JSON，不要 Markdown。

输出格式：
{
  "status": "waiting | accept | reject | unclear",
  "reason": "简短原因",
  "confidence": 0.0,
  "conditionResults": [
    {"id": "salary", "status": "accept | reject | unclear | waiting", "evidence": "候选人原话", "reason": "原因", "confidence": 0.0}
  ],
  "shouldRequestResume": false,
  "shouldSkip": false,
  "summary": "一句话说明依据"
}
""".strip()
    user_prompt = {
        "appliedPosition": context.get("appliedPosition") or "",
        "basicPhrase": safe_text(str(phrase or ""), 360),
        "hardConditions": conditions,
        "messages": compact_messages,
        "previousState": {
            "status": previous_state.get("status") or "",
            "lastScreening": previous_state.get("lastScreening") or "",
        },
        "ruleAnalysis": {
            "status": rule_analysis.get("status") or "",
            "reason": rule_analysis.get("reason") or "",
            "latestAnswerText": rule_analysis.get("latestAnswerText") or "",
            "decisionBasis": rule_analysis.get("decisionBasis") if isinstance(rule_analysis.get("decisionBasis"), dict) else {},
        },
    }
    payload = {
        "model": config.get("model", DEFAULT_MODEL_CONFIG["model"]),
        "messages": [
            {"role": "system", "content": system_prompt},
            {"role": "user", "content": json.dumps(user_prompt, ensure_ascii=False)},
        ],
        "temperature": 0.05,
        "response_format": {"type": "json_object"},
    }
    content = call_chat_completion(config, api_key, payload, timeout=SCREENING_MODEL_TIMEOUT_SECONDS)
    parsed = parse_json_object(content)
    return parsed if isinstance(parsed, dict) else {}


def enhance_basic_condition_screening_with_model(
    context: dict,
    phrase: str,
    rule_analysis: dict,
    previous_state: dict | None = None,
) -> dict:
    if str(rule_analysis.get("status") or "") == "not_asked":
        return rule_analysis
    if str(rule_analysis.get("status") or "") == "waiting" and not isinstance(rule_analysis.get("lastOther"), dict):
        return rule_analysis
    if str(rule_analysis.get("status") or "") == "accept":
        last_other = rule_analysis.get("decisionMessage") if isinstance(rule_analysis.get("decisionMessage"), dict) else rule_analysis.get("lastOther")
        last_text = str((last_other or {}).get("text") or "")
        if (
            str(rule_analysis.get("reason") or "") == "candidate_accepted_basic_conditions"
            and is_direct_basic_condition_acceptance_reply(last_text)
        ):
            preserved = dict(rule_analysis)
            preserved["modelDecision"] = {
                "enabled": False,
                "flow": "basic_conditions",
                "reason": "direct_short_acceptance_preserved",
            }
            return preserved
    if str(rule_analysis.get("status") or "") == "reject" and str(rule_analysis.get("reason") or "") in {
        "candidate_cannot_intern_six_months",
        "candidate_internship_duration_less_than_six_months",
        "candidate_can_only_intern_until_september",
        "candidate_rejected_required_condition",
        "candidate_rejected_required_condition_before_resume_attachment",
    }:
        preserved = dict(rule_analysis)
        preserved["modelDecision"] = {
            "enabled": False,
            "flow": "basic_conditions",
            "reason": "rule_hard_reject_preserved",
        }
        return preserved
    try:
        model_result = ask_agent_model_for_basic_condition_decision(context, phrase, rule_analysis, previous_state)
    except Exception as error:
        enriched = dict(rule_analysis)
        enriched["modelDecision"] = {
            "enabled": False,
            "error": safe_text(str(error), 180),
            "flow": "basic_conditions",
        }
        return enriched
    if not model_result:
        return rule_analysis
    questions = basic_condition_screening_questions()
    progress = normalize_model_condition_results(model_result, questions, [])
    fallback = dict(rule_analysis)
    fallback.setdefault("questions", questions)
    fallback.setdefault("progress", progress)
    analysis = build_model_screening_analysis(
        model_result,
        questions,
        progress,
        "ask_required_questions",
        context,
        fallback,
        "basic_conditions",
    )
    if analysis.get("status") == "not_asked":
        analysis["status"] = "unclear"
        analysis["reason"] = "model_basic_conditions_partial_or_missing_acceptance"
        analysis.pop("nextQuestion", None)
    return analysis


def preserve_zhilian_basic_acceptance_after_model(model_analysis: dict, rule_analysis: dict, platform: str = "zhilian") -> dict:
    if not isinstance(model_analysis, dict) or not isinstance(rule_analysis, dict):
        return model_analysis
    if str(rule_analysis.get("status") or "") != "accept":
        return model_analysis
    if str(model_analysis.get("status") or "") not in {"unclear", "waiting", "not_asked"}:
        return model_analysis
    preserved = dict(rule_analysis)
    preserved["modelDecision"] = {
        "enabled": True,
        "flow": "basic_conditions",
        "reason": f"{platform}_rule_accept_preserved_after_model",
        "modelStatus": str(model_analysis.get("status") or ""),
        "modelReason": safe_text(str(model_analysis.get("reason") or ""), 160),
    }
    preserved["modelOverrideIgnored"] = {
        "status": str(model_analysis.get("status") or ""),
        "reason": safe_text(str(model_analysis.get("reason") or ""), 160),
        "latestAnswerText": safe_text(str(model_analysis.get("latestAnswerText") or ""), 180),
    }
    return preserved


def analyze_position_screening(messages: list[dict], screening: dict) -> dict:
    if not isinstance(messages, list):
        messages = []
    questions = normalize_position_screening_questions(screening)
    mode = str((screening or {}).get("mode") or "ask_required_questions").strip() or "ask_required_questions"
    if not questions:
        return {
            "status": "not_configured",
            "reason": "position_screening_questions_missing",
            "questions": [],
        }
    disqualifying = match_position_screening_disqualifying_message(messages, screening)
    if disqualifying.get("matched"):
        message = disqualifying.get("message") if isinstance(disqualifying.get("message"), dict) else {}
        answer_text = str(message.get("text") or "").strip()
        return {
            "status": "reject",
            "reason": "candidate_message_matched_disqualifying_pattern",
            "mode": mode,
            "questions": questions,
            "progress": [
                {
                    "question": {
                        "id": disqualifying.get("id") or "disqualifying_candidate_message",
                        "text": disqualifying.get("reason") or "候选人消息命中岗位不匹配规则",
                        "required": True,
                    },
                    "asked": False,
                    "askedMessage": {},
                    "answerMessages": [message] if message else [],
                    "answerText": safe_text(answer_text, 180),
                    "judgement": {
                        "status": "reject",
                        "confidence": 0.92,
                        "reason": disqualifying.get("reason") or "candidate_message_matched_disqualifying_pattern",
                        "sourceText": safe_text(answer_text, 160),
                    },
                    "status": "reject",
                }
            ],
            "decisionQuestion": {
                "id": disqualifying.get("id") or "disqualifying_candidate_message",
                "text": disqualifying.get("reason") or "候选人消息命中岗位不匹配规则",
                "required": True,
            },
            "lastOther": message,
            "latestAnswerText": safe_text(answer_text, 180),
            "disqualifyingPattern": disqualifying,
        }

    progress: list[dict] = []
    latest_answer_text = ""
    for question in questions:
        asked_index = -1
        asked_message: dict = {}
        for index, item in enumerate(messages):
            if not isinstance(item, dict) or item.get("sender") != "me":
                continue
            if position_screening_question_matches_any(str(item.get("text") or ""), question):
                asked_index = index
                asked_message = item

        answer_messages: list[dict] = []
        if asked_index >= 0:
            for item in messages[asked_index + 1:]:
                if not isinstance(item, dict):
                    continue
                if item.get("sender") == "me" and any(
                    position_screening_question_matches_any(str(item.get("text") or ""), other)
                    for other in questions
                ):
                    break
                if item.get("sender") != "other":
                    continue
                text = str(item.get("text") or "").strip()
                if not is_effective_chat_text(text):
                    continue
                answer_messages.append(item)
        answer_text = "\n".join(str(item.get("text") or "").strip() for item in answer_messages[-3:] if str(item.get("text") or "").strip())
        if answer_text:
            latest_answer_text = answer_text
        judgement = classify_position_screening_answer(str(question.get("text") or ""), answer_text) if answer_text else {
            "status": "waiting" if asked_index >= 0 else "not_asked",
            "confidence": 0.0,
            "reason": "question_not_asked" if asked_index < 0 else "waiting_for_candidate_reply",
            "sourceText": "",
        }
        progress.append({
            "question": question,
            "asked": asked_index >= 0,
            "askedMessage": asked_message,
            "answerMessages": answer_messages[-3:],
            "answerText": safe_text(answer_text, 180),
            "judgement": judgement,
            "status": judgement.get("status") or "unclear",
        })

    rejected = [item for item in progress if item.get("status") == "reject"]
    accepted = [item for item in progress if item.get("status") == "accept"]
    waiting = [item for item in progress if item.get("status") == "waiting"]
    unclear = [item for item in progress if item.get("status") == "unclear"]
    not_asked = [item for item in progress if item.get("status") == "not_asked"]

    if mode == "ask_any_required_question":
        if accepted:
            return {
                "status": "accept",
                "reason": "any_required_question_accepted",
                "mode": mode,
                "questions": questions,
                "progress": progress,
                "decisionQuestion": accepted[0].get("question"),
                "lastOther": (accepted[0].get("answerMessages") or [{}])[-1] if accepted[0].get("answerMessages") else {},
                "latestAnswerText": safe_text(latest_answer_text, 180),
            }
        if len(rejected) >= len(questions):
            return {
                "status": "reject",
                "reason": "all_any_required_questions_rejected",
                "mode": mode,
                "questions": questions,
                "progress": progress,
                "decisionQuestion": rejected[-1].get("question") if rejected else {},
                "lastOther": (rejected[-1].get("answerMessages") or [{}])[-1] if rejected and rejected[-1].get("answerMessages") else {},
                "latestAnswerText": safe_text(latest_answer_text, 180),
            }
        if waiting:
            return {
                "status": "waiting",
                "reason": "waiting_for_any_required_question_answer",
                "mode": mode,
                "questions": questions,
                "progress": progress,
                "decisionQuestion": waiting[0].get("question"),
                "latestAnswerText": safe_text(latest_answer_text, 180),
            }
        if not_asked:
            return {
                "status": "not_asked",
                "reason": "need_ask_next_any_required_question",
                "mode": mode,
                "questions": questions,
                "progress": progress,
                "nextQuestion": not_asked[0].get("question"),
                "latestAnswerText": safe_text(latest_answer_text, 180),
            }
        return {
            "status": "unclear",
            "reason": "any_required_question_unclear",
            "mode": mode,
            "questions": questions,
            "progress": progress,
            "lastOther": (unclear[-1].get("answerMessages") or [{}])[-1] if unclear and unclear[-1].get("answerMessages") else {},
            "latestAnswerText": safe_text(latest_answer_text, 180),
        }

    if rejected:
        return {
            "status": "reject",
            "reason": "required_question_rejected",
            "mode": mode,
            "questions": questions,
            "progress": progress,
            "decisionQuestion": rejected[0].get("question"),
            "lastOther": (rejected[0].get("answerMessages") or [{}])[-1] if rejected[0].get("answerMessages") else {},
            "latestAnswerText": safe_text(latest_answer_text, 180),
        }
    if len(accepted) >= len(questions):
        return {
            "status": "accept",
            "reason": "all_required_questions_accepted",
            "mode": mode,
            "questions": questions,
            "progress": progress,
            "decisionQuestion": accepted[-1].get("question") if accepted else {},
            "lastOther": (accepted[-1].get("answerMessages") or [{}])[-1] if accepted and accepted[-1].get("answerMessages") else {},
            "latestAnswerText": safe_text(latest_answer_text, 180),
        }
    if waiting:
        return {
            "status": "waiting",
            "reason": "waiting_for_required_question_answer",
            "mode": mode,
            "questions": questions,
            "progress": progress,
            "decisionQuestion": waiting[0].get("question"),
            "latestAnswerText": safe_text(latest_answer_text, 180),
        }
    if unclear:
        return {
            "status": "unclear",
            "reason": "required_question_answer_unclear",
            "mode": mode,
            "questions": questions,
            "progress": progress,
            "decisionQuestion": unclear[0].get("question"),
            "lastOther": (unclear[0].get("answerMessages") or [{}])[-1] if unclear[0].get("answerMessages") else {},
            "latestAnswerText": safe_text(latest_answer_text, 180),
        }
    if not_asked:
        return {
            "status": "not_asked",
            "reason": "need_ask_next_required_question",
            "mode": mode,
            "questions": questions,
            "progress": progress,
            "nextQuestion": not_asked[0].get("question"),
            "latestAnswerText": safe_text(latest_answer_text, 180),
        }
    return {
        "status": "unclear",
        "reason": "position_screening_fallback_unclear",
        "mode": mode,
        "questions": questions,
        "progress": progress,
        "latestAnswerText": safe_text(latest_answer_text, 180),
    }


def build_position_screening_analysis_from_progress(
    questions: list[dict],
    progress: list[dict],
    mode: str,
    latest_answer_text: str,
    reason_prefix: str = "",
) -> dict:
    rejected = [item for item in progress if item.get("status") == "reject"]
    accepted = [item for item in progress if item.get("status") == "accept"]
    waiting = [item for item in progress if item.get("status") == "waiting"]
    unclear = [item for item in progress if item.get("status") == "unclear"]
    not_asked = [item for item in progress if item.get("status") == "not_asked"]
    reason_prefix = str(reason_prefix or "").strip()

    def with_reason(reason: str) -> str:
        return f"{reason_prefix}:{reason}" if reason_prefix else reason

    if mode == "ask_any_required_question":
        if accepted:
            return {
                "status": "accept",
                "reason": with_reason("any_required_question_accepted"),
                "mode": mode,
                "questions": questions,
                "progress": progress,
                "decisionQuestion": accepted[0].get("question"),
                "lastOther": (accepted[0].get("answerMessages") or [{}])[-1] if accepted[0].get("answerMessages") else {},
                "latestAnswerText": safe_text(latest_answer_text, 180),
            }
        if len(rejected) >= len(questions):
            return {
                "status": "reject",
                "reason": with_reason("all_any_required_questions_rejected"),
                "mode": mode,
                "questions": questions,
                "progress": progress,
                "decisionQuestion": rejected[-1].get("question") if rejected else {},
                "lastOther": (rejected[-1].get("answerMessages") or [{}])[-1] if rejected and rejected[-1].get("answerMessages") else {},
                "latestAnswerText": safe_text(latest_answer_text, 180),
            }
        if waiting:
            return {
                "status": "waiting",
                "reason": with_reason("waiting_for_any_required_question_answer"),
                "mode": mode,
                "questions": questions,
                "progress": progress,
                "decisionQuestion": waiting[0].get("question"),
                "latestAnswerText": safe_text(latest_answer_text, 180),
            }
        if not_asked:
            return {
                "status": "not_asked",
                "reason": with_reason("need_ask_next_any_required_question"),
                "mode": mode,
                "questions": questions,
                "progress": progress,
                "nextQuestion": not_asked[0].get("question"),
                "latestAnswerText": safe_text(latest_answer_text, 180),
            }
        return {
            "status": "unclear",
            "reason": with_reason("any_required_question_unclear"),
            "mode": mode,
            "questions": questions,
            "progress": progress,
            "lastOther": (unclear[-1].get("answerMessages") or [{}])[-1] if unclear and unclear[-1].get("answerMessages") else {},
            "latestAnswerText": safe_text(latest_answer_text, 180),
        }

    if rejected:
        return {
            "status": "reject",
            "reason": with_reason("required_question_rejected"),
            "mode": mode,
            "questions": questions,
            "progress": progress,
            "decisionQuestion": rejected[0].get("question"),
            "lastOther": (rejected[0].get("answerMessages") or [{}])[-1] if rejected[0].get("answerMessages") else {},
            "latestAnswerText": safe_text(latest_answer_text, 180),
        }
    if len(accepted) >= len(questions):
        return {
            "status": "accept",
            "reason": with_reason("all_required_questions_accepted"),
            "mode": mode,
            "questions": questions,
            "progress": progress,
            "decisionQuestion": accepted[-1].get("question") if accepted else {},
            "lastOther": (accepted[-1].get("answerMessages") or [{}])[-1] if accepted and accepted[-1].get("answerMessages") else {},
            "latestAnswerText": safe_text(latest_answer_text, 180),
        }
    if waiting:
        return {
            "status": "waiting",
            "reason": with_reason("waiting_for_required_question_answer"),
            "mode": mode,
            "questions": questions,
            "progress": progress,
            "decisionQuestion": waiting[0].get("question"),
            "latestAnswerText": safe_text(latest_answer_text, 180),
        }
    if unclear:
        return {
            "status": "unclear",
            "reason": with_reason("required_question_answer_unclear"),
            "mode": mode,
            "questions": questions,
            "progress": progress,
            "decisionQuestion": unclear[0].get("question"),
            "lastOther": (unclear[0].get("answerMessages") or [{}])[-1] if unclear[0].get("answerMessages") else {},
            "latestAnswerText": safe_text(latest_answer_text, 180),
        }
    if not_asked:
        return {
            "status": "not_asked",
            "reason": with_reason("need_ask_next_required_question"),
            "mode": mode,
            "questions": questions,
            "progress": progress,
            "nextQuestion": not_asked[0].get("question"),
            "latestAnswerText": safe_text(latest_answer_text, 180),
        }
    return {
        "status": "unclear",
        "reason": with_reason("position_screening_fallback_unclear"),
        "mode": mode,
        "questions": questions,
        "progress": progress,
        "latestAnswerText": safe_text(latest_answer_text, 180),
    }


def repair_position_screening_with_waiting_state_reply(analysis: dict, previous_state: dict, context: dict) -> dict:
    if not isinstance(analysis, dict) or str(analysis.get("status") or "") not in {"not_asked", "waiting", "unclear"}:
        return analysis
    if not isinstance(previous_state, dict) or previous_state.get("status") not in {"position_screening_sent_waiting", "position_screening_waiting"}:
        return analysis
    previous_question_text = str(previous_state.get("lastQuestion") or previous_state.get("lastQuestionCanonical") or "").strip()
    if not previous_question_text:
        return analysis
    last_message = context.get("lastMessage") if isinstance(context.get("lastMessage"), dict) else {}
    last_other = context.get("lastOtherMessage") if isinstance(context.get("lastOtherMessage"), dict) else {}
    last_text = str(last_other.get("text") or "").strip()
    if last_message.get("sender") != "other" or not last_text:
        return analysis
    judgement = classify_position_screening_answer(previous_question_text, last_text)
    if judgement.get("status") not in {"accept", "reject"}:
        return analysis

    questions = analysis.get("questions") if isinstance(analysis.get("questions"), list) else []
    progress = [dict(item) for item in analysis.get("progress", []) if isinstance(item, dict)]
    previous_question = question_by_id_or_text(
        questions,
        str(previous_state.get("lastQuestionId") or ""),
        previous_question_text,
    )
    if not previous_question:
        previous_question = {"id": safe_text(str(previous_state.get("lastQuestionId") or ""), 60), "text": previous_question_text}

    updated = False
    previous_qid = str(previous_question.get("id") or "").strip()
    for item in progress:
        question = item.get("question") if isinstance(item.get("question"), dict) else {}
        same_question = bool(
            (previous_qid and str(question.get("id") or "").strip() == previous_qid)
            or position_screening_question_matches_any(previous_question_text, question)
            or position_screening_question_matches(str(question.get("text") or ""), previous_question_text)
        )
        if not same_question:
            continue
        item.update({
            "asked": True,
            "askedMessage": {"sender": "me", "text": previous_question_text},
            "answerMessages": [last_other],
            "answerText": safe_text(last_text, 180),
            "judgement": judgement,
            "status": judgement.get("status") or "unclear",
            "repairedFromWaitingState": True,
        })
        updated = True
        break

    if not updated:
        progress.insert(0, {
            "question": previous_question,
            "asked": True,
            "askedMessage": {"sender": "me", "text": previous_question_text},
            "answerMessages": [last_other],
            "answerText": safe_text(last_text, 180),
            "judgement": judgement,
            "status": judgement.get("status") or "unclear",
            "repairedFromWaitingState": True,
        })

    repaired = build_position_screening_analysis_from_progress(
        questions or [item.get("question") for item in progress if isinstance(item.get("question"), dict)],
        progress,
        str(analysis.get("mode") or "ask_required_questions"),
        last_text,
        "waiting_state_latest_reply",
    )
    repaired["repairedFromWaitingState"] = True
    repaired["originalAnalysis"] = {
        "status": str(analysis.get("status") or ""),
        "reason": safe_text(str(analysis.get("reason") or ""), 160),
    }
    return repaired


def apply_basic_waiting_state_to_screening(screening: dict, previous_state: dict, context: dict) -> dict:
    if not isinstance(screening, dict):
        screening = {}
    if not isinstance(previous_state, dict):
        previous_state = {}
    if previous_state.get("status") not in {
        "basic_conditions_sent_waiting",
        "basic_conditions_waiting",
        "knowledge_answered_waiting",
        "knowledge_silent_skipped",
    }:
        return screening
    if screening.get("status") != "not_asked":
        return screening

    last_message = context.get("lastMessage") if isinstance(context.get("lastMessage"), dict) else {}
    last_other = context.get("lastOtherMessage") if isinstance(context.get("lastOtherMessage"), dict) else {}
    if last_message.get("sender") == "other" and str(last_other.get("text") or "").strip():
        judgement = classify_basic_condition_acceptance(str(last_other.get("text") or ""))
        return {
            "status": judgement.get("status", "unclear"),
            "reason": "waiting_state_new_candidate_reply:" + str(judgement.get("reason") or ""),
            "confidence": judgement.get("confidence"),
            "basicMessage": previous_state,
            "lastOther": last_other,
            "judgement": judgement,
            "state": previous_state,
            "decisionBasis": build_screening_decision_basis(
                str(judgement.get("status", "unclear")),
                "waiting_state_new_candidate_reply:" + str(judgement.get("reason") or ""),
                basic_message=previous_state,
                last_other=last_other,
                other_messages=[last_other],
                judgement=judgement,
                decision_message=last_other,
            ),
        }

    return {
        "status": "waiting",
        "reason": "basic_conditions_sent_waiting_state",
        "state": previous_state,
        "decisionBasis": build_screening_decision_basis(
            "waiting",
            "basic_conditions_sent_waiting_state",
            basic_message=previous_state,
            other_messages=[],
        ),
    }


def is_recruiter_resume_request_task(message: str) -> bool:
    text = str(message or "")
    lowered = text.lower()
    if not looks_like_recruiter_resume_request(text):
        return False
    if any(word in text for word in ("我的简历", "把我简历", "把我的简历", "我简历")):
        return False
    target_terms = ("没有回", "没回", "未回复", "未读", "新消息", "待处理", "候选人", "牛人", "下一个", "没回复")
    if any(term in text for term in target_terms) or "recruiter" in lowered:
        return True
    # On the recruiter-side BOSS chat page, a bare "求简历" should still use the
    # specialized toolbar flow instead of letting the model invent a click target.
    return "求简历" in text


def looks_like_recruiter_resume_request(message: str) -> bool:
    text = str(message or "")
    lowered = text.lower()
    if any(word in text for word in ("我的简历", "把我简历", "把我的简历", "我简历")):
        return False
    resume_terms = ("求简历", "要简历", "索要简历", "简历请求", "获取简历")
    ask_terms = ("让", "叫", "让他", "让她", "让候选人", "牛人", "候选人")
    if any(term in text for term in resume_terms):
        return True
    if "求" in text and "简历" in text:
        return True
    if re.search(r"(求|要|索要)[\u4e00-\u9fffA-Za-z0-9·._-]{2,16}(的)?简历", text):
        return True
    if "resume" in lowered and any(term in lowered for term in ("request", "ask", "candidate", "recruiter")):
        return True
    return "简历" in text and any(term in text for term in ask_terms)


def is_recruiter_proactive_contact_task(message: str) -> bool:
    text = str(message or "")
    compact = re.sub(r"\s+", "", text)
    lowered = compact.lower()
    if any(term in compact for term in ("推荐牛人", "主动联系", "主动打招呼", "批量打招呼", "打招呼")):
        return any(term in compact for term in ("推荐", "牛人", "主动", "应用技术", "应用技术经理"))
    return "proactive" in lowered and any(term in lowered for term in ("contact", "greet", "recommend"))


def is_recruiter_unsuitable_task(message: str) -> bool:
    text = str(message or "")
    compact = re.sub(r"\s+", "", text)
    lowered = compact.lower()
    if any(term in compact for term in ("求简历", "要简历", "发简历", "发送简历")):
        return False
    unsuitable_terms = ("不合适", "不匹配", "淘汰", "拒绝候选人", "标记不合适", "设为不合适", "点不合适")
    if any(term in compact for term in unsuitable_terms):
        return True
    return "unsuitable" in lowered or "notfit" in lowered or "not_fit" in lowered


def extract_recruiter_unsuitable_candidate_name(message: str) -> str:
    text = re.sub(r"\s+", "", str(message or ""))
    if not text or not is_recruiter_unsuitable_task(text):
        return ""
    patterns = (
        r"(?:把|将|给|对|向|找|打开|联系|让|叫)(?P<name>[\u4e00-\u9fffA-Za-z0-9·._-]{2,16}?)(?:标记为|设为|判为|点击|点)?(?:不合适|不匹配|淘汰|拒绝)",
        r"(?P<name>[\u4e00-\u9fffA-Za-z0-9·._-]{2,16}?)(?:标记为|设为|判为|点击|点)?(?:不合适|不匹配|淘汰)",
    )
    for pattern in patterns:
        match = re.search(pattern, text)
        if match:
            name = clean_recruiter_candidate_name(match.group("name"))
            if name:
                return name
    return ""


def clean_recruiter_candidate_name(value: str) -> str:
    text = re.sub(r"\s+", "", str(value or ""))
    text = text.strip("，,。.;；:：、!！?？'\"“”‘’（）()【】[]<>《》")
    text = re.sub(r"^(请|麻烦|帮我|帮忙|可以|能不能|再|把|再把|给|对|向|找|打开|联系|让|叫|候选人|牛人)+", "", text)
    text = re.sub(r"(候选人|牛人|这个人|那个人|这位|这名)$", "", text)
    text = re.sub(r"(标记为|设为|判为|点击|点)$", "", text)
    generic_terms = (
        "没有回", "没回", "未回复", "未读", "新消息", "待处理", "下一个",
        "未处理", "没处理", "待回复", "待沟通", "消息", "最近", "进行",
        "当前", "这个", "那个", "对方", "全部", "列表", "会话",
        "刚刚", "前三", "前两", "前二", "三个", "两个人", "三个人",
        "几个人", "几个", "一批", "批量", "条", "人",
    )
    if not text or any(term in text for term in generic_terms):
        return ""
    if len(text) < 2 or len(text) > 16:
        return ""
    return text


def extract_recruiter_request_candidate_name(message: str) -> str:
    names = extract_recruiter_request_candidate_names(message)
    if names:
        return names[0]
    text = re.sub(r"\s+", "", str(message or ""))
    if not text or not looks_like_recruiter_resume_request(text):
        return ""
    patterns = (
        r"(?:对|给|向|找|打开|联系|让|叫)(?P<name>[\u4e00-\u9fffA-Za-z0-9·._-]{2,16})(?:求简历|要简历|索要简历|发简历|发送简历|简历请求)",
        r"(?P<name>[\u4e00-\u9fffA-Za-z0-9·._-]{2,16})(?:求简历|要简历|索要简历|简历请求)",
        r"(?:求|要|索要)(?P<name>[\u4e00-\u9fffA-Za-z0-9·._-]{2,16})(?:的)?简历",
    )
    for pattern in patterns:
        match = re.search(pattern, text)
        if match:
            name = clean_recruiter_candidate_name(match.group("name"))
            if name:
                return name
    return ""


def extract_recruiter_candidate_names_from_text(value: str) -> list[str]:
    text = re.sub(r"\s+", "", str(value or ""))
    if not text:
        return []
    text = re.sub(r"^(请|麻烦|帮我|帮忙|可以|能不能|对|给|向|找|打开|联系|让|叫)+", "", text)
    text = re.sub(r"(求简历|要简历|索要简历|发简历|发送简历|简历请求|获取简历).*$", "", text)
    parts = re.split(r"[，,、/|；;]+|(?:和|及|以及|还有)", text)
    names: list[str] = []
    for part in parts:
        part = re.sub(r"的$", "", str(part or ""))
        name = clean_recruiter_candidate_name(part)
        if name and name not in names:
            names.append(name)
    return names


def extract_recruiter_request_candidate_names(message: str) -> list[str]:
    text = re.sub(r"\s+", "", str(message or ""))
    if not text or not looks_like_recruiter_resume_request(text):
        return []
    patterns = (
        r"(?:对|给|向|找|打开|联系|让|叫)(?P<names>[\u4e00-\u9fffA-Za-z0-9·._,，、/|；;和及以及还有-]{2,80}?)(?:求简历|要简历|索要简历|发简历|发送简历|简历请求|获取简历)",
        r"(?:求|要|索要)(?P<names>[\u4e00-\u9fffA-Za-z0-9·._,，、/|；;和及以及还有-]{2,80}?)(?:的)?简历",
    )
    for pattern in patterns:
        match = re.search(pattern, text)
        if not match:
            continue
        names = extract_recruiter_candidate_names_from_text(match.group("names"))
        if names:
            return names
    return []


def extract_recruiter_batch_count(message: str) -> int:
    text = re.sub(r"\s+", "", str(message or ""))
    if not text or not looks_like_recruiter_resume_request(text):
        return 1
    if re.search(r"(?:下一个|当前|这个|那个)", text) and not re.search(r"\d|[一二两三四五六七八九十]", text):
        return 1
    match = re.search(r"(?:前|先|连续|批量|处理|对)?(\d{1,2})(?:个|位|人|条)?", text)
    if match:
        value = int(match.group(1))
        return max(1, min(30, value))
    cn_map = {
        "一": 1,
        "二": 2,
        "两": 2,
        "三": 3,
        "四": 4,
        "五": 5,
        "六": 6,
        "七": 7,
        "八": 8,
        "九": 9,
        "十": 10,
    }
    match = re.search(r"(?:前|先|连续|批量|处理|对)?([一二两三四五六七八九十])(?:个|位|人|条)", text)
    if match:
        return cn_map.get(match.group(1), 1)
    return 1


def extract_recruiter_screen_batch_count(message: str) -> int:
    text = re.sub(r"\s+", "", str(message or ""))
    if not text:
        return 5
    if any(term in text for term in (
        "当前联系人", "当前候选人", "当前会话", "当前聊天框",
        "这个联系人", "这个候选人", "这个会话", "这个聊天框",
        "刚刚联系人", "刚刚的联系人", "刚才联系人", "刚才的联系人",
    )):
        return 1
    match = re.search(r"(\d{1,2})(?:个|人|条|位|份)?", text)
    if match:
        return max(1, min(30, int(match.group(1))))
    cn_values = {
        "一": 1,
        "二": 2,
        "两": 2,
        "三": 3,
        "四": 4,
        "五": 5,
        "六": 6,
        "七": 7,
        "八": 8,
        "九": 9,
        "十": 10,
        "十五": 15,
        "二十": 20,
    }
    for key, value in sorted(cn_values.items(), key=lambda item: len(item[0]), reverse=True):
        if key in text:
            return max(1, min(30, value))
    if any(term in text for term in ("所有", "全部", "all")):
        return 30
    return 5


def candidate_label_matches(label: str, candidate_name: str) -> bool:
    name = clean_recruiter_candidate_name(candidate_name)
    if not name:
        return False
    compact_label = re.sub(r"\s+", "", str(label or ""))
    compact_label = re.sub(r"^\d+", "", compact_label)
    compact_label = re.sub(r"^\d{1,2}:\d{2}", "", compact_label)
    return name in compact_label


def recruiter_candidate_name_key(value: str) -> str:
    name = clean_recruiter_candidate_name(value) or recruiter_candidate_name_from_label(value) or str(value or "")
    return re.sub(r"[^\u4e00-\u9fffA-Za-z0-9·._-]+", "", name).lower()


def recruiter_candidate_names_match(left: str, right: str) -> bool:
    left_key = recruiter_candidate_name_key(left)
    right_key = recruiter_candidate_name_key(right)
    if not left_key or not right_key:
        return False
    if left_key == right_key:
        return True
    return len(left_key) >= 2 and len(right_key) >= 2 and (left_key in right_key or right_key in left_key)


def clean_applied_position(value: str) -> str:
    text = re.sub(r"\s+", " ", str(value or "")).strip()
    text = text.strip("，,。.;；:：、|/\\-—_()（）[]【】")
    if not text:
        return ""
    blocked = {"全部职位", "职位", "岗位", "全部", "未读", "新招呼", "仅沟通", "更多"}
    if text in blocked:
        return ""
    text = re.split(r"\s+(?:您好|你好|BOSS|Boss|HR|Hr|[^\s]+\.pdf)\b", text, maxsplit=1)[0].strip()
    return safe_text(text, 80)


def normalize_candidate_label(label: str) -> str:
    value = re.sub(r"\s+", " ", str(label or "")).strip()
    value = re.sub(r"^\d{1,3}\s+(?=\S)", "", value)
    value = re.sub(r"^\d{1,2}:\d{2}\s*", "", value)
    return safe_text(value, 80)


def compact_conversation_label(label: str) -> str:
    value = re.sub(r"\s+", " ", str(label or "")).strip()
    value = re.sub(r"^\d{1,3}\s+(?=\S)", "", value)
    value = re.sub(r"^\d{1,2}:\d{2}\s*", "", value)
    value = re.sub(r"\s+", "", value)
    value = re.sub(r"(已读|未读|草稿|新消息|对方正在输入)", "", value)
    return value[:160]


def recruiter_candidate_name_from_label(label: str) -> str:
    normalized = normalize_candidate_label(label)
    if not normalized:
        return ""
    first = re.split(r"\s+", normalized, maxsplit=1)[0].strip()
    first = re.sub(r"^\d{1,3}", "", first)
    first = re.sub(r"^\d{1,2}:\d{2}", "", first)
    first = first.strip("：:，,。.;；-—()（）[]【】")
    if re.fullmatch(r"[\u4e00-\u9fffA-Za-z·._-]{2,16}", first or ""):
        if first not in {"AI应用开发实习生", "全部职位", "未读", "职位", "候选人"}:
            return first
    compact = compact_conversation_label(label)
    match = re.match(r"([\u4e00-\u9fffA-Za-z·]{2,8})", compact)
    if match:
        value = match.group(1)
        if value not in {"AI应用", "全部职位", "候选人"}:
            return value
    return ""


def build_recruiter_candidate_identity(
    context: dict | None,
    candidate_label: str = "",
    conversation_key: str = "",
) -> dict:
    context = context if isinstance(context, dict) else {}
    applicant = context.get("applicant") if isinstance(context.get("applicant"), dict) else {}
    platform = safe_text(str(context.get("platform") or applicant.get("platform") or ""), 30).strip()
    url = str(context.get("url") or "")
    if not platform:
        if "51job.com" in url:
            platform = "51job"
        elif "zhaopin.com" in url:
            platform = "zhilian"
        else:
            platform = "boss"
    label = safe_text(str(candidate_label or applicant.get("label") or ""), 220)
    name = safe_text(str(applicant.get("name") or recruiter_candidate_name_from_label(label)), 60)
    applied_position = safe_text(str(applicant.get("appliedPosition") or context.get("appliedPosition") or ""), 100)
    last_message = context.get("lastMessage") if isinstance(context.get("lastMessage"), dict) else {}
    last_other = context.get("lastOtherMessage") if isinstance(context.get("lastOtherMessage"), dict) else {}
    last_message_signature = chat_message_signature(last_message) if last_message else ""
    last_other_signature = chat_message_signature(last_other) if last_other else ""
    label_fingerprint = stable_digest(compact_conversation_label(label), 18) if label else ""
    recent_fingerprint = stable_digest(str(context.get("recentText") or "")[-600:], 18) if context.get("recentText") else ""
    source_parts = [
        platform,
        str(conversation_key or context.get("conversationKey") or ""),
        name,
        applied_position,
        label_fingerprint,
        last_message_signature,
        recent_fingerprint,
    ]
    identity_key = stable_digest("|".join(part for part in source_parts if part), 24)
    return {
        "platform": platform,
        "identityKey": identity_key,
        "conversationKey": safe_text(str(conversation_key or context.get("conversationKey") or ""), 80),
        "candidateName": name,
        "appliedPosition": applied_position,
        "listLabel": label,
        "labelFingerprint": label_fingerprint,
        "lastMessageSignature": last_message_signature,
        "lastOtherSignature": last_other_signature,
        "recentFingerprint": recent_fingerprint,
    }


def recruiter_basic_candidate_state_key(label: str, identity: dict | None = None) -> str:
    identity = identity if isinstance(identity, dict) else {}
    if identity.get("identityKey"):
        return "recruiter_basic_" + str(identity.get("identityKey"))
    compact = compact_conversation_label(label)
    if not compact:
        return ""
    name_match = re.match(r"([\u4e00-\u9fffA-Za-z·]{2,8})", compact)
    basis = f"{recruiter_candidate_name_from_label(label)}|{compact[:120]}"
    return "recruiter_basic_" + stable_digest(basis, 20)


def build_recruiter_watch_item(candidate_label: str, context: dict, identity: dict | None = None) -> dict:
    identity = identity if isinstance(identity, dict) else build_recruiter_candidate_identity(context, candidate_label)
    last_message = context.get("lastMessage") if isinstance(context.get("lastMessage"), dict) else {}
    last_other = context.get("lastOtherMessage") if isinstance(context.get("lastOtherMessage"), dict) else {}
    return {
        "candidateLabel": safe_text(str(candidate_label or identity.get("listLabel") or ""), 220),
        "candidateName": safe_text(str(identity.get("candidateName") or recruiter_candidate_name_from_label(candidate_label)), 60),
        "appliedPosition": safe_text(str(identity.get("appliedPosition") or context.get("appliedPosition") or ""), 100),
        "identityKey": safe_text(str(identity.get("identityKey") or ""), 80),
        "conversationKey": safe_text(str(identity.get("conversationKey") or context.get("conversationKey") or ""), 80),
        "candidateIdentity": identity,
        "compactLabel": compact_conversation_label(str(candidate_label or identity.get("listLabel") or "")),
        "lastMessageSignature": chat_message_signature(last_message) if last_message else "",
        "lastOtherSignature": chat_message_signature(last_other) if last_other else "",
        "lastSender": str(last_message.get("sender") or ""),
        "updatedAt": time.strftime("%Y-%m-%d %H:%M:%S"),
    }


def update_recruiter_watch_item_from_context(item: dict, context: dict, candidate_label: str = "") -> None:
    if not isinstance(item, dict):
        return
    identity = build_recruiter_candidate_identity(context, candidate_label or str(item.get("candidateLabel") or ""))
    last_message = context.get("lastMessage") if isinstance(context.get("lastMessage"), dict) else {}
    last_other = context.get("lastOtherMessage") if isinstance(context.get("lastOtherMessage"), dict) else {}
    if candidate_label:
        item["candidateLabel"] = safe_text(candidate_label, 220)
        item["compactLabel"] = compact_conversation_label(candidate_label)
    for key in ("candidateName", "appliedPosition", "identityKey", "conversationKey"):
        if identity.get(key):
            item[key] = safe_text(str(identity.get(key) or ""), 100)
    item["candidateIdentity"] = identity
    item["lastMessageSignature"] = chat_message_signature(last_message) if last_message else str(item.get("lastMessageSignature") or "")
    item["lastOtherSignature"] = chat_message_signature(last_other) if last_other else str(item.get("lastOtherSignature") or "")
    item["lastSender"] = str(last_message.get("sender") or item.get("lastSender") or "")
    item["updatedAt"] = time.strftime("%Y-%m-%d %H:%M:%S")


def recruiter_watch_items_same(left: dict, right: dict) -> bool:
    if not isinstance(left, dict) or not isinstance(right, dict):
        return False
    for key in ("identityKey", "conversationKey"):
        if left.get(key) and right.get(key) and left.get(key) == right.get(key):
            return True
    left_name = str(left.get("candidateName") or "")
    right_name = str(right.get("candidateName") or "")
    left_position = str(left.get("appliedPosition") or "")
    right_position = str(right.get("appliedPosition") or "")
    if left_name and right_name and left_name == right_name and (not left_position or not right_position or left_position == right_position):
        return True
    left_label = str(left.get("compactLabel") or compact_conversation_label(str(left.get("candidateLabel") or "")))
    right_label = str(right.get("compactLabel") or compact_conversation_label(str(right.get("candidateLabel") or "")))
    return bool(left_label and right_label and (left_label in right_label or right_label in left_label))


def recruiter_watch_item_matches_label(item: dict, label: str, context: dict | None = None) -> bool:
    if not isinstance(item, dict):
        return False
    compact_label = compact_conversation_label(label)
    item_label = str(item.get("compactLabel") or compact_conversation_label(str(item.get("candidateLabel") or "")))
    if compact_label and item_label and (compact_label in item_label or item_label in compact_label):
        return True
    name = str(item.get("candidateName") or "")
    position = str(item.get("appliedPosition") or "")
    if name and name in compact_label:
        if not position or position in compact_label:
            return True
        return True
    if context:
        applicant = context.get("applicant") if isinstance(context.get("applicant"), dict) else {}
        current_name = str(applicant.get("name") or recruiter_candidate_name_from_label(str(label or "")))
        current_position = str(applicant.get("appliedPosition") or context.get("appliedPosition") or "")
        if name and current_name and name == current_name:
            return not position or not current_position or position == current_position
    return False


def find_matching_recruiter_watch_item(
    watch_items: list[dict],
    label: str,
    context: dict | None = None,
) -> dict | None:
    for item in watch_items:
        if recruiter_watch_item_matches_label(item, label, context=context):
            return item
    if context:
        identity = build_recruiter_candidate_identity(context, label)
        candidate = build_recruiter_watch_item(label, context, identity)
        for item in watch_items:
            if recruiter_watch_items_same(item, candidate):
                return item
    return None


def compact_recruiter_resume_result(resume: dict | None) -> dict:
    if not isinstance(resume, dict):
        return {}

    def compact_scan(scan: dict | None) -> dict:
        if not isinstance(scan, dict):
            return {}
        return {
            "found": bool(scan.get("found")),
            "reason": safe_text(str(scan.get("reason") or ""), 80),
            "candidate": scan.get("candidate") if isinstance(scan.get("candidate"), dict) else {},
            "candidates": scan.get("candidates")[:5] if isinstance(scan.get("candidates"), list) else [],
        }

    def compact_step(step: dict | None) -> dict:
        if not isinstance(step, dict):
            return {}
        out = {
            "ok": step.get("ok"),
            "blocked": step.get("blocked"),
            "reason": safe_text(str(step.get("reason") or ""), 100),
            "message": safe_text(str(step.get("message") or ""), 220),
            "downloaded": step.get("downloaded"),
            "skipped": step.get("skipped"),
            "skipReason": safe_text(str(step.get("skipReason") or ""), 80),
            "filename": safe_text(str(step.get("filename") or ""), 180),
            "filePath": safe_text(str(step.get("filePath") or ""), 260),
            "downloadMethod": safe_text(str(step.get("downloadMethod") or ""), 100),
        }
        if isinstance(step.get("scan"), dict):
            out["scan"] = compact_scan(step.get("scan"))
        if isinstance(step.get("openResult"), dict):
            out["openResult"] = {
                k: v for k, v in step.get("openResult", {}).items()
                if k not in {"page", "originPage"}
            }
        if isinstance(step.get("saveResult"), dict):
            out["saveResult"] = {
                k: v for k, v in step.get("saveResult", {}).items()
                if k != "download"
            }
        return out

    return {
        "action": safe_text(str(resume.get("action") or ""), 100),
        "message": safe_text(str(resume.get("message") or ""), 260),
        "blocked": resume.get("blocked"),
        "downloaded": resume.get("downloaded"),
        "download": compact_step(resume.get("download") if isinstance(resume.get("download"), dict) else {}),
        "request": compact_step(resume.get("request") if isinstance(resume.get("request"), dict) else {}),
    }


def classify_recruiter_screen_result_action(result: dict) -> str:
    screening = result.get("screening") if isinstance(result.get("screening"), dict) else {}
    status = str(screening.get("status") or "")
    if result.get("blocked"):
        return "blocked"
    resume = result.get("resume") if isinstance(result.get("resume"), dict) else {}
    resume_skipped = bool(resume.get("skipped") and resume.get("skipReason") in {"already_requested", "resume_attachment_received"})
    resume_downloaded = bool(result.get("downloaded") or resume.get("downloaded"))
    if resume_downloaded and result.get("knowledgeAnswer"):
        return "knowledge_answered_resume_downloaded"
    if resume_downloaded:
        return "accepted_resume_downloaded"
    if resume_skipped and result.get("knowledgeAnswer"):
        return "knowledge_answered_resume_already_requested"
    if resume_skipped:
        return "accepted_resume_already_requested"
    if result.get("resume") and result.get("knowledgeAnswer"):
        return "knowledge_answered_and_requested_resume"
    if result.get("resume"):
        return "accepted_requested_resume"
    if result.get("sent") and result.get("knowledgeAnswer"):
        return "knowledge_answered_and_sent_screening"
    if result.get("knowledgeAnswer"):
        return "knowledge_answered"
    if result.get("sent"):
        if result.get("positionScreening"):
            return "sent_position_screening"
        return "sent_basic_conditions"
    if result.get("shouldMarkUnsuitable") or status == "reject":
        return "rejected_skipped"
    if status in {"waiting", "unclear"}:
        return "unclear_or_waiting_skipped"
    return "checked"


def opened_thread_matches_context(opened: dict | None, context: dict | None) -> dict:
    if not isinstance(opened, dict) or not isinstance(context, dict):
        return {"matched": False, "reason": "missing_context"}
    applicant = context.get("applicant") if isinstance(context.get("applicant"), dict) else {}
    opened_label = compact_conversation_label(str(opened.get("label") or ""))
    current_label = compact_conversation_label(str(applicant.get("label") or ""))
    current_name = compact_conversation_label(str(applicant.get("name") or ""))
    current_position = compact_conversation_label(str(applicant.get("appliedPosition") or ""))
    opened_y = opened.get("y")
    current_y = applicant.get("y")

    if current_name and current_name in opened_label:
        return {"matched": True, "reason": "candidate_name", "name": current_name}
    if current_label and opened_label:
        if current_label[:40] in opened_label or opened_label[:40] in current_label:
            return {"matched": True, "reason": "selected_row_label"}
        if len(current_label) >= 20 and len(opened_label) >= 20:
            overlap = len(set(current_label) & set(opened_label))
            if overlap >= min(18, max(8, len(set(opened_label)) // 2)):
                return {"matched": True, "reason": "selected_row_overlap"}
    if current_position and opened_label and current_position in opened_label:
        return {"matched": True, "reason": "position"}
    if isinstance(opened_y, (int, float)) and isinstance(current_y, (int, float)):
        if abs(float(opened_y) - float(current_y)) <= 24:
            return {"matched": True, "reason": "same_row_y"}

    # Some chat UIs do not expose a selected row after clicking. In that case we
    # accept only the unread-filter fallback, because the list itself was already
    # narrowed to unread conversations before the click.
    if not current_label and str(opened.get("reason") or "") == "unread-filter-first-row":
        return {"matched": True, "reason": "unread_filter_fallback"}

    return {
        "matched": False,
        "reason": "opened_target_did_not_match_selected_row",
        "openedLabel": safe_text(opened_label, 80),
        "currentLabel": safe_text(current_label, 80),
        "currentName": safe_text(current_name, 40),
    }


def extract_windows_path(message: str) -> str | None:
    match = re.search(r"[A-Za-z]:\\[^\n\r\"'<>|]+", message)
    if not match:
        return None
    return match.group(0).strip().rstrip("。；;，,")


def contains_windows_path(message: str) -> bool:
    return bool(re.search(r"[A-Za-z]:\\", message))


def chat_context_signature(text: str) -> str:
    compact = re.sub(r"\s+", " ", str(text or "")).strip()
    return str(hash(compact[-1000:])) if compact else ""


def stable_digest(text: str, length: int = 16) -> str:
    value = str(text or "").encode("utf-8", errors="ignore")
    return hashlib.sha1(value).hexdigest()[:length]


def chat_message_signature(message: dict | None) -> str:
    if not isinstance(message, dict):
        return ""
    text = re.sub(r"\s+", " ", str(message.get("text") or "")).strip()
    sender = str(message.get("sender") or "")
    when = str(message.get("time") or "")
    return stable_digest(f"{sender}|{when}|{text[-220:]}")


def last_effective_chat_message(messages: list[dict], sender: str | None = None) -> dict:
    if not isinstance(messages, list):
        return {}
    ignored = {"已读", "送达", "未读", "对方正在输入", "按enter键发送", "按ctrl+enter键换行发送"}
    for item in reversed(messages):
        if not isinstance(item, dict):
            continue
        if sender and item.get("sender") != sender:
            continue
        text = re.sub(r"\s+", "", str(item.get("text") or "")).lower()
        if not text or text in ignored:
            continue
        return item
    return {}


def build_conversation_key(url: str, messages: list[dict], opened_label: str | None = None) -> str:
    label = re.sub(r"\s+", " ", str(opened_label or "")).strip()
    if not label and messages:
        first_other = next((item for item in messages if isinstance(item, dict) and item.get("sender") == "other"), None)
        if first_other:
            label = str(first_other.get("text") or "")
    last_other = last_effective_chat_message(messages, sender="other")
    basis = "|".join([
        urlparse(str(url or "")).netloc,
        urlparse(str(url or "")).path,
        label[:120],
        str(last_other.get("text") or "")[:80],
    ])
    return "chat_" + stable_digest(basis, 20)


def infer_counterpart_profile(context: dict, opened_label: str | None = None) -> dict:
    applicant = context.get("applicant") if isinstance(context.get("applicant"), dict) else {}
    if applicant.get("name") or applicant.get("appliedPosition"):
        return {
            "name": safe_text(str(applicant.get("name") or ""), 40),
            "organization": "",
            "role": safe_text(str(applicant.get("appliedPosition") or context.get("appliedPosition") or ""), 80),
            "appliedPosition": safe_text(str(applicant.get("appliedPosition") or context.get("appliedPosition") or ""), 80),
            "rawHeader": safe_text(str(applicant.get("label") or ""), 260),
        }

    detail = context.get("chatDetailSource") if isinstance(context.get("chatDetailSource"), dict) else {}
    header_source = " ".join([
        str(opened_label or ""),
        str(detail.get("text") or ""),
        str(context.get("pageTextPreview") or ""),
    ])
    header = safe_text(re.sub(r"\s+", " ", header_source).strip(), 260)
    before_more = header.split(" 更多 ", 1)[0].strip()
    tokens = [part for part in before_more.split(" ") if part and part not in {"已读", "送达", "草稿"}]
    profile = {
        "name": "",
        "organization": "",
        "role": "",
        "appliedPosition": safe_text(str(context.get("appliedPosition") or ""), 80),
        "rawHeader": header,
    }
    if tokens:
        profile["name"] = safe_text(tokens[0], 40)
    if len(tokens) >= 2:
        profile["organization"] = safe_text(tokens[1], 60)
    if len(tokens) >= 3:
        profile["role"] = safe_text(tokens[2], 60)
    return profile


def build_reply_style(memory: dict, intent_stats: dict, profile: dict) -> dict:
    role_text = f"{profile.get('role', '')} {profile.get('organization', '')}".lower()
    category_rank = sorted(intent_stats.items(), key=lambda item: int(item[1] or 0), reverse=True)
    top_categories = [name for name, count in category_rank[:4] if count]
    tone = "以招聘者身份沟通，礼貌、简短、自然；先回应候选人，再根据岗位推进筛选或邀约。"
    if "hr" in role_text or "人力" in role_text or "招聘" in role_text:
        tone = "面向招聘方，礼貌稳妥、信息密度高，不绕圈。"
    if "resume_request" in top_categories:
        tone += " 对方常要简历，优先确认可发简历或说明附件状态。"
    if "contact_exchange" in top_categories:
        tone += " 涉及电话/微信时谨慎，不编造不存在的联系方式。"
    if "education_grade" in top_categories or "identity_question" in top_categories:
        tone += " 对方会核实身份/学历/状态，先直接说明真实身份信息。"
    return {
        "persona": "招聘者沟通助手",
        "tone": tone,
        "replyLength": "10-20 个中文字符优先，最多 20 个中文字符",
        "do": [
            "按对方最近问题直接回答",
            "保持礼貌自然",
            "缺少真实资料时说明可补充，不写占位符",
        ],
        "dont": [
            "不要编造学校、年龄、工作年限、联系方式",
            "不要连续追问或重复上一轮已经发过的话",
            "不要长段落输出",
        ],
    }


def build_chat_memory(previous: dict, context: dict, opened_label: str | None = None) -> dict:
    messages = context.get("messages") if isinstance(context.get("messages"), list) else []
    counterpart = infer_counterpart_profile(context, opened_label=opened_label)
    applied_position = safe_text(str(context.get("appliedPosition") or counterpart.get("appliedPosition") or ""), 80)
    intent_stats: dict[str, int] = {}
    other_questions: list[str] = []
    me_points: list[str] = []
    recent_messages: list[dict] = []
    for message in messages[-80:]:
        if not isinstance(message, dict):
            continue
        text = safe_text(str(message.get("text") or "").strip(), 500)
        if not text:
            continue
        sender = str(message.get("sender") or "")
        recent_messages.append({
            "sender": sender if sender in {"me", "other"} else "unknown",
            "text": text,
            "time": safe_text(str(message.get("time") or message.get("timestamp") or ""), 40),
            "status": safe_text(str(message.get("status") or ""), 30),
        })
        if sender == "other":
            intent = classify_chat_intent(text)
            category = str(intent.get("category") or "unknown")
            intent_stats[category] = int(intent_stats.get(category) or 0) + 1
            if text not in other_questions:
                other_questions.append(text)
        elif sender == "me":
            if text not in me_points:
                me_points.append(text)

    other_questions = other_questions[-10:]
    me_points = me_points[-6:]
    top_intents = [
        name for name, count in sorted(intent_stats.items(), key=lambda item: int(item[1] or 0), reverse=True)
        if count and name != "unknown"
    ][:5]
    focus_map = {
        "identity_question": "身份确认",
        "education_grade": "学历/年级/毕业状态",
        "resume_request": "简历材料",
        "contact_exchange": "联系方式交换",
        "interview_schedule": "面试安排",
        "salary_expectation": "薪资期望",
        "job_interest": "岗位匹配",
        "greeting": "日常招呼",
    }
    focus = [focus_map.get(name, name) for name in top_intents]
    summary_parts = []
    if counterpart.get("name") or counterpart.get("organization") or counterpart.get("role"):
        summary_parts.append(
            "对方"
            f"{counterpart.get('name') or '未知'}"
            f"（{counterpart.get('organization') or '未知公司'} / {counterpart.get('role') or '未知角色'}）"
        )
    if focus:
        summary_parts.append("主要关注：" + "、".join(focus[:4]))
    if applied_position:
        summary_parts.append(f"应聘岗位：{applied_position}")
    if other_questions:
        summary_parts.append("最近问过：" + "；".join(other_questions[-4:]))
    if me_points:
        summary_parts.append("我方最近回应：" + "；".join(me_points[-2:]))
    summary = safe_text("。".join(summary_parts) or str(previous.get("summary") or ""), 900)
    last_message = context.get("lastMessage") if isinstance(context.get("lastMessage"), dict) else {}
    last_other = context.get("lastOtherMessage") if isinstance(context.get("lastOtherMessage"), dict) else {}
    return {
        "summary": summary,
        "counterpart": counterpart,
        "appliedPosition": applied_position,
        "positionReply": context.get("positionReply") if isinstance(context.get("positionReply"), dict) else {},
        "recentMessages": recent_messages[-80:],
        "recentOtherMessages": other_questions,
        "recentMyMessages": me_points,
        "intentStats": intent_stats,
        "replyStyle": build_reply_style(previous, intent_stats, counterpart),
        "lastMessageSignature": chat_message_signature(last_message) if last_message else "",
        "lastOtherSignature": chat_message_signature(last_other) if last_other else "",
    }


def compact_chat_memory(memory: dict) -> dict:
    if not isinstance(memory, dict):
        return {}
    return {
        "summary": safe_text(str(memory.get("summary") or ""), 700),
        "counterpart": memory.get("counterpart") if isinstance(memory.get("counterpart"), dict) else {},
        "appliedPosition": safe_text(str(memory.get("appliedPosition") or ""), 80),
        "positionReply": memory.get("positionReply") if isinstance(memory.get("positionReply"), dict) else {},
        "recentMessages": list(memory.get("recentMessages") or [])[-60:],
        "recentOtherMessages": list(memory.get("recentOtherMessages") or [])[-6:],
        "recentMyMessages": list(memory.get("recentMyMessages") or [])[-6:],
        "intentStats": memory.get("intentStats") if isinstance(memory.get("intentStats"), dict) else {},
        "replyStyle": memory.get("replyStyle") if isinstance(memory.get("replyStyle"), dict) else {},
        "lastOtherSignature": str(memory.get("lastOtherSignature") or ""),
        "updatedAt": str(memory.get("updatedAt") or ""),
    }


def compact_candidate_conversation_review(review: dict) -> dict:
    if not isinstance(review, dict):
        return {}
    unanswered = review.get("unansweredQuestions") if isinstance(review.get("unansweredQuestions"), list) else []
    answered = review.get("answeredQuestions") if isinstance(review.get("answeredQuestions"), list) else []
    actions = review.get("actionsDone") if isinstance(review.get("actionsDone"), list) else []
    return {
        "modelEnabled": bool(review.get("modelEnabled")),
        "acceptanceStatus": safe_text(str(review.get("acceptanceStatus") or ""), 40),
        "recommendedNextAction": safe_text(str(review.get("recommendedNextAction") or ""), 60),
        "pendingReplyNeeded": bool(review.get("pendingReplyNeeded")),
        "shouldRequestResume": bool(review.get("shouldRequestResume")),
        "shouldSkip": bool(review.get("shouldSkip")),
        "summary": safe_text(str(review.get("summary") or ""), 500),
        "unansweredQuestions": [
            {
                "text": safe_text(str(item.get("text") or item.get("question") or ""), 180),
                "topic": safe_text(str(item.get("topic") or item.get("topicHint") or ""), 60),
                "messageIndex": item.get("messageIndex"),
                "sourceText": safe_text(str(item.get("sourceText") or ""), 180),
                "reason": safe_text(str(item.get("reason") or ""), 120),
            }
            for item in unanswered[:RECENT_UNANSWERED_OTHER_LIMIT]
            if isinstance(item, dict)
        ],
        "answeredQuestions": [
            {
                "text": safe_text(str(item.get("text") or item.get("question") or ""), 180),
                "answer": safe_text(str(item.get("answer") or ""), 120),
                "topic": safe_text(str(item.get("topic") or item.get("topicHint") or ""), 60),
            }
            for item in answered[:8]
            if isinstance(item, dict)
        ],
        "actionsDone": [safe_text(str(item), 80) for item in actions[:12]],
    }


def classify_chat_intent(text: str) -> dict:
    raw = str(text or "").strip()
    lowered = raw.lower()
    compact = re.sub(r"\s+", "", raw)
    category = "unknown"
    risk = "normal"
    confidence = 0.35
    reply_hint = "自然简短回复，必要时先确认信息。"

    checks = [
        ("contact_exchange", ("微信", "vx", "wechat", "电话", "手机号", "联系方式", "加我", "交换"), "对方想交换联系方式。", "sensitive"),
        ("identity_question", ("你是谁", "哪位", "您是", "谁啊", "哪一个"), "对方在确认身份。", "normal"),
        ("education_grade", ("大几", "几年级", "在读", "应届", "毕业", "学生", "学校"), "对方在问学历/年级/毕业状态。", "normal"),
        ("resume_request", ("简历", "发一下", "发我", "附件", "pdf", "资料"), "对方想要简历或资料。", "sensitive"),
        ("interview_schedule", ("面试", "约", "时间", "方便", "几点", "明天", "今天", "周", "到岗"), "对方在沟通面试或时间安排。", "normal"),
        ("salary_expectation", ("薪资", "薪水", "工资", "期望", "待遇", "多少钱"), "对方在问薪资期望。", "sensitive"),
        ("job_interest", ("岗位", "职位", "工作内容", "技术栈", "职责", "base", "地点"), "对方在沟通岗位信息。", "normal"),
        ("greeting", ("你好", "您好", "在吗", "哈喽", "hello", "hi"), "对方在打招呼。", "normal"),
        ("rejection_or_close", ("不合适", "暂不", "不用", "谢谢", "不考虑"), "对方可能在结束沟通。", "normal"),
    ]
    for name, words, hint, item_risk in checks:
        if any(word in compact or word in lowered for word in words):
            category = name
            risk = item_risk
            confidence = 0.82
            reply_hint = hint
            break

    return {
        "category": category,
        "risk": risk,
        "confidence": confidence,
        "replyHint": reply_hint,
        "sourceText": safe_text(raw, 160),
    }


def is_auto_reply_command(message: str) -> bool:
    text = str(message or "").lower()
    compact = re.sub(r"\s+", "", text)
    direct_terms = [
        "回复未读",
        "处理未读",
        "回未读",
        "未读消息回复",
        "回复新消息",
        "处理新消息",
        "帮我回未读",
        "帮我回复未读",
        "打开未读并回复",
    ]
    if any(term in compact for term in direct_terms):
        return True
    signal_terms = [
        "\u68c0\u6d4b\u5230\u65b0\u6d88\u606f",  # 检测到新消息
        "\u65b0\u6d88\u606f",  # 新消息
        "\u81ea\u52a8\u68c0\u67e5",  # 自动检查
        "\u672a\u8bfb",  # 未读
        "\u672a\u8bfb\u6d88\u606f",  # 未读消息
        "\u672a\u56de\u590d",  # 未回复
        "\u6ca1\u6709\u56de\u590d",  # 没有回复
        "\u5f85\u56de\u590d",  # 待回复
    ]
    reply_terms = [
        "\u56de\u590d",  # 回复
        "\u5904\u7406",  # 处理
        "\u81ea\u52a8\u751f\u6210\u56de\u590d",  # 自动生成回复
        "\u81ea\u52a8\u56de\u590d",  # 自动回复
        "\u56de\u590d\u6d88\u606f",  # 回复消息
        "\u70b9\u8fdb\u53bb\u8fdb\u884c\u56de\u590d",  # 点进去进行回复
        "\u5e2e\u6211\u56de\u590d",  # 帮我回复
        "auto reply",
    ]
    return any(term in text for term in signal_terms) and any(term in text for term in reply_terms)


def is_local_browser_page(terminal: BrowserTerminal) -> bool:
    try:
        parsed = urlparse(terminal.current_page().url)
        return parsed.hostname in {"127.0.0.1", "localhost", "::1"}
    except Exception:
        return False


def move_cursor_like_person(
    terminal: BrowserTerminal,
    x: float,
    y: float,
    duration_factor: float = 1.0,
    show_trail: bool = True,
) -> None:
    page = terminal.current_page()
    viewport = page.viewport_size or {"width": 1280, "height": 720}
    x = clamp(float(x), 8, max(8, float(viewport.get("width", 1280)) - 8))
    y = clamp(float(y), 8, max(8, float(viewport.get("height", 720)) - 8))
    try:
        if terminal.visual_cursor:
            ensure_visual_cursor(page)
            path = build_bezier_cursor_path(
                page,
                x,
                y,
                terminal.move_duration_factor() * duration_factor,
                allow_overshoot=False,
            )
            if show_trail:
                draw_visual_trail(page, path, visible=True)
            terminal.follow_cursor_path(page, path)
            if show_trail:
                page.wait_for_timeout(random.randint(35, 90))
                draw_visual_trail(page, [], visible=False)
        else:
            page.mouse.move(x, y, steps=random.randint(8, 18))
            page.evaluate("""pos => { window.__codexCursorPos = pos; }""", {"x": x, "y": y})
    except Exception:
        page.mouse.move(x, y, steps=random.randint(4, 10))


def humanized_point_click(terminal: BrowserTerminal, x: float, y: float, target_box: dict | None = None) -> None:
    page = terminal.current_page()
    viewport = page.viewport_size or {"width": 1280, "height": 720}
    x = clamp(float(x), 8, max(8, float(viewport.get("width", 1280)) - 8))
    y = clamp(float(y), 8, max(8, float(viewport.get("height", 720)) - 8))
    if terminal.visual_cursor:
        ensure_visual_cursor(page)
        path = build_bezier_cursor_path(
            page,
            x,
            y,
            terminal.move_duration_factor(),
            target_box=target_box,
            allow_overshoot=True,
        )
        draw_visual_trail(page, path, visible=True)
        terminal.follow_cursor_path(page, path)
        move_visual_cursor(page, x, y, click=True)
        page.wait_for_timeout(random.randint(35, 95))
        page.mouse.click(x, y)
        page.wait_for_timeout(random.randint(80, 170))
        draw_visual_trail(page, [], visible=False)
    else:
        page.mouse.move(x, y, steps=random.randint(10, 22))
        page.wait_for_timeout(random.randint(65, 180))
        page.mouse.click(x, y)
    try:
        page.evaluate("""pos => { window.__codexCursorPos = pos; }""", {"x": float(x), "y": float(y)})
    except Exception:
        pass
    maybe_post_click_settle(terminal, x, y)
    maybe_human_work_rest(terminal)


def target_box_inner_point(box: dict) -> tuple[float, float]:
    width = max(1.0, float(box.get("width") or 1))
    height = max(1.0, float(box.get("height") or 1))
    pad_x = min(width * 0.32, max(3.0, width * 0.16))
    pad_y = min(height * 0.32, max(3.0, height * 0.16))
    left = float(box.get("x") or 0) + pad_x
    right = float(box.get("x") or 0) + width - pad_x
    top = float(box.get("y") or 0) + pad_y
    bottom = float(box.get("y") or 0) + height - pad_y
    if right <= left:
        left = float(box.get("x") or 0) + width * 0.42
        right = float(box.get("x") or 0) + width * 0.58
    if bottom <= top:
        top = float(box.get("y") or 0) + height * 0.42
        bottom = float(box.get("y") or 0) + height * 0.58
    return random.uniform(left, right), random.uniform(top, bottom)


def humanized_button_hover_jitter(terminal: BrowserTerminal, box: dict) -> tuple[float, float]:
    page = terminal.current_page()
    final_x, final_y = target_box_inner_point(box)
    if not terminal.humanize:
        return final_x, final_y
    moves = 1 if random.random() < 0.55 else 0
    for _ in range(moves):
        x, y = target_box_inner_point(box)
        try:
            if terminal.visual_cursor:
                move_cursor_like_person(terminal, x, y, duration_factor=random.uniform(0.18, 0.36), show_trail=False)
                move_visual_cursor(page, x, y, click=False)
            else:
                page.mouse.move(x, y, steps=random.randint(2, 6))
            page.evaluate("""pos => { window.__codexCursorPos = pos; }""", {"x": float(x), "y": float(y)})
            page.wait_for_timeout(random.randint(55, 190))
        except Exception:
            break
    return final_x, final_y


def maybe_human_work_rest(terminal: BrowserTerminal) -> None:
    if not getattr(terminal, "humanize", False):
        return
    count = int(getattr(terminal, "_codex_human_work_count", 0)) + 1
    next_after = int(getattr(terminal, "_codex_human_next_rest_after", 0) or random.randint(7, 12))
    setattr(terminal, "_codex_human_work_count", count)
    if count < next_after:
        return
    setattr(terminal, "_codex_human_work_count", 0)
    setattr(terminal, "_codex_human_next_rest_after", random.randint(6, 11))
    page = terminal.current_page()
    rest_ms = random.randint(8500, 12500)
    try:
        if random.random() < 0.45:
            jitter_mouse(page)
        page.wait_for_timeout(rest_ms)
        if random.random() < 0.55:
            jitter_mouse(page)
    except Exception:
        try:
            page.wait_for_timeout(rest_ms)
        except Exception:
            pass


def maybe_post_click_settle(terminal: BrowserTerminal, x: float, y: float) -> None:
    if not getattr(terminal, "humanize", False) or random.random() > 0.48:
        return
    page = terminal.current_page()
    viewport = page.viewport_size or {"width": 1280, "height": 720}
    try:
        dx = random.choice([-1, 1]) * random.uniform(8, 24)
        dy = random.choice([-1, 1]) * random.uniform(5, 18)
        nx = clamp(float(x) + dx, 12, float(viewport.get("width", 1280)) - 12)
        ny = clamp(float(y) + dy, 12, float(viewport.get("height", 720)) - 12)
        if terminal.visual_cursor:
            move_cursor_like_person(terminal, nx, ny, duration_factor=random.uniform(0.12, 0.28), show_trail=False)
            move_visual_cursor(page, nx, ny, click=False)
        else:
            page.mouse.move(nx, ny, steps=random.randint(2, 5))
        page.evaluate("""pos => { window.__codexCursorPos = pos; }""", {"x": float(nx), "y": float(ny)})
        page.wait_for_timeout(random.randint(70, 240))
    except Exception:
        return


def maybe_human_reading_pause(terminal: BrowserTerminal, reason: str = "", text_hint: str = "") -> None:
    if not getattr(terminal, "humanize", False):
        return
    chance = 0.38
    if reason in {"candidate_open", "page_change", "before_decision"}:
        chance = 0.68
    if random.random() > chance:
        return
    page = terminal.current_page()
    viewport = page.viewport_size or {"width": 1280, "height": 720}
    text_len = min(900, len(str(text_hint or "")))
    pause_ms = random.randint(360, 1050) + int(text_len * random.uniform(0.35, 0.9))
    pause_ms = min(2400, pause_ms)
    try:
        if random.random() < 0.55:
            x = float(viewport.get("width", 1280)) * random.uniform(0.58, 0.78)
            y = float(viewport.get("height", 720)) * random.uniform(0.36, 0.68)
            move_cursor_like_person(terminal, x, y, duration_factor=random.uniform(0.28, 0.55), show_trail=False)
        page.wait_for_timeout(pause_ms)
        if random.random() < 0.25:
            jitter_mouse(page)
    except Exception:
        try:
            page.wait_for_timeout(pause_ms)
        except Exception:
            pass


def maybe_human_batch_pause(terminal: BrowserTerminal, index: int) -> None:
    if not getattr(terminal, "humanize", False) or index <= 0:
        return
    if index % random.randint(3, 5) != 0:
        return
    page = terminal.current_page()
    pause_ms = random.randint(1300, 3600)
    if random.random() < 0.18:
        pause_ms += random.randint(3500, 6500)
    try:
        if random.random() < 0.45:
            small_scroll_wander(terminal)
        else:
            jitter_mouse(page)
        page.wait_for_timeout(pause_ms)
    except Exception:
        try:
            page.wait_for_timeout(pause_ms)
        except Exception:
            pass


def maybe_human_proactive_contact_pause(terminal: BrowserTerminal, index: int) -> None:
    if not getattr(terminal, "humanize", False) or index <= 0:
        return
    page = terminal.current_page()
    since_rest = int(getattr(terminal, "_codex_proactive_contacts_since_rest", 0)) + 1
    next_after = int(getattr(terminal, "_codex_proactive_next_rest_after", 0) or random.randint(4, 7))
    setattr(terminal, "_codex_proactive_contacts_since_rest", since_rest)
    setattr(terminal, "_codex_proactive_next_rest_after", next_after)

    pause_ms = random.randint(950, 1900)
    if random.random() < 0.36:
        pause_ms += random.randint(600, 1600)
    should_rest = since_rest >= next_after
    if should_rest:
        pause_ms += random.randint(5200, 9200)
        setattr(terminal, "_codex_proactive_contacts_since_rest", 0)
        setattr(terminal, "_codex_proactive_next_rest_after", random.randint(4, 7))

    try:
        if random.random() < (0.52 if should_rest else 0.28):
            jitter_mouse(page)
        if random.random() < (0.42 if should_rest else 0.18):
            small_scroll_wander(terminal)
        page.wait_for_timeout(pause_ms)
    except Exception:
        try:
            page.wait_for_timeout(pause_ms)
        except Exception:
            pass


def maybe_human_resume_request_pause(terminal: BrowserTerminal) -> None:
    if not getattr(terminal, "humanize", False):
        return
    since_rest = int(getattr(terminal, "_codex_resume_requests_since_rest", 0)) + 1
    next_after = int(getattr(terminal, "_codex_resume_next_rest_after", 0) or random.randint(3, 6))
    setattr(terminal, "_codex_resume_requests_since_rest", since_rest)
    setattr(terminal, "_codex_resume_next_rest_after", next_after)
    if since_rest < next_after:
        return

    page = terminal.current_page()
    rest_ms = random.randint(8500, 12500)
    setattr(terminal, "_codex_resume_requests_since_rest", 0)
    setattr(terminal, "_codex_resume_next_rest_after", random.randint(3, 6))
    try:
        if random.random() < 0.58:
            jitter_mouse(page)
        if random.random() < 0.38:
            small_scroll_wander(terminal)
        page.wait_for_timeout(rest_ms)
        if random.random() < 0.45:
            jitter_mouse(page)
    except Exception:
        try:
            page.wait_for_timeout(rest_ms)
        except Exception:
            pass


def humanized_locator_click(terminal: BrowserTerminal, locator, *, force: bool = False) -> None:
    page = terminal.current_page()
    try:
        locator.scroll_into_view_if_needed(timeout=3500)
    except Exception:
        pass
    try:
        box = locator.bounding_box(timeout=3000)
    except Exception:
        box = None
    if box:
        x, y = humanized_button_hover_jitter(terminal, box)
        humanized_point_click(terminal, x, y, target_box=box)
        return
    try:
        if force:
            locator.click(timeout=8000, force=True)
        else:
            locator.click(timeout=8000)
    except Exception as error:
        msg = str(error).lower()
        if force or "not visible" in msg or "element is not visible" in msg or "obscured" in msg:
            locator.click(timeout=8000, force=True)
        else:
            raise


def humanized_precise_button_click(terminal: BrowserTerminal, locator, *, force: bool = False) -> None:
    page = terminal.current_page()
    try:
        locator.scroll_into_view_if_needed(timeout=3500)
    except Exception:
        pass
    try:
        box = locator.bounding_box(timeout=3000)
    except Exception:
        box = None
    if not box:
        if force:
            locator.click(timeout=8000, force=True)
        else:
            locator.click(timeout=8000)
        return

    x = float(box["x"] + box["width"] * random.uniform(0.46, 0.54))
    y = float(box["y"] + box["height"] * random.uniform(0.42, 0.58))
    if terminal.visual_cursor:
        ensure_visual_cursor(page)
        path = build_bezier_cursor_path(
            page,
            x,
            y,
            terminal.move_duration_factor() * 0.86,
            target_box=box,
            allow_overshoot=False,
        )
        draw_visual_trail(page, path, visible=True)
        terminal.follow_cursor_path(page, path)
        move_visual_cursor(page, x, y, click=True)
        page.wait_for_timeout(random.randint(35, 85))
        page.mouse.click(x, y)
        page.wait_for_timeout(random.randint(90, 170))
        draw_visual_trail(page, [], visible=False)
    else:
        page.mouse.move(x, y, steps=random.randint(8, 18))
        page.wait_for_timeout(random.randint(50, 120))
        page.mouse.click(x, y)
    try:
        page.evaluate("""pos => { window.__codexCursorPos = pos; }""", {"x": float(x), "y": float(y)})
    except Exception:
        pass


def humanized_scroll(
    terminal: BrowserTerminal,
    amount: int,
    *,
    box: dict | None = None,
    locator=None,
    corrective: bool = True,
) -> None:
    page = terminal.current_page()
    if box is None and locator is not None:
        try:
            box = locator.bounding_box(timeout=1500)
        except Exception:
            box = None
    if box:
        x = float(box["x"] + box["width"] * random.uniform(0.42, 0.58))
        y = float(box["y"] + box["height"] * random.uniform(0.32, 0.72))
    else:
        viewport = page.viewport_size or {"width": 1280, "height": 720}
        x = float(viewport.get("width", 1280)) * random.uniform(0.42, 0.62)
        y = float(viewport.get("height", 720)) * random.uniform(0.34, 0.72)
    if terminal.humanize:
        move_cursor_like_person(terminal, x, y, duration_factor=0.65, show_trail=terminal.visual_cursor)
        page.wait_for_timeout(random.randint(45, 150))

    total = int(amount)
    if total == 0:
        return
    direction = 1 if total > 0 else -1
    remaining = abs(total)
    segments = max(4, min(12, remaining // random.randint(95, 170) + random.randint(2, 4)))
    weights = []
    for index in range(int(segments)):
        t = (index + 0.5) / max(1, segments)
        weights.append(max(0.18, math.sin(math.pi * t) * random.uniform(0.65, 1.35)))
    weight_total = sum(weights) or 1.0
    steps = []
    allocated = 0
    for index, weight in enumerate(weights):
        if index == len(weights) - 1:
            step = remaining - allocated
        else:
            step = int(max(18, min(260, remaining * weight / weight_total)))
            allocated += step
        if step > 0:
            steps.append(step)
    moved = 0
    for index, step in enumerate(steps):
        if step <= 0:
            continue
        page.mouse.wheel(0, direction * step)
        moved += step
        if terminal.humanize and random.random() < 0.18:
            jitter_mouse(page)
        if terminal.humanize and random.random() < 0.16 and index not in {0, len(steps) - 1}:
            page.mouse.wheel(0, -direction * random.randint(8, max(10, min(48, step // 2))))
        page.wait_for_timeout(random.randint(55, 235))
    if corrective and moved > 160 and terminal.humanize and random.random() < 0.45:
        back = int(max(18, min(120, moved * random.uniform(0.05, 0.15))))
        page.mouse.wheel(0, -direction * back)
        page.wait_for_timeout(random.randint(65, 160))
        if random.random() < 0.75:
            page.mouse.wheel(0, direction * int(back * random.uniform(0.45, 0.85)))
            page.wait_for_timeout(random.randint(45, 130))
    if terminal.humanize and random.random() < 0.32:
        maybe_human_reading_pause(terminal, reason="page_change")


def jitter_mouse(page) -> None:
    try:
        viewport = page.viewport_size or {"width": 1280, "height": 720}
        pos = page.evaluate("() => window.__codexCursorPos || { x: innerWidth / 2, y: innerHeight / 2 }")
        x = float(pos.get("x", viewport["width"] / 2))
        y = float(pos.get("y", viewport["height"] / 2))
        for _ in range(random.randint(1, 2)):
            x = clamp(x + random.uniform(-55, 55), 12, viewport["width"] - 12)
            y = clamp(y + random.uniform(-35, 35), 12, viewport["height"] - 12)
            page.mouse.move(x, y, steps=random.randint(6, 16))
            page.evaluate("""pos => { window.__codexCursorPos = pos; }""", {"x": x, "y": y})
            page.wait_for_timeout(random.randint(60, 260))
    except Exception:
        return


def small_scroll_wander(target) -> None:
    try:
        if isinstance(target, BrowserTerminal):
            amount = random.randint(45, 160) * random.choice([1, -1])
            humanized_scroll(target, amount, corrective=random.random() < 0.65)
            return
        page = target
        amount = random.randint(45, 160) * random.choice([1, -1])
        page.mouse.wheel(0, amount)
        page.wait_for_timeout(random.randint(90, 310))
        if random.random() < 0.65:
            page.mouse.wheel(0, -int(amount * random.uniform(0.35, 0.9)))
            page.wait_for_timeout(random.randint(60, 210))
    except Exception:
        return


def clamp(value: float, low: float, high: float) -> float:
    return max(low, min(high, value))


def open_recommend_page_from_left_menu(terminal: BrowserTerminal) -> dict:
    page = terminal.current_page()
    current_url = str(page.url or "")
    if "/web/chat/recommend" in current_url:
        return {"opened": False, "mode": "already_on_recommend", "url": current_url}

    selectors = [
        'a[ka="menu-geek-recommend"]',
        'a[href*="/web/chat/recommend"]',
        '[ka="menu-geek-recommend"]',
    ]
    last_error = ""
    for selector in selectors:
        try:
            candidates = page.locator(selector)
            if candidates.count() <= 0:
                continue
            locator = candidates.first
            if terminal.humanize:
                terminal.pause_like_person("pre_action")
                highlight_target(locator)
            humanized_locator_click(terminal, locator, force=True)
            page.wait_for_timeout(random.randint(900, 1500))
            if "/web/chat/recommend" in str(page.url or "") or wait_for_recommend_frame(page, timeout_ms=4500):
                return {"opened": True, "mode": "left_menu_selector", "selector": selector, "url": str(page.url or "")}
        except Exception as error:
            last_error = safe_text(str(error), 160)

    try:
        text_locator = page.get_by_text("推荐牛人", exact=True)
        if text_locator.count() > 0:
            locator = text_locator.first
            if terminal.humanize:
                terminal.pause_like_person("pre_action")
                highlight_target(locator)
            humanized_locator_click(terminal, locator, force=True)
            page.wait_for_timeout(random.randint(900, 1500))
            if "/web/chat/recommend" in str(page.url or "") or wait_for_recommend_frame(page, timeout_ms=4500):
                return {"opened": True, "mode": "left_menu_text", "url": str(page.url or "")}
    except Exception as error:
        last_error = safe_text(str(error), 160)

    try:
        page.goto("https://www.zhipin.com/web/chat/recommend", wait_until="domcontentloaded")
        page.wait_for_timeout(random.randint(1200, 1900))
        return {
            "opened": True,
            "mode": "goto_fallback",
            "url": str(page.url or ""),
            "lastError": last_error,
        }
    except Exception as error:
        return {
            "opened": False,
            "mode": "failed",
            "url": current_url,
            "error": safe_text(str(error), 180),
            "lastError": last_error,
        }


def wait_for_recommend_frame(page, timeout_ms: int = 8000):
    deadline = time.time() + max(1, int(timeout_ms or 8000)) / 1000.0
    while time.time() < deadline:
        for frame in page.frames:
            if "/web/frame/recommend/" in str(frame.url or ""):
                return frame
        try:
            page.wait_for_timeout(280)
        except Exception:
            break
    return None


def wait_for_evaluate_condition(target, wait_page, script: str, timeout_ms: int = 1200, poll_ms: int = 120) -> dict:
    deadline = time.time() + max(0.05, int(timeout_ms or 0) / 1000.0)
    last_error = ""
    last_value = None
    while time.time() < deadline:
        try:
            result = target.evaluate(script)
            last_value = result
            if isinstance(result, dict) and result.get("matched"):
                return result
            if result is True:
                return {"matched": True, "reason": "condition_matched"}
        except Exception as error:
            last_error = safe_text(str(error), 120)
        remaining_ms = int(max(0, (deadline - time.time()) * 1000))
        if remaining_ms <= 0:
            break
        try:
            wait_page.wait_for_timeout(min(max(35, int(poll_ms or 120)), remaining_ms))
        except Exception:
            break
    return {
        "matched": False,
        "reason": "condition_timeout",
        "lastValue": last_value if isinstance(last_value, dict) else None,
        "error": last_error,
    }


def wait_for_recommend_resume_dialog_ready(page, frame, timeout_ms: int = 1200) -> dict:
    return wait_for_evaluate_condition(
        frame,
        page,
        """() => {
          const active = document.querySelector(".dialog-wrap.active");
          if (!active) return {matched: false, reason: "resume_dialog_not_open"};
          const text = String(active.innerText || active.textContent || "").replace(/\\s+/g, " ").trim();
          const hasGreet = !!active.querySelector("button.btn-greet,.resumeGreet button,.button-chat-wrap.resumeGreet button");
          const hasClose = !!active.querySelector(".close-btn");
          const hasResumePanel = !!active.querySelector(".resume-right-side,.resume-summary,.resume-simple-box,iframe");
          if (hasGreet || (hasClose && hasResumePanel) || text.length > 80) {
            return {matched: true, reason: "resume_dialog_ready", hasGreet, hasClose, textLength: text.length};
          }
          return {matched: false, reason: "resume_dialog_waiting", hasGreet, hasClose, textLength: text.length};
        }""",
        timeout_ms=timeout_ms,
        poll_ms=110,
    )


def wait_for_post_greet_surface(page, timeout_ms: int = 2200) -> dict:
    return wait_for_evaluate_condition(
        page,
        page,
        """() => {
          const visible = (el) => {
            if (!el || !el.isConnected) return false;
            const box = el.getBoundingClientRect();
            const style = window.getComputedStyle(el);
            return box.width > 6 && box.height > 6
              && style.display !== "none"
              && style.visibility !== "hidden"
              && style.opacity !== "0";
          };
          const normalize = (value) => String(value || "").replace(/\\s+/g, "").trim();
          for (const node of Array.from(document.querySelectorAll(".dialog-wrap.active button,.boss-dialog button,button,[role='button']"))) {
            if (!visible(node)) continue;
            const text = normalize(node.innerText || node.textContent || node.getAttribute("aria-label") || node.getAttribute("title") || "");
            if (text === "\\u77e5\\u9053\\u4e86" || text === "\\u6211\\u77e5\\u9053\\u4e86") {
              return {matched: true, reason: "post_greet_ack_visible", text};
            }
          }
          const active = document.querySelector(".dialog-wrap.active");
          const activeText = normalize(active ? active.innerText || active.textContent || "" : "");
          if (activeText.includes("\\u5df2\\u53d1\\u9001") || activeText.includes("\\u6253\\u62db\\u547c")) {
            return {matched: true, reason: "post_greet_dialog_visible", textLength: activeText.length};
          }
          return {matched: false, reason: active ? "waiting_post_greet_dialog" : "waiting_active_dialog"};
        }""",
        timeout_ms=timeout_ms,
        poll_ms=120,
    )


def read_recommend_frame_summary(frame) -> dict:
    try:
        return frame.evaluate(
            """() => {
              const text = document.body ? document.body.innerText || "" : "";
              const normalize = (value) => String(value || "").replace(/\\s+/g, " ").trim();
              const selectedNode = document.querySelector(".job-selecter-wrap .ui-dropmenu-label")
                || document.querySelector(".job-selecter-wrap .job-item.curr .label");
              const selectedPosition = normalize(selectedNode ? selectedNode.innerText || selectedNode.textContent || "" : "");
              const lines = text.split(/\\n+/).map((line) => line.trim()).filter(Boolean);
              let position = selectedPosition;
              for (const line of lines.slice(0, 16)) {
                if (position) break;
                if (/经理|工程师|销售|管培生|人力资源|HR|hrbp|实习生|应用技术|涂料/.test(line) && line.length <= 90) {
                  position = line;
                  break;
                }
              }
              const riskWords = ["验证码", "安全验证", "操作频繁", "账号异常", "系统繁忙", "请稍后", "限制"];
              const risk = riskWords.find((word) => text.includes(word)) || "";
              return {
                url: location.href,
                title: document.title,
                position: normalize(position),
                bodyPreview: text.slice(0, 1200),
                risk
              };
            }"""
        ) or {}
    except Exception as error:
        return {"error": str(error)}


def normalize_recommend_position(value: str) -> str:
    return re.sub(r"[\s_（）()·\-—|｜]+", "", str(value or "").lower())


def recommend_position_has_terms(value: str, terms: list[str]) -> bool:
    normalized = normalize_recommend_position(value)
    return all(normalize_recommend_position(term) in normalized for term in terms if term)


